INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C1','kor',5,1,'u3',1,'자료를 활용한 발표의 좋은 점 — 알맞은 자료가 있으면 내용을 이해하기 쉬워지고, 말로 설명하기 어려운 것을 보여 줄 수 있으며, 듣는 사람의 관심을 끌 수 있다',ARRAY['6국01-05 듣기·말하기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C2','kor',5,1,'u3',1,'내용과 상황에 맞는 매체 — 종이 자료와 화면 자료 가운데 늘 더 좋은 것이 있는 것이 아니라 전할 내용과 상황에 맞는 매체가 따로 있으며, 움직임이나 변화 과정은 영상이 잘 보여 준다',ARRAY['6국01-05 듣기·말하기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C3','kor',5,1,'u3',1,'대화할 때 알맞은 태도 — 말하는 사람은 듣는 사람이 이해할 수 있게 말하고, 듣는 사람은 집중해서 듣고 궁금한 점을 질문한다',ARRAY['6국01-03 듣기·말하기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C4','kor',5,1,'u3',1,'질문은 두 사람 모두에게 남는다 — 질문하는 사람은 궁금한 점을 해결하고, 질문을 받은 사람은 답하려고 자기 생각을 더 깊이 돌아보게 된다',ARRAY['6국01-03 듣기·말하기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C5','kor',5,1,'u3',1,'이 단원의 두 갈래 — 이 단원에서는 자료를 선별하여 발표하기와 궁금한 내용 질문하기를 배운다',ARRAY['6국01-05 듣기·말하기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C6','kor',5,1,'u3',2,'발표를 준비할 때 먼저 생각할 것 — 발표 주제 · 발표를 듣는 사람 · 발표 목적 · 활용할 매체를 먼저 생각하며, 듣는 사람이 누구인지에 따라 자료도 달라진다',ARRAY['6국01-05 듣기·말하기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C7','kor',5,1,'u3',2,'자료를 찾는 방법과 그 특징 — 책은 정리된 내용이 많으나 최신 정보가 적을 수 있고, 인터넷은 빠르고 양이 많으나 사실인지 확인해야 하며, 전문가에게 물으면 깊이 있는 답을 들을 수 있으나 만나기 어렵다. 직접 관찰 · 설문 조사 · 기관 찾아가기도 있다',ARRAY['6국06-01 매체']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C8','kor',5,1,'u3',2,'자료 유형 네 가지와 특성 — 글은 주제에 대한 자세한 설명을, 표나 그래프는 수치와 그 변화를 한눈에, 영상은 움직임이나 변화 과정을, 그림이나 사진은 대상의 특징을 강조해 보여 준다',ARRAY['6국01-05 듣기·말하기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C9','kor',5,1,'u3',2,'같은 내용도 유형에 따라 전해지는 정도가 다르다 — 수치의 변화를 글로만 전하면 듣는 사람이 크기를 가늠하기 어렵고, 그래프로 전하면 줄어든 정도와 속도가 한눈에 보인다',ARRAY['6국01-05 듣기·말하기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C10','kor',5,1,'u3',2,'믿을 수 있는 자료 찾기 — 인터넷에는 사실이 아닌 내용도 섞여 있으므로 같은 내용을 여러 곳에서 확인하고, 공공 기관 누리집을 활용하며, 조사하면서 출처를 함께 기록한다',ARRAY['6국06-01 매체']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C11','kor',5,1,'u3',2,'찾은 자료도 따져 보고 쓴다 — 표나 그래프는 눈금의 간격이 고른지와 수치가 과장되지 않았는지 확인하고, 영상은 전체가 아니라 발표에 꼭 필요한 부분만 골라 쓴다',ARRAY['6국06-01 매체']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C12','kor',5,1,'u3',3,'자료 선별의 뜻 — 자료 선별은 발표 내용을 더 효과적으로 전달할 수 있는 자료를 골라 선택하는 것이며, 찾은 자료를 그대로 다 쓰는 것이 아니다',ARRAY['6국01-05 듣기·말하기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C13','kor',5,1,'u3',3,'무엇을 보여 주려는지가 유형을 고르는 기준 — 발표 내용이 설명인지, 변화 과정인지, 생김새인지, 수치인지에 따라 그 내용을 가장 잘 살려 주는 자료 유형을 고른다',ARRAY['6국01-05 듣기·말하기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C14','kor',5,1,'u3',3,'유형에 정답이 하나로 정해진 것은 아니다 — 한 내용에 여러 유형이 어울릴 수 있어 글로 설명하며 사진을 함께 보여 주거나 영상 대신 사진 두 장을 나란히 둘 수도 있으며, 중요한 것은 유형의 이름이 아니라 자료가 내용을 잘 전하는가이다',ARRAY['6국01-05 듣기·말하기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C15','kor',5,1,'u3',3,'발표 내용에 필요한 부분 찾기 — 찾은 글 자료 가운데 발표 개요의 각 내용과 맞는 단락을 골라 쓴다',ARRAY['6국01-05 듣기·말하기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C16','kor',5,1,'u3',3,'글 자료는 요약한다 — 글 자료는 발표 내용에 꼭 필요한 것만 남겨 정리하고 요약하며, 글이 많으면 듣는 사람이 발표자를 보지 않고 화면만 읽게 된다',ARRAY['6국01-05 듣기·말하기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C17','kor',5,1,'u3',3,'주제와 관계없는 자료는 뺀다 — 멋있어 보이더라도 발표 주제와 이어지지 않는 자료는 빼야 한다',ARRAY['6국01-05 듣기·말하기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C18','kor',5,1,'u3',3,'어려운 말은 뜻을 지키며 쉬운 말로 — 듣는 사람이 어려워할 낱말은 이해하기 쉬운 말로 바꾸되 뜻이 달라지지 않게 하며, 「감소한다 → 사라진다」 · 「분해한다 → 없앤다」처럼 바꾸면 뜻이 어긋난다',ARRAY['6국01-05 듣기·말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C19','kor',5,1,'u3',3,'만든 자료를 검토하는 기준 — 주제에 맞는지 · 자료 유형의 특성이 잘 드러나는지 · 글의 양이 알맞은지 · 듣는 사람이 어려워할 말은 없는지 · 출처를 밝혔는지를 살핀다',ARRAY['6국01-05 듣기·말하기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C20','kor',5,1,'u3',3,'출처 밝히기 — 남이 만든 자료를 쓸 때에는 어디에서 가져왔는지를 자료 아래쪽에 적으며, 출처를 밝히면 만든 사람에 대한 예의가 되고 듣는 사람도 믿고 들을 수 있다',ARRAY['6국06-01 매체']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C21','kor',5,1,'u3',4,'발표의 차례 — 발표는 계획하기 → 자료 준비하기 → 발표하기 → 점검하기의 차례로 이어진다',ARRAY['6국01-05 듣기·말하기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C22','kor',5,1,'u3',4,'주제를 좁혀 가기 — 관심 있는 대상에서 발표하고 싶은 대상, 자세히 알려 주고 싶은 내용으로 좁혀 가며 발표 주제를 정한다',ARRAY['6국01-05 듣기·말하기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C23','kor',5,1,'u3',4,'알맞은 크기의 주제 — 발표 주제는 짧은 발표 시간 안에 다룰 수 있게 너무 넓지도 좁지도 않아야 자료를 모으기 좋다',ARRAY['6국01-05 듣기·말하기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C24','kor',5,1,'u3',4,'상황에 맞는 매체 정하기 — 사진 · 영상 · 그래프를 함께 보일 때는 화면 자료, 가까이서 자세히 보게 할 때는 종이 자료, 직접 만져 보게 할 때는 실물, 짧고 분명한 내용은 몸짓과 말이 알맞다',ARRAY['6국01-05 듣기·말하기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C25','kor',5,1,'u3',4,'발표 자료를 만들 때 — 한 화면에 한 가지 내용만 담고, 글은 요약해서 짧게 적고, 뒤쪽에서도 보이게 큰 글씨로 쓰고, 가져온 자료에는 출처를 적는다',ARRAY['6국01-05 듣기·말하기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C26','kor',5,1,'u3',4,'발표의 주인공은 발표자 — 발표의 주체는 발표하는 사람이고 자료는 말을 도와주는 보조이므로, 자료는 많을수록 좋은 것이 아니라 말로 전하기 어려운 곳에 있을 때 힘이 된다',ARRAY['6국01-05 듣기·말하기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C27','kor',5,1,'u3',4,'시작하는 말과 끝맺는 말 — 시작하는 말에는 무엇을 왜 발표하는지를, 끝맺는 말에는 마무리와 질문 안내를 담는다',ARRAY['6국01-05 듣기·말하기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C28','kor',5,1,'u3',4,'예상 질문 준비하기 — 발표 내용과 자료에서 나올 법한 질문과 답을 미리 만들어 보면 발표 내용의 빈 곳이 먼저 보인다',ARRAY['6국01-05 듣기·말하기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C29','kor',5,1,'u3',4,'발표 과정 점검하고 친구에게 배우기 — 알맞은 자료를 선별했는지 · 효과적인 유형을 골랐는지 · 자신 있게 발표했는지 · 질문에 성의 있게 답했는지 점검하고, 친구 발표에서 좋았던 점과 아쉬웠던 점을 함께 정리한다',ARRAY['6국01-05 듣기·말하기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C30','kor',5,1,'u3',7,'주의 깊게 들어야 질문이 생긴다 — 질문은 아무 때나 떠오르지 않으며 다른 사람의 말을 집중해서 들어야 궁금한 곳이 보인다',ARRAY['6국01-03 듣기·말하기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C31','kor',5,1,'u3',7,'제안과 제안한 까닭 — 회의에서 제안하는 사람은 무엇을 문제라고 보았는지 까닭을 함께 말하므로, 들을 때 제안과 까닭을 짝지어 듣는다',ARRAY['6국01-03 듣기·말하기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C32','kor',5,1,'u3',7,'질문의 세 가지 목적 — 질문에는 의도를 파악하기 위한 질문 · 명료하게 이해하기 위한 질문 · 대안이나 정보를 찾기 위한 질문이 있다',ARRAY['6국01-03 듣기·말하기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C33','kor',5,1,'u3',7,'의도를 파악하는 질문 — 「이 규칙으로 어떤 문제를 해결하고 싶은가요?」처럼 상대가 왜 그렇게 말했는지 알고 싶을 때 하는 질문이다',ARRAY['6국01-03 듣기·말하기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C34','kor',5,1,'u3',7,'명료하게 이해하는 질문 — 「나눔 시간은 물건을 나누는 건가요, 이야기를 나누는 건가요?」처럼 뜻이 흐릿해 또렷이 하고 싶을 때 하는 질문이다',ARRAY['6국01-03 듣기·말하기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C35','kor',5,1,'u3',7,'대안이나 정보를 찾는 질문 — 「계속 별명을 부르면 어떻게 하나요?」 · 「더 알려면 어떤 자료를 찾아보면 좋을까요?」처럼 다른 방법이나 더 알 것을 구할 때 하는 질문이다',ARRAY['6국01-03 듣기·말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C36','kor',5,1,'u3',7,'질문을 여는 말 — 누가 · 언제 · 어디에서는 사실을 또렷이 할 때, 무엇을 · 어떻게는 내용과 방법을 물을 때, 왜는 까닭과 의도를 물을 때, 만약은 다른 경우를 짚어 볼 때 쓴다',ARRAY['6국01-03 듣기·말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C37','kor',5,1,'u3',7,'분명한 표현으로 묻기 — 「그거 좀 이상하지 않아요?」처럼 흐릿하게 묻지 않고 무엇을 알고 싶은지 분명하게 표현해야 답하는 사람도 질문의 목적을 알고 알맞게 답할 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C38','kor',5,1,'u3',7,'내용과 이어지고 예의 있는 질문 — 회의나 발표에서는 나온 내용과 이어지는 질문을 하며, 「그 의견은 왜 그렇게 별로인가요?」처럼 상대를 깎아내리는 말은 질문이 아니다',ARRAY['6국01-03 듣기·말하기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C39','kor',5,1,'u3',7,'갈래를 맞히는 것이 목적이 아니다 — 질문은 맥락에 따라 여러 갈래로 나눌 수 있고 한 질문이 두 목적에 걸치기도 하므로, 갈래를 맞히는 것보다 내가 무엇을 알고 싶은지 생각하고 묻는 것이 중요하다',ARRAY['6국01-03 듣기·말하기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C40','kor',5,1,'u3',9,'까닭이 적히지 않은 행동에서 질문이 생긴다 — 이야기에는 까닭이 다 적히지 않은 행동이 있고, 그럴 때 읽는 사람은 인물에게 묻고 싶어진다',ARRAY['6국01-03 듣기·말하기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C41','kor',5,1,'u3',9,'인물의 말과 행동에서 단서 모으기 — 인물이 까닭을 말하지 않을 때에는 되풀이하는 행동과 짧은 말을 단서로 모아 마음을 짐작하며, 배경 설명은 마음의 단서가 아닐 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C42','kor',5,1,'u3',9,'이야기 흐름 간추리기 — 일이 일어난 차례대로 중요한 사건을 간추리면 인물의 마음이 어떻게 달라졌는지 보이고 질문할 곳이 드러난다',ARRAY['6국01-03 듣기·말하기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C43','kor',5,1,'u3',9,'누구에게 무엇을 물을지 정하기 — 인물의 말과 행동에서 이해가 안 되거나 더 또렷이 알고 싶은 것을 중심으로, 어느 인물에게 물을지와 질문의 목적을 정해 질문을 만든다',ARRAY['6국01-03 듣기·말하기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C44','kor',5,1,'u3',9,'이야기 안에서 생각해 볼 수 있는 질문 — 좋은 질문은 이야기 속에서 답을 찾거나 생각해 볼 수 있는 질문이며, 국수 값이나 골목 이름처럼 이야기와 관계없는 사실을 묻는 것은 알맞지 않다',ARRAY['6국01-03 듣기·말하기']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C45','kor',5,1,'u3',9,'인물이 되어 근거를 들어 답하기 — 인물이 되어 답하는 사람은 이야기에 나온 말과 행동을 근거로 답한다',ARRAY['6국01-03 듣기·말하기']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C46','kor',5,1,'u3',9,'이야기를 나와 관련짓기 — 누군가 나를 위해 말없이 해 준 일이나 내가 까닭을 말하지 않고 한 일을 떠올려 인물의 마음과 이어 본다',ARRAY['6국01-03 듣기·말하기']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C47','kor',5,1,'u3',11,'조사하고 발표하는 활동의 차례 — 관심 있는 주제 정하기 → 매체로 조사하기 → 필요한 자료 선별하기 → 발표 자료 만들기 → 발표하기 → 질문 주고받기의 차례로 한다',ARRAY['6국01-05 듣기·말하기']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C48','kor',5,1,'u3',11,'조사할 만한 주제 — 믿을 만한 자료를 구할 수 있고 친구들에게 도움이 되는 주제를 고르며, 친구의 집안 사정처럼 남의 사정이나 아무도 모르는 미래의 일은 알맞지 않다',ARRAY['6국06-01 매체']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C49','kor',5,1,'u3',11,'알고 싶은 것에 맞는 조사 방법 — 우리 학교 앞의 실제 모습은 직접 관찰, 어른들의 기억은 면담, 나라 전체의 수치는 공공 기관 누리집처럼 그 답이 있을 곳에 맞는 방법을 고른다',ARRAY['6국06-01 매체']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C50','kor',5,1,'u3',11,'더 믿을 수 있는 자료 — 누가 썼는지 알 수 없는 게시글이나 전해 들은 이야기보다 만든 곳과 낸 때가 드러난 책임 있는 곳의 자료가 더 믿을 수 있다',ARRAY['6국06-01 매체']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C51','kor',5,1,'u3',11,'질문이 오갈 때 발표가 완성된다 — 발표를 들으며 발표 내용 · 활용한 자료 · 자료를 만든 과정에 대해 질문할 수 있고, 질문의 목적을 정하고 분명하게 묻는다',ARRAY['6국01-03 듣기·말하기']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C52','kor',5,1,'u3',11,'두 소단원은 이어져 있다 — 자료를 선별해 발표하는 사람은 예상 질문을 준비하고, 듣는 사람은 그 자료와 내용을 집중해 들어 질문하므로 발표하기와 질문하기는 한 짝이다',ARRAY['6국01-03 듣기·말하기']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C53','kor',5,1,'u3',11,'낱말에 담긴 태도 — 비슷한 뜻의 낱말이라도 담고 있는 태도가 다르므로 낱말을 고를 때 차별이나 낮추는 뜻은 없는지, 약자를 배려했는지 생각한다 (기초 다지기)',ARRAY['기초 다지기(낱말 고르기)']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C54','kor',5,1,'u3',11,'반려 · 협력 — 즐기는 대상으로 보는 「애완」보다 짝이 되는 동무로 보는 「반려」가, 아래에서 일을 맡는다는 「하청」보다 힘을 합하여 돕는다는 「협력」이 함께함을 담은 바람직한 말이다 (기초 다지기)',ARRAY['기초 다지기(낱말 고르기)']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u3-C55','kor',5,1,'u3',11,'주변에서 고쳐 쓸 말 찾기 — 「살색」은 한 가지 피부색만 가리켜 「살구색」으로, 「학부형」은 아버지와 형만 가리켜 「학부모」로 고쳐 쓰는 것처럼 누군가를 빠뜨리거나 낮추는 말을 찾아 고친다 (기초 다지기)',ARRAY['기초 다지기(낱말 고르기)']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X01','kor',5,'u3',ARRAY['K5-1-u3-C1']::text[],'자료를 쓰면 발표 준비를 하지 않아도 되거나 발표 시간을 없앨 수 있다고 여긴다','자료는 말을 도와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X02','kor',5,'u3',ARRAY['K5-1-u3-C2']::text[],'한 가지 매체가 늘 더 좋다고 여기거나 변화 과정이 아닌 것에 영상을 고른다','내용과 상황에 맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X03','kor',5,'u3',ARRAY['K5-1-u3-C3']::text[],'듣는 사람은 모르는 것도 아는 척 넘어가거나 말하는 도중에 끼어들어도 된다고 여긴다','집중해서 듣고 질문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X04','kor',5,'u3',ARRAY['K5-1-u3-C4']::text[],'질문은 묻는 사람에게만 도움이 되거나 점수를 받으려고 하는 것이라고 여긴다','답하는 사람도 돌아봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X05','kor',5,'u3',ARRAY['K5-1-u3-C6']::text[],'발표를 준비할 때 주제만 정하면 된다고 여겨 듣는 사람 · 목적 · 매체를 생각하지 않는다','네 가지를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X06','kor',5,'u3',ARRAY['K5-1-u3-C7']::text[],'인터넷 자료는 늘 사실이라거나 책에는 최신 정보가 가장 많다고 여겨 조사 방법의 특징을 뒤바꿔 안다','방법마다 얻는 것이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X07','kor',5,'u3',ARRAY['K5-1-u3-C8']::text[],'자료 유형과 그 특성을 서로 뒤섞어 안다','무엇을 가장 잘 보여 주나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X08','kor',5,'u3',ARRAY['K5-1-u3-C9']::text[],'수치의 변화도 글로만 전하면 듣는 사람이 충분히 가늠할 수 있다고 여긴다','한눈에 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X09','kor',5,'u3',ARRAY['K5-1-u3-C10']::text[],'인터넷에서 찾은 내용을 한 곳만 보고 그대로 믿고 출처도 적지 않는다','여러 곳 확인 · 출처 기록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X10','kor',5,'u3',ARRAY['K5-1-u3-C11']::text[],'그래프의 눈금 간격이나 과장은 따지지 않고, 영상은 처음부터 끝까지 다 틀어야 한다고 여긴다','따져 보고 골라 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X11','kor',5,'u3',ARRAY['K5-1-u3-C12']::text[],'찾은 자료는 많이 넣을수록 좋다고 여겨 고르지 않고 그대로 다 쓴다','고르는 것이 선별') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X12','kor',5,'u3',ARRAY['K5-1-u3-C13']::text[],'발표 내용이 무엇을 보여 주려는지 따지지 않고 자료 유형을 고른다','설명 · 변화 · 생김새 · 수치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X13','kor',5,'u3',ARRAY['K5-1-u3-C14']::text[],'한 발표 내용에는 정해진 자료 유형 하나만 써야 한다고 여긴다','여러 유형도 어울려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X14','kor',5,'u3',ARRAY['K5-1-u3-C15']::text[],'발표 개요의 내용과 맞지 않는 단락을 필요한 부분으로 고른다','개요와 맞추어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X15','kor',5,'u3',ARRAY['K5-1-u3-C16']::text[],'글 자료를 요약하지 않고 그대로 옮겨 화면을 글로 가득 채운다','필요한 것만 남겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X16','kor',5,'u3',ARRAY['K5-1-u3-C17']::text[],'멋있어 보이면 주제와 관계없는 자료도 발표에 넣는다','주제와 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X17','kor',5,'u3',ARRAY['K5-1-u3-C18']::text[],'어려운 말을 쉬운 말로 바꾸면서 「감소한다 → 사라진다」처럼 뜻까지 바꾼다','뜻은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X18','kor',5,'u3',ARRAY['K5-1-u3-C19']::text[],'만든 자료를 검토할 때 글씨 색이나 꾸밈만 보고 내용 · 글의 양 · 출처는 살피지 않는다','듣는 사람의 처지에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X19','kor',5,'u3',ARRAY['K5-1-u3-C20']::text[],'남이 만든 사진이나 글을 출처 없이 내 것처럼 쓴다','이름표를 달아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X20','kor',5,'u3',ARRAY['K5-1-u3-C21']::text[],'계획 없이 바로 발표하거나 점검을 발표보다 먼저 하는 것처럼 발표의 차례를 뒤섞는다','계획 → 준비 → 발표 → 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X21','kor',5,'u3',ARRAY['K5-1-u3-C22']::text[],'「바다」 · 「음식」처럼 관심 있는 대상을 좁히지 않고 그대로 발표 주제로 삼는다','차례로 좁혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X22','kor',5,'u3',ARRAY['K5-1-u3-C23']::text[],'「지구의 모든 바다」처럼 너무 넓거나 「어제 본 게 한 마리의 크기」처럼 너무 좁은 주제를 고른다','시간 안에 다룰 크기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X23','kor',5,'u3',ARRAY['K5-1-u3-C24']::text[],'전하려는 상황과 맞지 않는 매체를 고른다','듣는 사람이 무엇을 해야 하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X24','kor',5,'u3',ARRAY['K5-1-u3-C25']::text[],'한 화면에 여러 내용을 빽빽하게 담고 작은 글씨로 쓴다','한 화면에 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X25','kor',5,'u3',ARRAY['K5-1-u3-C26']::text[],'자료가 많을수록 좋은 발표라고 여겨 발표자는 화면을 읽기만 한다','주인공은 발표자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X26','kor',5,'u3',ARRAY['K5-1-u3-C27']::text[],'시작하는 말에 무엇을 왜 발표하는지 밝히지 않고 핑계를 대거나 바로 본론으로 들어가며, 끝맺는 말에서 질문 안내를 빠뜨린다','무엇을 왜 · 마무리와 질문 안내') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X27','kor',5,'u3',ARRAY['K5-1-u3-C28']::text[],'예상 질문은 준비할 필요가 없다고 여기거나 발표와 관계없는 질문을 예상 질문으로 고른다','빈 곳이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X28','kor',5,'u3',ARRAY['K5-1-u3-C29']::text[],'발표를 마치면 돌아볼 것이 없다고 여기거나 친구 발표에서 좋은 점이나 아쉬운 점 한쪽만 말한다','점검 · 좋은 점과 아쉬운 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X29','kor',5,'u3',ARRAY['K5-1-u3-C30']::text[],'질문은 귀 기울여 듣지 않아도 저절로 떠오른다고 여긴다','들어야 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X30','kor',5,'u3',ARRAY['K5-1-u3-C31']::text[],'제안과 그 제안을 한 까닭을 엉뚱하게 짝짓는다','무엇을 문제로 보았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X31','kor',5,'u3',ARRAY['K5-1-u3-C32','K5-1-u3-C33']::text[],'상대가 왜 그렇게 말했는지 묻는 질문을 다른 목적의 질문으로 여긴다','까닭 · 의도를 묻나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X32','kor',5,'u3',ARRAY['K5-1-u3-C32','K5-1-u3-C34']::text[],'흐릿한 뜻을 또렷이 하려는 질문을 다른 목적의 질문으로 여긴다','뜻을 또렷이 하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X33','kor',5,'u3',ARRAY['K5-1-u3-C32','K5-1-u3-C35']::text[],'다른 방법이나 더 알 것을 구하는 질문을 다른 목적의 질문으로 여긴다','새로 구하는 것이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X34','kor',5,'u3',ARRAY['K5-1-u3-C36']::text[],'「만약」을 사실을 또렷이 할 때 쓰는 것처럼 질문을 여는 말의 쓰임을 헷갈린다','만약 = 다른 경우') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X35','kor',5,'u3',ARRAY['K5-1-u3-C37']::text[],'「그거 좀 이상하지 않아요?」처럼 무엇을 알고 싶은지 흐릿하게 묻는다','무엇이 궁금한지 또렷이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X36','kor',5,'u3',ARRAY['K5-1-u3-C38']::text[],'회의나 발표와 관계없는 것을 묻거나 상대를 깎아내리는 말을 질문으로 여긴다','내용과 이어지게 · 예의 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X37','kor',5,'u3',ARRAY['K5-1-u3-C39']::text[],'한 질문은 반드시 한 갈래에만 들어가고 갈래를 맞히는 것이 질문 공부의 목적이라고 여긴다','무엇을 알고 싶은가가 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X38','kor',5,'u3',ARRAY['K5-1-u3-C40']::text[],'까닭이 적히지 않은 인물의 행동을 궁금해하지 않고 그냥 넘긴다','왜 그랬을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X39','kor',5,'u3',ARRAY['K5-1-u3-C41']::text[],'「골목 끝에 있다」 · 「눈이 내렸다」 같은 배경을 인물 마음의 단서로 고른다','인물의 말과 행동을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X40','kor',5,'u3',ARRAY['K5-1-u3-C42']::text[],'이야기의 흐름을 간추릴 때 사건의 차례를 뒤섞는다','일어난 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X41','kor',5,'u3',ARRAY['K5-1-u3-C43']::text[],'누구에게 묻는지와 무엇이 궁금한지를 정하지 않고 질문을 만든다','어느 인물에게 · 무엇을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X42','kor',5,'u3',ARRAY['K5-1-u3-C44']::text[],'국수 값이나 골목 이름처럼 이야기와 관계없는 사실을 묻는 질문을 좋은 질문으로 고른다','이야기 안에서 생각해 볼 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X43','kor',5,'u3',ARRAY['K5-1-u3-C45']::text[],'인물이 되어 답할 때 이야기에 나온 말과 행동과 상관없이 마음대로 답한다','이야기 속 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X44','kor',5,'u3',ARRAY['K5-1-u3-C46']::text[],'이야기 속 일은 내 생활과 관계없다고 여겨 나와 관련지어 보지 않는다','나에게도 그런 일이?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X45','kor',5,'u3',ARRAY['K5-1-u3-C47']::text[],'조사하고 발표하는 활동에서 조사도 하기 전에 자료를 만드는 것처럼 차례를 뒤섞는다','주제 → 조사 → 선별 → 자료 → 발표 → 질문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X46','kor',5,'u3',ARRAY['K5-1-u3-C48']::text[],'친구의 집안 사정이나 아무도 모르는 미래의 일처럼 알맞지 않은 것을 조사 주제로 고른다','자료가 있나 · 도움이 되나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X47','kor',5,'u3',ARRAY['K5-1-u3-C49']::text[],'알고 싶은 것과 맞지 않는 조사 방법을 고른다','답이 어디에 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X48','kor',5,'u3',ARRAY['K5-1-u3-C50']::text[],'누가 썼는지 알 수 없는 글이나 전해 들은 이야기를 믿을 수 있는 자료로 여긴다','만든 곳과 때') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X49','kor',5,'u3',ARRAY['K5-1-u3-C51']::text[],'발표가 끝나면 질문은 필요 없다고 여기거나 발표 내용만 물을 수 있다고 여긴다','내용 · 자료 · 만든 과정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X50','kor',5,'u3',ARRAY['K5-1-u3-C52']::text[],'자료를 선별해 발표하기와 질문하며 듣기를 서로 관계없는 따로 떨어진 공부로 여긴다','발표와 질문은 한 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X51','kor',5,'u3',ARRAY['K5-1-u3-C53']::text[],'뜻만 비슷하면 어느 낱말을 써도 똑같다고 여겨 낱말에 담긴 태도를 살피지 않는다','누구를 어떻게 부르나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X52','kor',5,'u3',ARRAY['K5-1-u3-C54']::text[],'「반려」 대신 「애완」을, 「협력」 대신 「하청」을 바람직한 말로 고른다','함께함을 담은 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u3-X53','kor',5,'u3',ARRAY['K5-1-u3-C55']::text[],'「살색」 · 「학부형」처럼 누군가를 빠뜨리는 말을 고칠 필요가 없다고 여긴다','빠뜨리는 사람은 없나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#1','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C1',1,'mc','auto','자료를 활용해 발표하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X01','K5-1-u3-X25']::text[],false,'{"seq":1,"concept":"K5-1-u3-C1","difficulty":1,"kind":"mc","stem":"자료를 활용해 발표하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"내용을 이해하기 쉬워진다","correct":true},{"t":"발표 시간을 없앨 수 있다","mis":"K5-1-u3-X01"},{"t":"준비를 하지 않아도 된다","mis":"K5-1-u3-X01"},{"t":"발표하는 사람이 말을 한마디도 하지 않아도 된다","mis":"K5-1-u3-X25"}],"explanation":["발표 시간은 그대로 있어요.","자료도 준비가 필요해요.","자료는 말이 닿지 못하는 곳을 채워 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#2','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C2',1,'mc','auto','영상 자료를 쓰면 특히 좋은 경우는 어느 것인가요?',ARRAY['K5-1-u3-X02','K5-1-u3-X07']::text[],false,'{"seq":2,"concept":"K5-1-u3-C2","difficulty":1,"kind":"mc","stem":"영상 자료를 쓰면 특히 좋은 경우는 어느 것인가요?","options":[{"t":"밀물이 들어오는 변화 과정을 보일 때","correct":true},{"t":"낱말의 뜻을 풀이할 때","mis":"K5-1-u3-X02"},{"t":"해마다 달라진 수치를 견줄 때","mis":"K5-1-u3-X07"},{"t":"짱뚱어의 생김새를 한 장으로 보일 때","mis":"K5-1-u3-X02"}],"explanation":["뜻 풀이는 글이 알맞아요.","수치는 표나 그래프가 알맞아요.","움직임이나 변화 과정은 영상이 잘 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#3','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C3',1,'mc','auto','시온이가 대화에서 보인 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X03','K5-1-u3-X29']::text[],false,'{"seq":3,"concept":"K5-1-u3-C3","difficulty":1,"kind":"mc","stem":"시온이가 대화에서 보인 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"집중해서 듣고 궁금한 점을 질문했다","correct":true},{"t":"모르는 것도 아는 척하고 넘어갔다","mis":"K5-1-u3-X03"},{"t":"주아의 말 도중에 끼어들었다","mis":"K5-1-u3-X03"},{"t":"주아의 말을 듣지 않고 자기 이야기만 했다","mis":"K5-1-u3-X29"}],"explanation":["시온이는 궁금한 것을 물었어요.","주아의 말이 끝난 뒤 물었어요.","들은 내용에서 질문이 나왔어요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"너 무슨 책 읽어?"},{"who":"주아","text":"조선 시대 과학 기술에 대한 책을 읽고 있어."},{"who":"시온","text":"아, 그렇구나. 그 시대에는 어떤 기술이 있었어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#4','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C4',1,'ox','auto','질문을 받은 사람도 질문 덕분에 얻는 것이 있어요.',ARRAY['K5-1-u3-X04']::text[],false,'{"seq":4,"concept":"K5-1-u3-C4","difficulty":1,"kind":"ox","stem":"질문을 받은 사람도 질문 덕분에 얻는 것이 있어요.","answer":"O","reason_options":[{"t":"답하려면 자기 생각을 다시 정리하며 더 깊이 돌아보게 되기 때문에","correct":true},{"t":"질문은 묻는 사람에게만 도움이 되기 때문에","mis":"K5-1-u3-X04"}],"mis":"K5-1-u3-X04","explanation":["답하는 쪽도 남는 것이 있어요.","생각을 다시 정리하게 돼요.","질문은 두 사람 모두에게 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#5','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C5',2,'mc','auto','이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u3-X11','K5-1-u3-X29','K5-1-u3-X50']::text[],false,'{"seq":5,"concept":"K5-1-u3-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"자료를 선별하여 발표하기 · 궁금한 내용 질문하기","correct":true},{"t":"자료를 많이 모아 발표하기 · 질문 피하기","mis":"K5-1-u3-X11"},{"t":"말로만 발표하기 · 조용히 듣기","mis":"K5-1-u3-X29"},{"t":"발표하기 · 질문하기를 서로 다른 날 따로 익히기","mis":"K5-1-u3-X50"}],"explanation":["많이 모으는 것보다 골라야 해요.","듣는 사람도 질문해요.","두 갈래는 발표와 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#6','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C1',2,'mc','auto','듣는 사람이 갯벌 생물에 대해 질문할 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X01','K5-1-u3-X29','K5-1-u3-X26']::text[],false,'{"seq":6,"concept":"K5-1-u3-C1","difficulty":2,"kind":"mc","stem":"듣는 사람이 갯벌 생물에 대해 질문할 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"발표하는 사람이 사진 자료로 갯벌 생물을 보여 주었기 때문이다","correct":true},{"t":"발표 시간이 짧았기 때문이다","mis":"K5-1-u3-X01"},{"t":"듣는 사람이 그 내용을 미리 다 알고 있었기 때문이다","mis":"K5-1-u3-X29"},{"t":"발표하는 사람이 질문하지 말라고 했기 때문이다","mis":"K5-1-u3-X26"}],"explanation":["시간과는 관계없어요.","다 알았다면 묻지 않았겠지요.","사진을 보고 궁금한 점이 생겼어요."],"asset":{"type":"speech","turns":[{"who":"발표","text":"이상으로 우리 지역 갯벌에 대한 발표를 마치겠습니다. 질문이 있으면 손을 들어 주세요."},{"who":"듣는이","text":"갯벌 생물을 설명할 때 보여 주신 사진에서 궁금한 점을 질문하겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#7','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C2',2,'mc','auto','종이 자료와 화면 자료에 대해 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-1-u3-X02','K5-1-u3-X23']::text[],false,'{"seq":7,"concept":"K5-1-u3-C2","difficulty":2,"kind":"mc","stem":"종이 자료와 화면 자료에 대해 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"전할 내용과 상황에 맞는 매체가 따로 있다","correct":true},{"t":"화면 자료가 언제나 종이 자료보다 낫다","mis":"K5-1-u3-X02"},{"t":"종이 자료는 이제 쓸모가 없다","mis":"K5-1-u3-X02"},{"t":"매체는 아무것이나 골라도 똑같다","mis":"K5-1-u3-X23"}],"explanation":["늘 더 좋은 매체는 없어요.","종이 자료가 알맞을 때도 있어요.","내용과 상황에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#8','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C4',2,'mc','auto','질문을 받은 사람에게 생기는 좋은 점은 어느 것인가요?',ARRAY['K5-1-u3-X04']::text[],false,'{"seq":8,"concept":"K5-1-u3-C4","difficulty":2,"kind":"mc","stem":"질문을 받은 사람에게 생기는 좋은 점은 어느 것인가요?","options":[{"t":"자신의 생각을 더 깊이 돌아보게 된다","correct":true},{"t":"발표를 빨리 끝낼 수 있다","mis":"K5-1-u3-X04"},{"t":"점수를 더 받을 수 있다","mis":"K5-1-u3-X04"},{"t":"다시는 질문을 받지 않게 된다","mis":"K5-1-u3-X04"}],"explanation":["빨리 끝내려는 것이 아니에요.","점수와는 관계없어요.","답하려면 생각을 다시 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#9','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C3',2,'mc','auto','시온이처럼 대화를 이어 가려면 어떻게 하면 좋을까요?',ARRAY['K5-1-u3-X03','K5-1-u3-X29']::text[],false,'{"seq":9,"concept":"K5-1-u3-C3","difficulty":2,"kind":"mc","stem":"시온이처럼 대화를 이어 가려면 어떻게 하면 좋을까요?","options":[{"t":"상대의 말을 집중해서 듣고 궁금한 점을 묻는다","correct":true},{"t":"상대가 말할 때 다른 책을 펼쳐 본다","mis":"K5-1-u3-X03"},{"t":"잘 몰라도 아는 척 고개만 끄덕인다","mis":"K5-1-u3-X03"},{"t":"질문은 대화를 끊으니 하지 않는다","mis":"K5-1-u3-X29"}],"explanation":["집중하지 않으면 궁금한 곳이 안 보여요.","아는 척하면 대화가 멈춰요.","질문이 대화를 이어 줘요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"너 무슨 책 읽어?"},{"who":"주아","text":"조선 시대 과학 기술에 대한 책을 읽고 있어."},{"who":"시온","text":"아, 그렇구나. 그 시대에는 어떤 기술이 있었어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_basic#10','kor',5,1,'u3','L01','g5_1_kor_u3_L01_basic','lesson_basic','K5-1-u3-C1',3,'match','auto','말로만 전하기 어려운 내용과 그것을 보여 줄 자료를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C1","difficulty":3,"kind":"match","stem":"말로만 전하기 어려운 내용과 그것을 보여 줄 자료를 이으세요.","pairs":[{"l":"밀물이 들어오는 과정","r":"영상"},{"l":"해마다 달라진 갯벌 면적","r":"그래프"},{"l":"짱뚱어의 생김새","r":"사진"}],"mis":"K5-1-u3-X07","explanation":["움직임은 영상이에요.","수치의 변화는 그래프예요.","생김새는 사진이 잘 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#1','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C1',2,'ox','auto','자료를 준비하면 발표하는 사람은 말을 줄이고 자료만 보여 주면 돼요.',ARRAY['K5-1-u3-X25']::text[],false,'{"seq":1,"concept":"K5-1-u3-C1","difficulty":2,"kind":"ox","stem":"자료를 준비하면 발표하는 사람은 말을 줄이고 자료만 보여 주면 돼요.","answer":"X","reason_options":[{"t":"자료는 말로 설명하기 어려운 곳을 채워 줄 뿐이고 설명은 발표하는 사람이 하기 때문에","correct":true},{"t":"자료가 있으면 말은 필요 없기 때문에","mis":"K5-1-u3-X25"}],"mis":"K5-1-u3-X25","explanation":["자료는 말을 도와요.","설명하는 사람은 발표자예요.","말과 자료가 함께 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#2','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C3',2,'mc','auto','시온이의 마지막 말 「그 시대에는 어떤 기술이 있었어?」가 한 일은 무엇인가요?',ARRAY['K5-1-u3-X03','K5-1-u3-X29','K5-1-u3-X36']::text[],false,'{"seq":2,"concept":"K5-1-u3-C3","difficulty":2,"kind":"mc","stem":"시온이의 마지막 말 「그 시대에는 어떤 기술이 있었어?」가 한 일은 무엇인가요?","options":[{"t":"주아의 말을 듣고 생긴 궁금한 점을 물어 대화를 이어 갔다","correct":true},{"t":"주아의 말을 끊고 다른 이야기로 넘어갔다","mis":"K5-1-u3-X03"},{"t":"주아의 말을 듣지 않고 미리 준비한 말을 했다","mis":"K5-1-u3-X29"},{"t":"주아를 놀리려고 한 말이다","mis":"K5-1-u3-X36"}],"explanation":["주아의 말이 끝난 뒤 물었어요.","주아가 한 말에서 나온 질문이에요.","들은 것에서 궁금한 곳을 찾았어요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"너 무슨 책 읽어?"},{"who":"주아","text":"조선 시대 과학 기술에 대한 책을 읽고 있어."},{"who":"시온","text":"아, 그렇구나. 그 시대에는 어떤 기술이 있었어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#3','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C2',3,'mc','auto','발표 내용과 매체를 가장 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u3-X02','K5-1-u3-X08','K5-1-u3-X23']::text[],false,'{"seq":3,"concept":"K5-1-u3-C2","difficulty":3,"kind":"mc","stem":"발표 내용과 매체를 가장 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"갯벌에 물이 차오르는 과정 — 화면에 띄운 영상","correct":true},{"t":"「갯벌」이라는 낱말의 뜻 — 화면에 띄운 영상","mis":"K5-1-u3-X02"},{"t":"해마다 줄어든 면적 — 소리 내어 읽는 긴 글","mis":"K5-1-u3-X08"},{"t":"짱뚱어의 생김새 — 몸짓으로 흉내 내기","mis":"K5-1-u3-X23"}],"explanation":["뜻 풀이에 영상은 맞지 않아요.","수치의 변화는 그래프가 좋아요.","변화 과정은 영상이 잘 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#4','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C4',3,'mc','auto','듣는이의 질문을 받은 발표자가 얻을 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X04','K5-1-u3-X01']::text[],false,'{"seq":4,"concept":"K5-1-u3-C4","difficulty":3,"kind":"mc","stem":"듣는이의 질문을 받은 발표자가 얻을 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌 생물에 대해 자기가 아는 것을 다시 정리해 볼 수 있다","correct":true},{"t":"발표를 더 빨리 끝낼 수 있다","mis":"K5-1-u3-X04"},{"t":"질문한 사람보다 점수를 더 받을 수 있다","mis":"K5-1-u3-X04"},{"t":"다음 발표를 준비하지 않아도 된다","mis":"K5-1-u3-X01"}],"explanation":["질문은 시간을 줄이려는 것이 아니에요.","점수와는 관계없어요.","답하며 생각을 돌아봐요."],"asset":{"type":"speech","turns":[{"who":"발표","text":"이상으로 우리 지역 갯벌에 대한 발표를 마치겠습니다. 질문이 있으면 손을 들어 주세요."},{"who":"듣는이","text":"갯벌 생물을 설명할 때 보여 주신 사진에서 궁금한 점을 질문하겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#5','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C3',3,'error','auto','대화할 때의 태도에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X03','K5-1-u3-X29']::text[],false,'{"seq":5,"concept":"K5-1-u3-C3","difficulty":3,"kind":"error","stem":"대화할 때의 태도에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘 모르겠으면 아는 척하고 넘어가는 게 예의야.」","correct":true,"mis_target":"K5-1-u3-X03"},{"t":"「듣는 사람이 이해할 수 있게 말해야 해.」","mis":"K5-1-u3-X03"},{"t":"「궁금한 점은 질문하는 게 좋아.」","mis":"K5-1-u3-X29"}],"explanation":["말하는 쪽의 태도로 맞아요.","듣는 쪽의 태도로 맞아요.","모르면 질문해야 대화가 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#6','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C5',3,'mc','auto','이 단원의 두 공부가 함께 쓰이는 장면으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X01','K5-1-u3-X03','K5-1-u3-X49']::text[],false,'{"seq":6,"concept":"K5-1-u3-C5","difficulty":3,"kind":"mc","stem":"이 단원의 두 공부가 함께 쓰이는 장면으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"발표하는 사람은 자료로 설명하고, 듣는 사람은 그 자료를 보고 궁금한 점을 질문한다","correct":true},{"t":"발표하는 사람이 자료 없이 말만 하고 듣는 사람은 조용히 있는다","mis":"K5-1-u3-X01"},{"t":"듣는 사람이 발표 도중에 끼어들어 다른 이야기를 한다","mis":"K5-1-u3-X03"},{"t":"발표하는 사람이 질문을 받지 않고 바로 들어간다","mis":"K5-1-u3-X49"}],"explanation":["자료도 질문도 없어요.","끼어들면 안 돼요.","발표와 질문이 함께 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#7','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C1',3,'sa','auto','발표 내용을 더 잘 전하려고 함께 보여 주는 글 · 표 · 영상 · 사진 같은 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K5-1-u3-C1","difficulty":3,"kind":"sa","stem":"발표 내용을 더 잘 전하려고 함께 보여 주는 글 · 표 · 영상 · 사진 같은 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["자료"],"explanation":["발표를 도와주는 것이에요.","네 가지 유형이 있어요.","「자료」예요."],"mis":"K5-1-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#8','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C1',4,'essay','teacher','말로만 하는 발표와 자료를 활용한 발표를 견주어 자료를 활용하면 좋은 점을 두 가지 쓰고, 갯벌 발표에서 예를 드세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u3-C1","difficulty":4,"kind":"essay","stem":"말로만 하는 발표와 자료를 활용한 발표를 견주어 자료를 활용하면 좋은 점을 두 가지 쓰고, 갯벌 발표에서 예를 드세요.","answer_guide":{"answer":"예: 자료를 활용하면 내용을 이해하기 쉬워지고, 말로 설명하기 어려운 것을 보여 줄 수 있다. 갯벌 발표에서 밀물이 들어오는 과정은 말로만 하면 떠올리기 어렵지만 영상으로 보여 주면 한눈에 알 수 있다. 짱뚱어 사진을 보여 주면 듣는 사람의 관심도 끌 수 있다.","scoring_points":["좋은 점을 두 가지 썼는가","말로만 할 때와 견주었는가","갯벌 발표에서 예를 들었는가"]},"explanation":["말로만 하면 어려운 것을 떠올려요.","좋은 점을 두 가지 찾아요.","갯벌 예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#9','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C4',4,'essay','teacher','질문이 묻는 사람과 답하는 사람에게 각각 어떤 도움이 되는지 시온이와 주아의 대화를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u3-C4","difficulty":4,"kind":"essay","stem":"질문이 묻는 사람과 답하는 사람에게 각각 어떤 도움이 되는지 시온이와 주아의 대화를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 묻는 사람인 시온이는 조선 시대에 어떤 기술이 있었는지 궁금한 점을 해결할 수 있다. 답하는 사람인 주아는 책에서 읽은 내용을 다시 떠올려 정리하면서 자기 생각을 더 깊이 돌아보게 된다. 그래서 질문은 두 사람 모두에게 남는 것이 있다.","scoring_points":["묻는 사람이 얻는 것을 썼는가","답하는 사람이 얻는 것을 썼는가","두 사람의 대화를 예로 들었는가"]},"explanation":["시온이는 무엇을 얻나요?","주아는 무엇을 얻나요?","대화와 이어 써요."],"asset":{"type":"speech","turns":[{"who":"시온","text":"너 무슨 책 읽어?"},{"who":"주아","text":"조선 시대 과학 기술에 대한 책을 읽고 있어."},{"who":"시온","text":"아, 그렇구나. 그 시대에는 어떤 기술이 있었어?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L01_challenge#10','kor',5,1,'u3','L01','g5_1_kor_u3_L01_challenge','lesson_challenge','K5-1-u3-C2',4,'essay','teacher','「화면 자료가 종이 자료보다 언제나 낫다」는 친구의 말에 대해 자기 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C2","difficulty":4,"kind":"essay","stem":"「화면 자료가 종이 자료보다 언제나 낫다」는 친구의 말에 대해 자기 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 언제나 낫다고 할 수는 없다. 사진과 영상을 함께 보일 때는 화면 자료가 좋지만, 손으로 그린 그림이나 표를 가까이서 자세히 보게 할 때는 종이 자료가 더 알맞을 수 있다. 무엇이 더 좋다기보다 전할 내용과 상황에 맞는 매체를 고르는 것이 중요하다.","scoring_points":["친구의 말에 대한 생각을 밝혔는가","두 매체가 알맞은 경우를 들었는가","내용과 상황에 맞게 고른다는 점을 썼는가"]},"explanation":["늘 더 좋은 매체가 있을까요?","알맞은 경우를 하나씩 떠올려요.","내용과 상황을 기준으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#1','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C6',1,'mc','auto','발표를 준비할 때 먼저 생각할 것이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u3-X05']::text[],false,'{"seq":1,"concept":"K5-1-u3-C6","difficulty":1,"kind":"mc","stem":"발표를 준비할 때 먼저 생각할 것이 아닌 것은 어느 것인가요?","options":[{"t":"교실의 온도","correct":true},{"t":"발표를 듣는 사람","mis":"K5-1-u3-X05"},{"t":"발표 목적","mis":"K5-1-u3-X05"},{"t":"활용할 매체","mis":"K5-1-u3-X05"}],"explanation":["듣는 사람에 따라 자료가 달라져요.","목적도 먼저 생각해요.","교실 온도는 발표 준비와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#2','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C8',1,'match','auto','자료 유형과 그 특성을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u3-C8","difficulty":1,"kind":"match","stem":"자료 유형과 그 특성을 이으세요.","pairs":[{"l":"글","r":"주제에 대한 자세한 설명"},{"l":"표나 그래프","r":"수치와 그 변화"},{"l":"영상","r":"움직임이나 변화 과정"},{"l":"그림이나 사진","r":"대상의 특징"}],"mis":"K5-1-u3-X07","explanation":["글은 설명을 담아요.","표나 그래프는 수치를 보여 줘요.","영상은 움직임, 사진은 특징이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#3','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C8',1,'mc','auto','㉰는 어떤 자료 유형인가요?',ARRAY['K5-1-u3-X07']::text[],false,'{"seq":3,"concept":"K5-1-u3-C8","difficulty":1,"kind":"mc","stem":"㉰는 어떤 자료 유형인가요?","options":[{"t":"영상","correct":true},{"t":"그림이나 사진","mis":"K5-1-u3-X07"},{"t":"표나 그래프","mis":"K5-1-u3-X07"},{"t":"글","mis":"K5-1-u3-X07"}],"explanation":["한 장으로는 물이 차오르는 과정을 담기 어려워요.","수치가 아니에요.","시간이 흐르며 달라지는 모습을 담았어요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 밀물 때 잠기고 썰물 때 드러나는 넓고 평평한 땅이다.","　 진흙과 모래가 섞여 있어 수많은 생물이 산다.","㉯ 우리나라 갯벌 면적이 해마다 어떻게 달라졌는지 연도별로 정리한 것","㉰ 밀물이 들어오며 갯벌이 물에 잠기는 장면을 잠깐 동안 담은 화면","㉱ 진흙 위를 기어가는 짱뚱어를 가까이에서 찍은 한 장"],"title":"같은 주제(갯벌), 다른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#4','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C8',1,'mc','auto','㉯를 가장 잘 나타낼 수 있는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X07','K5-1-u3-X08']::text[],false,'{"seq":4,"concept":"K5-1-u3-C8","difficulty":1,"kind":"mc","stem":"㉯를 가장 잘 나타낼 수 있는 자료 유형은 어느 것인가요?","options":[{"t":"표나 그래프","correct":true},{"t":"영상","mis":"K5-1-u3-X07"},{"t":"그림이나 사진","mis":"K5-1-u3-X07"},{"t":"글","mis":"K5-1-u3-X08"}],"explanation":["움직임이 아니에요.","생김새가 아니에요.","연도별 수치는 표나 그래프가 한눈에 보여 줘요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 밀물 때 잠기고 썰물 때 드러나는 넓고 평평한 땅이다.","　 진흙과 모래가 섞여 있어 수많은 생물이 산다.","㉯ 우리나라 갯벌 면적이 해마다 어떻게 달라졌는지 연도별로 정리한 것","㉰ 밀물이 들어오며 갯벌이 물에 잠기는 장면을 잠깐 동안 담은 화면","㉱ 진흙 위를 기어가는 짱뚱어를 가까이에서 찍은 한 장"],"title":"같은 주제(갯벌), 다른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#5','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C7',2,'mc','auto','인터넷에서 자료를 찾는 방법의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X06','K5-1-u3-X09']::text[],false,'{"seq":5,"concept":"K5-1-u3-C7","difficulty":2,"kind":"mc","stem":"인터넷에서 자료를 찾는 방법의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"빠르고 양이 많으나 사실인지 확인해야 한다","correct":true},{"t":"깊이 있는 답을 들을 수 있으나 만나기 어렵다","mis":"K5-1-u3-X06"},{"t":"정리된 내용이 많으나 최신 정보는 적을 수 있다","mis":"K5-1-u3-X06"},{"t":"찾은 내용은 모두 사실이라 확인할 필요가 없다","mis":"K5-1-u3-X09"}],"explanation":["전문가에게 묻기의 특징이에요.","책에서 찾기의 특징이에요.","인터넷에는 사실이 아닌 내용도 섞여 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#6','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C7',2,'mc','auto','책에서 발표 자료를 찾을 때 먼저 하면 좋은 일은 어느 것인가요?',ARRAY['K5-1-u3-X11','K5-1-u3-X06','K5-1-u3-X14']::text[],false,'{"seq":6,"concept":"K5-1-u3-C7","difficulty":2,"kind":"mc","stem":"책에서 발표 자료를 찾을 때 먼저 하면 좋은 일은 어느 것인가요?","options":[{"t":"차례를 보고 주제와 관련 있는 부분을 찾는다","correct":true},{"t":"첫 쪽부터 끝까지 모두 옮겨 적는다","mis":"K5-1-u3-X11"},{"t":"표지 그림만 보고 고른다","mis":"K5-1-u3-X06"},{"t":"아무 쪽이나 펼쳐 처음 보이는 내용을 쓴다","mis":"K5-1-u3-X14"}],"explanation":["모두 옮기면 고른 것이 아니에요.","표지로는 내용을 알 수 없어요.","차례가 길잡이가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#7','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C10',2,'mc','auto','인터넷에서 찾은 자료를 믿을 수 있는지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X09','K5-1-u3-X48']::text[],false,'{"seq":7,"concept":"K5-1-u3-C10","difficulty":2,"kind":"mc","stem":"인터넷에서 찾은 자료를 믿을 수 있는지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 내용을 여러 곳에서 확인하고 공공 기관 누리집도 찾아본다","correct":true},{"t":"처음 찾은 글을 그대로 믿는다","mis":"K5-1-u3-X09"},{"t":"글이 길면 믿을 수 있다고 본다","mis":"K5-1-u3-X09"},{"t":"댓글이 많이 달린 글을 고른다","mis":"K5-1-u3-X48"}],"explanation":["한 곳만 보면 틀릴 수 있어요.","길이와 믿음은 관계없어요.","여러 곳에서 견주어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#8','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C9',2,'mc','auto','갯벌 면적이 줄어든 정도를 전할 때 그래프가 글보다 나은 까닭은 무엇인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X13','K5-1-u3-X07']::text[],false,'{"seq":8,"concept":"K5-1-u3-C9","difficulty":2,"kind":"mc","stem":"갯벌 면적이 줄어든 정도를 전할 때 그래프가 글보다 나은 까닭은 무엇인가요?","options":[{"t":"줄어든 정도와 속도가 한눈에 보이기 때문이다","correct":true},{"t":"그래프가 더 예쁘기 때문이다","mis":"K5-1-u3-X18"},{"t":"글로는 아예 전할 수 없기 때문이다","mis":"K5-1-u3-X13"},{"t":"그래프에는 자세한 설명이 담기기 때문이다","mis":"K5-1-u3-X07"}],"explanation":["예쁜 것이 기준은 아니에요.","글로도 전할 수는 있어요.","수치의 변화를 한눈에 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#9','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C11',2,'ox','auto','영상 자료는 처음부터 끝까지 다 보여 주어야 해요.',ARRAY['K5-1-u3-X10']::text[],false,'{"seq":9,"concept":"K5-1-u3-C11","difficulty":2,"kind":"ox","stem":"영상 자료는 처음부터 끝까지 다 보여 주어야 해요.","answer":"X","reason_options":[{"t":"발표에 꼭 필요한 부분만 골라 써야 듣는 사람이 핵심을 놓치지 않기 때문에","correct":true},{"t":"영상은 잘라 쓰면 안 되기 때문에","mis":"K5-1-u3-X10"}],"mis":"K5-1-u3-X10","explanation":["필요한 부분만 골라요.","다 틀면 핵심이 흐려져요.","따져 보고 골라 쓰는 것까지가 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_basic#10','kor',5,1,'u3','L02','g5_1_kor_u3_L02_basic','lesson_basic','K5-1-u3-C11',3,'mc','auto','그래프 자료를 발표에 쓰기 전에 확인할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X24','K5-1-u3-X11']::text[],false,'{"seq":10,"concept":"K5-1-u3-C11","difficulty":3,"kind":"mc","stem":"그래프 자료를 발표에 쓰기 전에 확인할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"눈금의 간격이 고른지, 수치가 과장되지 않았는지","correct":true},{"t":"색깔이 화려한지","mis":"K5-1-u3-X18"},{"t":"그래프가 화면을 가득 채우는지","mis":"K5-1-u3-X24"},{"t":"막대가 많을수록 좋은지","mis":"K5-1-u3-X11"}],"explanation":["색깔은 기준이 아니에요.","크기보다 정확한지가 먼저예요.","눈금과 과장을 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#1','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C6',2,'mc','auto','발표를 듣는 사람이 일 학년 동생들이라면 발표 준비에서 무엇이 달라져야 할까요?',ARRAY['K5-1-u3-X05','K5-1-u3-X17','K5-1-u3-X11']::text[],false,'{"seq":1,"concept":"K5-1-u3-C6","difficulty":2,"kind":"mc","stem":"발표를 듣는 사람이 일 학년 동생들이라면 발표 준비에서 무엇이 달라져야 할까요?","options":[{"t":"동생들이 알아듣기 쉬운 자료와 말을 고른다","correct":true},{"t":"주제만 정하면 되니 달라질 것이 없다","mis":"K5-1-u3-X05"},{"t":"더 어려운 낱말을 많이 쓴다","mis":"K5-1-u3-X17"},{"t":"자료를 되도록 많이 넣는다","mis":"K5-1-u3-X11"}],"explanation":["듣는 사람도 먼저 생각해요.","어려운 말은 바꾸어 써요.","듣는 사람에 따라 자료가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#2','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C10',2,'ox','auto','자료를 조사할 때 출처는 발표가 끝난 뒤에 떠올려 적으면 돼요.',ARRAY['K5-1-u3-X09']::text[],false,'{"seq":2,"concept":"K5-1-u3-C10","difficulty":2,"kind":"ox","stem":"자료를 조사할 때 출처는 발표가 끝난 뒤에 떠올려 적으면 돼요.","answer":"X","reason_options":[{"t":"조사하면서 출처를 함께 기록해야 나중에 정확히 밝힐 수 있기 때문에","correct":true},{"t":"출처는 기억해 두었다가 적어도 틀리지 않기 때문에","mis":"K5-1-u3-X09"}],"mis":"K5-1-u3-X09","explanation":["나중에는 어디서 찾았는지 잊기 쉬워요.","기억은 흐려져요.","조사하면서 바로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#3','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C7',3,'mc','auto','갯벌 생물에 대해 책에 없는 내용을 깊이 있게 알고 싶다면 어떤 방법이 알맞을까요?',ARRAY['K5-1-u3-X48','K5-1-u3-X06']::text[],false,'{"seq":3,"concept":"K5-1-u3-C7","difficulty":3,"kind":"mc","stem":"갯벌 생물에 대해 책에 없는 내용을 깊이 있게 알고 싶다면 어떤 방법이 알맞을까요?","options":[{"t":"갯벌 생물을 연구하는 전문가에게 묻는다","correct":true},{"t":"아무 게시글이나 찾아 그대로 옮긴다","mis":"K5-1-u3-X48"},{"t":"친구에게 들은 말을 그대로 쓴다","mis":"K5-1-u3-X48"},{"t":"같은 책을 다시 읽는다","mis":"K5-1-u3-X06"}],"explanation":["누가 썼는지 모르는 글이에요.","전해 들은 말은 확인이 필요해요.","전문가에게서 깊이 있는 답을 들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#4','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C8',3,'mc','auto','㉮~㉱ 가운데 대상의 특징을 강조해 보여 주는 자료는 어느 것인가요?',ARRAY['K5-1-u3-X07']::text[],false,'{"seq":4,"concept":"K5-1-u3-C8","difficulty":3,"kind":"mc","stem":"㉮~㉱ 가운데 대상의 특징을 강조해 보여 주는 자료는 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"K5-1-u3-X07"},{"t":"㉯","mis":"K5-1-u3-X07"},{"t":"㉰","mis":"K5-1-u3-X07"}],"explanation":["자세한 설명을 담은 글이에요.","수치를 정리한 것이에요.","짱뚱어를 가까이에서 찍은 사진이에요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 밀물 때 잠기고 썰물 때 드러나는 넓고 평평한 땅이다.","　 진흙과 모래가 섞여 있어 수많은 생물이 산다.","㉯ 우리나라 갯벌 면적이 해마다 어떻게 달라졌는지 연도별로 정리한 것","㉰ 밀물이 들어오며 갯벌이 물에 잠기는 장면을 잠깐 동안 담은 화면","㉱ 진흙 위를 기어가는 짱뚱어를 가까이에서 찍은 한 장"],"title":"같은 주제(갯벌), 다른 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#5','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C8',3,'error','auto','자료 유형의 특성에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X02','K5-1-u3-X07']::text[],false,'{"seq":5,"concept":"K5-1-u3-C8","difficulty":3,"kind":"error","stem":"자료 유형의 특성에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「영상은 낱말의 뜻을 자세히 풀이하는 데 가장 좋아.」","correct":true,"mis_target":"K5-1-u3-X02"},{"t":"「표나 그래프는 수치의 변화를 한눈에 보여 줘.」","mis":"K5-1-u3-X07"},{"t":"「글은 주제에 대한 자세한 설명을 담아.」","mis":"K5-1-u3-X07"}],"explanation":["맞는 말이에요.","맞는 말이에요.","영상은 움직임이나 변화 과정을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#6','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C9',3,'mc','auto','「갯벌 면적이 줄었다」는 내용을 글로만 전할 때 생기는 어려움은 무엇인가요?',ARRAY['K5-1-u3-X08','K5-1-u3-X07']::text[],false,'{"seq":6,"concept":"K5-1-u3-C9","difficulty":3,"kind":"mc","stem":"「갯벌 면적이 줄었다」는 내용을 글로만 전할 때 생기는 어려움은 무엇인가요?","options":[{"t":"듣는 사람이 얼마나 줄었는지 크기를 가늠하기 어렵다","correct":true},{"t":"아무 어려움이 없다","mis":"K5-1-u3-X08"},{"t":"글로 전하면 내용이 틀리게 된다","mis":"K5-1-u3-X08"},{"t":"듣는 사람이 갯벌 사진을 떠올리게 된다","mis":"K5-1-u3-X07"}],"explanation":["수치의 크기는 글로 가늠하기 어려워요.","틀리는 것은 아니에요.","그래프라면 정도가 한눈에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#7','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C11',3,'mc','auto','눈금이 고르지 않은 그래프를 그대로 쓰면 어떤 일이 생길 수 있나요?',ARRAY['K5-1-u3-X10','K5-1-u3-X24']::text[],false,'{"seq":7,"concept":"K5-1-u3-C11","difficulty":3,"kind":"mc","stem":"눈금이 고르지 않은 그래프를 그대로 쓰면 어떤 일이 생길 수 있나요?","options":[{"t":"조금 줄어든 것이 아주 크게 줄어든 것처럼 보여 듣는 사람이 잘못 알 수 있다","correct":true},{"t":"아무 문제도 생기지 않는다","mis":"K5-1-u3-X10"},{"t":"그래프가 더 정확해진다","mis":"K5-1-u3-X10"},{"t":"듣는 사람이 그래프를 보지 않게 된다","mis":"K5-1-u3-X24"}],"explanation":["잘못 알게 될 수 있어요.","정확해지지 않아요.","눈금 간격이 고른지 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#8','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C8',4,'essay','teacher','「우리 동네 공원」을 발표한다고 할 때, 네 가지 자료 유형을 하나씩 골라 무엇을 보여 줄지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u3-C8","difficulty":4,"kind":"essay","stem":"「우리 동네 공원」을 발표한다고 할 때, 네 가지 자료 유형을 하나씩 골라 무엇을 보여 줄지 쓰세요.","answer_guide":{"answer":"예: 글 — 공원이 언제 어떻게 만들어졌는지 자세히 설명한다. 표나 그래프 — 계절마다 공원을 찾는 사람의 수가 어떻게 달라지는지 보여 준다. 영상 — 분수가 물을 뿜는 모습을 보여 준다. 그림이나 사진 — 공원에 피는 꽃의 생김새를 보여 준다.","scoring_points":["네 가지 유형을 모두 썼는가","유형마다 보여 줄 내용을 썼는가","유형의 특성에 맞는 내용인가"]},"explanation":["설명 · 수치 · 움직임 · 특징을 떠올려요.","유형마다 하나씩 정해요.","특성과 내용을 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#9','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C10',4,'essay','teacher','인터넷에서 「갯벌이 해마다 두 배로 넓어진다」는 글을 찾았어요. 이 글을 발표에 쓰기 전에 해야 할 일을 두 가지 이상 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u3-C10","difficulty":4,"kind":"essay","stem":"인터넷에서 「갯벌이 해마다 두 배로 넓어진다」는 글을 찾았어요. 이 글을 발표에 쓰기 전에 해야 할 일을 두 가지 이상 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 먼저 같은 내용을 다른 곳에서도 확인한다. 인터넷에는 사실이 아닌 내용도 섞여 있기 때문이다. 다음으로 공공 기관 누리집에서 갯벌 면적 자료를 찾아 견주어 본다. 책임 있는 곳의 자료가 더 믿을 수 있기 때문이다. 쓴다면 출처도 함께 적는다.","scoring_points":["해야 할 일을 두 가지 이상 썼는가","여러 곳 확인 · 공공 기관 · 출처 가운데 들었는가","까닭을 썼는가"]},"explanation":["그대로 믿어도 될까요?","확인하는 방법을 떠올려요.","까닭도 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L02_challenge#10','kor',5,1,'u3','L02','g5_1_kor_u3_L02_challenge','lesson_challenge','K5-1-u3-C11',4,'essay','teacher','「찾은 자료를 그대로 믿고 옮기는 것이 아니라 따져 보고 골라 쓰는 것까지가 조사이다」라는 말의 뜻을 표나 그래프, 영상의 예를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C11","difficulty":4,"kind":"essay","stem":"「찾은 자료를 그대로 믿고 옮기는 것이 아니라 따져 보고 골라 쓰는 것까지가 조사이다」라는 말의 뜻을 표나 그래프, 영상의 예를 들어 쓰세요.","answer_guide":{"answer":"예: 조사는 자료를 찾는 데서 끝나지 않는다. 그래프는 눈금의 간격이 고른지, 수치가 과장되지 않았는지 따져 보고 써야 한다. 영상은 처음부터 끝까지 다 틀지 않고 발표에 꼭 필요한 부분만 골라 써야 한다. 이렇게 따져 보고 골라 써야 듣는 사람이 바르게 알 수 있다.","scoring_points":["말의 뜻을 썼는가","그래프를 따져 보는 방법을 썼는가","영상을 골라 쓰는 방법을 썼는가"]},"explanation":["찾기와 쓰기 사이에 할 일이 있어요.","그래프는 무엇을 따지나요?","영상은 어떻게 골라 쓰나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#1','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C12',1,'mc','auto','자료 선별의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X11','K5-1-u3-X16','K5-1-u3-X01']::text[],false,'{"seq":1,"concept":"K5-1-u3-C12","difficulty":1,"kind":"mc","stem":"자료 선별의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"발표 내용을 더 효과적으로 전달할 수 있는 자료를 골라 선택하는 것","correct":true},{"t":"찾은 자료를 하나도 빼지 않고 모두 쓰는 것","mis":"K5-1-u3-X11"},{"t":"보기에 멋진 자료만 모으는 것","mis":"K5-1-u3-X16"},{"t":"자료를 쓰지 않고 말로만 발표하는 것","mis":"K5-1-u3-X01"}],"explanation":["다 쓰는 것은 선별이 아니에요.","멋보다 주제와 맞는지가 먼저예요.","골라 선택하는 것이 선별이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#2','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C13',1,'match','auto','갯벌 발표 내용과 그 내용을 가장 잘 살려 주는 자료 유형을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u3-C13","difficulty":1,"kind":"match","stem":"갯벌 발표 내용과 그 내용을 가장 잘 살려 주는 자료 유형을 이으세요.","pairs":[{"l":"갯벌의 뜻과 생기는 곳","r":"글"},{"l":"밀물과 썰물에 따른 변화","r":"영상"},{"l":"갯벌 생물의 생김새","r":"그림이나 사진"},{"l":"연도별 갯벌 면적의 변화","r":"표나 그래프"}],"mis":"K5-1-u3-X12","explanation":["설명은 글이에요.","변화 과정은 영상이에요.","생김새는 사진, 수치는 그래프예요."],"asset":{"type":"passage","lines":["발표 주제 — 우리나라의 갯벌","① 갯벌의 뜻과 생기는 곳","② 밀물과 썰물에 따라 달라지는 모습","③ 갯벌에 사는 생물의 생김새","④ 연도별 갯벌 면적의 변화"],"title":"갯벌 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#3','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C15',1,'mc','auto','갯벌 생물의 생김새를 발표할 때 필요한 부분은 어느 것인가요?',ARRAY['K5-1-u3-X14']::text[],false,'{"seq":3,"concept":"K5-1-u3-C15","difficulty":1,"kind":"mc","stem":"갯벌 생물의 생김새를 발표할 때 필요한 부분은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉰","mis":"K5-1-u3-X14"},{"t":"㉱","mis":"K5-1-u3-X14"},{"t":"㉮","mis":"K5-1-u3-X14"}],"explanation":["갯벌이 하는 일이에요.","사람들의 삶터 이야기예요.","짱뚱어와 농게의 생김새가 담겼어요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 썰물 때 드러나는 평평한 땅이다. 강이 실어 온 흙과 모래가","　 쌓여 만들어지며, 조수 간만의 차가 큰 바닷가에 잘 생긴다.","㉯ 짱뚱어는 가슴지느러미로 진흙 위를 기어 다니고, 농게는 한쪽","　 집게발만 유난히 크다. 조개는 진흙 속에 몸을 묻고 산다.","㉰ 갯벌은 육지에서 흘러온 물을 걸러 준다. 진흙 속 작은 생물이","　 오염 물질을 분해하기 때문이다. 태풍 때 파도의 힘도 줄인다.","㉱ 갯벌은 사람들의 삶터이다. 조개를 캐는 일이 오래 이어져 왔고,","　 요즘에는 갯벌 체험장을 찾는 사람도 많아졌다."],"title":"찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#4','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C17',1,'mc','auto','갯벌 발표에서 빼야 할 자료는 어느 것인가요?',ARRAY['K5-1-u3-X16']::text[],false,'{"seq":4,"concept":"K5-1-u3-C17","difficulty":1,"kind":"mc","stem":"갯벌 발표에서 빼야 할 자료는 어느 것인가요?","options":[{"t":"멋있어 보여서 넣은 도시 야경 사진","correct":true},{"t":"갯벌 면적 변화를 담은 그래프","mis":"K5-1-u3-X16"},{"t":"농게를 가까이에서 찍은 사진","mis":"K5-1-u3-X16"},{"t":"밀물이 들어오는 영상","mis":"K5-1-u3-X16"}],"explanation":["발표 내용 ④와 이어져요.","발표 내용 ③과 이어져요.","도시 야경은 갯벌과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#5','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C18',2,'mc','auto','어려운 말을 뜻은 그대로 두고 알맞게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":5,"concept":"K5-1-u3-C18","difficulty":2,"kind":"mc","stem":"어려운 말을 뜻은 그대로 두고 알맞게 바꾼 것은 어느 것인가요?","options":[{"t":"「퇴적된다」 → 「쌓인다」","correct":true},{"t":"「감소한다」 → 「사라진다」","mis":"K5-1-u3-X17"},{"t":"「분해한다」 → 「없앤다」","mis":"K5-1-u3-X17"},{"t":"「서식한다」 → 「떠난다」","mis":"K5-1-u3-X17"}],"explanation":["줄어드는 것과 사라지는 것은 달라요.","잘게 나누는 것과 없애는 것은 달라요.","뜻이 그대로이고 말만 쉬워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#6','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C16',2,'mc','auto','㉮를 「갯벌의 뜻과 생기는 곳」에 맞게 요약한 것은 어느 것인가요?',ARRAY['K5-1-u3-X14','K5-1-u3-X15']::text[],false,'{"seq":6,"concept":"K5-1-u3-C16","difficulty":2,"kind":"mc","stem":"㉮를 「갯벌의 뜻과 생기는 곳」에 맞게 요약한 것은 어느 것인가요?","options":[{"t":"썰물 때 드러나는 평평한 땅 · 흙과 모래가 쌓여 생김 · 조수 간만의 차가 큰 곳","correct":true},{"t":"갯벌 체험장을 찾는 사람이 많음","mis":"K5-1-u3-X14"},{"t":"㉮의 문장을 그대로 모두 옮겨 적음","mis":"K5-1-u3-X15"},{"t":"농게는 한쪽 집게발이 큼","mis":"K5-1-u3-X14"}],"explanation":["㉱의 내용이에요.","옮겨 적으면 요약이 아니에요.","필요한 것만 남겼어요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 썰물 때 드러나는 평평한 땅이다. 강이 실어 온 흙과 모래가","　 쌓여 만들어지며, 조수 간만의 차가 큰 바닷가에 잘 생긴다.","㉯ 짱뚱어는 가슴지느러미로 진흙 위를 기어 다니고, 농게는 한쪽","　 집게발만 유난히 크다. 조개는 진흙 속에 몸을 묻고 산다.","㉰ 갯벌은 육지에서 흘러온 물을 걸러 준다. 진흙 속 작은 생물이","　 오염 물질을 분해하기 때문이다. 태풍 때 파도의 힘도 줄인다.","㉱ 갯벌은 사람들의 삶터이다. 조개를 캐는 일이 오래 이어져 왔고,","　 요즘에는 갯벌 체험장을 찾는 사람도 많아졌다."],"title":"찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#7','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C14',2,'ox','auto','「갯벌의 뜻과 생기는 곳」은 글 자료로만 보여 주어야 해요.',ARRAY['K5-1-u3-X13']::text[],false,'{"seq":7,"concept":"K5-1-u3-C14","difficulty":2,"kind":"ox","stem":"「갯벌의 뜻과 생기는 곳」은 글 자료로만 보여 주어야 해요.","answer":"X","reason_options":[{"t":"글로 설명하면서 사진을 함께 보여 주는 것처럼 한 내용에 여러 유형이 어울릴 수 있기 때문에","correct":true},{"t":"한 내용에는 정해진 유형이 하나뿐이기 때문에","mis":"K5-1-u3-X13"}],"mis":"K5-1-u3-X13","explanation":["여러 유형을 함께 쓸 수 있어요.","정답 유형이 하나로 정해져 있지 않아요.","중요한 것은 내용을 잘 전하는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#8','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C20',2,'mc','auto','남이 만든 자료의 출처를 밝히면 좋은 점은 무엇인가요?',ARRAY['K5-1-u3-X19','K5-1-u3-X18']::text[],false,'{"seq":8,"concept":"K5-1-u3-C20","difficulty":2,"kind":"mc","stem":"남이 만든 자료의 출처를 밝히면 좋은 점은 무엇인가요?","options":[{"t":"자료를 만든 사람에 대한 예의가 되고 듣는 사람도 믿고 들을 수 있다","correct":true},{"t":"발표 시간이 길어진다","mis":"K5-1-u3-X19"},{"t":"자료가 더 화려해진다","mis":"K5-1-u3-X18"},{"t":"남의 자료를 내 것처럼 쓸 수 있다","mis":"K5-1-u3-X19"}],"explanation":["시간을 늘리려는 것이 아니에요.","꾸밈과는 관계없어요.","이름표를 다는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#9','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C19',2,'mc','auto','만든 발표 자료를 검토하는 기준이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X19','K5-1-u3-X17']::text[],false,'{"seq":9,"concept":"K5-1-u3-C19","difficulty":2,"kind":"mc","stem":"만든 발표 자료를 검토하는 기준이 아닌 것은 어느 것인가요?","options":[{"t":"글씨 색이 내가 좋아하는 색인가","correct":true},{"t":"글의 양은 알맞은가","mis":"K5-1-u3-X18"},{"t":"출처를 밝혔는가","mis":"K5-1-u3-X19"},{"t":"듣는 사람이 어려워할 말은 없는가","mis":"K5-1-u3-X17"}],"explanation":["글의 양도 살펴요.","출처도 살펴요.","좋아하는 색은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_basic#10','kor',5,1,'u3','L03','g5_1_kor_u3_L03_basic','lesson_basic','K5-1-u3-C16',3,'mc','auto','글 자료를 요약하지 않고 화면에 그대로 옮기면 어떤 일이 생기나요?',ARRAY['K5-1-u3-X15','K5-1-u3-X19']::text[],false,'{"seq":10,"concept":"K5-1-u3-C16","difficulty":3,"kind":"mc","stem":"글 자료를 요약하지 않고 화면에 그대로 옮기면 어떤 일이 생기나요?","options":[{"t":"듣는 사람이 발표자를 보지 않고 화면의 글만 읽게 된다","correct":true},{"t":"듣는 사람이 더 집중해서 발표자를 본다","mis":"K5-1-u3-X15"},{"t":"발표가 더 짧고 분명해진다","mis":"K5-1-u3-X15"},{"t":"자료의 출처가 저절로 밝혀진다","mis":"K5-1-u3-X19"}],"explanation":["글이 많으면 화면만 봐요.","오히려 길고 흐려져요.","필요한 것만 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#1','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C15',2,'mc','auto','「갯벌이 하는 일」을 발표하려면 어느 단락이 필요할까요?',ARRAY['K5-1-u3-X14']::text[],false,'{"seq":1,"concept":"K5-1-u3-C15","difficulty":2,"kind":"mc","stem":"「갯벌이 하는 일」을 발표하려면 어느 단락이 필요할까요?","options":[{"t":"㉰","correct":true},{"t":"㉯","mis":"K5-1-u3-X14"},{"t":"㉱","mis":"K5-1-u3-X14"},{"t":"㉮","mis":"K5-1-u3-X14"}],"explanation":["생물의 생김새예요.","사람들의 삶터예요.","물을 걸러 주고 파도를 줄이는 일이에요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 썰물 때 드러나는 평평한 땅이다. 강이 실어 온 흙과 모래가","　 쌓여 만들어지며, 조수 간만의 차가 큰 바닷가에 잘 생긴다.","㉯ 짱뚱어는 가슴지느러미로 진흙 위를 기어 다니고, 농게는 한쪽","　 집게발만 유난히 크다. 조개는 진흙 속에 몸을 묻고 산다.","㉰ 갯벌은 육지에서 흘러온 물을 걸러 준다. 진흙 속 작은 생물이","　 오염 물질을 분해하기 때문이다. 태풍 때 파도의 힘도 줄인다.","㉱ 갯벌은 사람들의 삶터이다. 조개를 캐는 일이 오래 이어져 왔고,","　 요즘에는 갯벌 체험장을 찾는 사람도 많아졌다."],"title":"찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#2','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C18',2,'mc','auto','「조수 간만의 차」를 같은 반 친구들이 알아듣기 쉽게 바꾼 말은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":2,"concept":"K5-1-u3-C18","difficulty":2,"kind":"mc","stem":"「조수 간만의 차」를 같은 반 친구들이 알아듣기 쉽게 바꾼 말은 어느 것인가요?","options":[{"t":"밀물과 썰물의 높이 차이","correct":true},{"t":"바다의 깊이","mis":"K5-1-u3-X17"},{"t":"갯벌에 사는 물고기의 수","mis":"K5-1-u3-X17"},{"t":"파도의 세기","mis":"K5-1-u3-X17"}],"explanation":["깊이가 아니에요.","생물의 수가 아니에요.","뜻이 그대로이고 쉬워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#3','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C14',3,'mc','auto','「밀물에 따른 변화」를 보여 줄 영상을 구하기 어렵다면 어떻게 하면 좋을까요?',ARRAY['K5-1-u3-X13','K5-1-u3-X16']::text[],false,'{"seq":3,"concept":"K5-1-u3-C14","difficulty":3,"kind":"mc","stem":"「밀물에 따른 변화」를 보여 줄 영상을 구하기 어렵다면 어떻게 하면 좋을까요?","options":[{"t":"밀물 전과 뒤의 사진 두 장을 나란히 보여 준다","correct":true},{"t":"그 내용을 아무 말 없이 발표에서 뺀다","mis":"K5-1-u3-X13"},{"t":"관계없는 도시 영상을 대신 넣는다","mis":"K5-1-u3-X16"},{"t":"영상이 아니면 안 되니 발표를 미룬다","mis":"K5-1-u3-X13"}],"explanation":["다른 유형으로도 전할 수 있어요.","주제와 관계없어요.","사진 두 장으로도 변화가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#4','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C18',3,'error','auto','어려운 말을 쉬운 말로 바꾼 것이에요. 뜻이 달라져 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":4,"concept":"K5-1-u3-C18","difficulty":3,"kind":"error","stem":"어려운 말을 쉬운 말로 바꾼 것이에요. 뜻이 달라져 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「오염 물질을 분해한다」 → 「더러운 물질을 없앤다」","correct":true,"mis_target":"K5-1-u3-X17"},{"t":"「완만하다」 → 「경사가 급하지 않다」","mis":"K5-1-u3-X17"},{"t":"「서식한다」 → 「산다」","mis":"K5-1-u3-X17"}],"explanation":["뜻이 그대로예요.","뜻이 그대로예요.","잘게 나누는 것을 없앤다고 하면 뜻이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#5','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C12',3,'mc','auto','자료 선별을 가장 잘한 친구는 누구인가요?',ARRAY['K5-1-u3-X11','K5-1-u3-X16','K5-1-u3-X15']::text[],false,'{"seq":5,"concept":"K5-1-u3-C12","difficulty":3,"kind":"mc","stem":"자료 선별을 가장 잘한 친구는 누구인가요?","options":[{"t":"「발표 내용 넷에 맞추어 자료를 고르고, 관계없는 사진은 뺐어.」","correct":true},{"t":"「찾은 자료가 아까워서 다 넣었어.」","mis":"K5-1-u3-X11"},{"t":"「멋있는 사진부터 골랐어.」","mis":"K5-1-u3-X16"},{"t":"「글 자료를 요약하지 않고 그대로 붙였어.」","mis":"K5-1-u3-X15"}],"explanation":["다 넣으면 고른 것이 아니에요.","멋보다 주제예요.","내용에 맞추어 고르고 덜어 냈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#6','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C13',3,'mc','auto','자료 유형을 고를 때 가장 먼저 따질 기준은 무엇인가요?',ARRAY['K5-1-u3-X12','K5-1-u3-X13']::text[],false,'{"seq":6,"concept":"K5-1-u3-C13","difficulty":3,"kind":"mc","stem":"자료 유형을 고를 때 가장 먼저 따질 기준은 무엇인가요?","options":[{"t":"그 발표 내용이 무엇을 보여 주려는지","correct":true},{"t":"유형의 이름이 멋있는지","mis":"K5-1-u3-X12"},{"t":"친구들이 가장 많이 쓴 유형인지","mis":"K5-1-u3-X12"},{"t":"한 발표에 같은 유형만 쓰는지","mis":"K5-1-u3-X13"}],"explanation":["이름보다 내용이 먼저예요.","남이 쓴 것과 관계없어요.","설명 · 변화 · 생김새 · 수치 가운데 무엇인지 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#7','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C20',3,'mc','auto','출처를 적는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X19','K5-1-u3-X24']::text[],false,'{"seq":7,"concept":"K5-1-u3-C20","difficulty":3,"kind":"mc","stem":"출처를 적는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가져온 사진 아래쪽에 어디에서 가져왔는지 작게 적는다","correct":true},{"t":"출처는 발표자만 알면 되니 적지 않는다","mis":"K5-1-u3-X19"},{"t":"내가 찍은 것처럼 내 이름을 적는다","mis":"K5-1-u3-X19"},{"t":"출처를 화면 한가운데에 크게 적어 사진을 가린다","mis":"K5-1-u3-X24"}],"explanation":["듣는 사람도 알아야 해요.","남의 자료예요.","자료 아래쪽에 작게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#8','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C16',4,'essay','teacher','㉰를 「갯벌이 하는 일」 발표 화면에 넣을 수 있게 짧게 요약하고, 어려운 말 하나를 뜻이 달라지지 않게 쉬운 말로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u3-C16","difficulty":4,"kind":"essay","stem":"㉰를 「갯벌이 하는 일」 발표 화면에 넣을 수 있게 짧게 요약하고, 어려운 말 하나를 뜻이 달라지지 않게 쉬운 말로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 요약 — 육지에서 흘러온 물을 걸러 줌 · 진흙 속 작은 생물이 더러운 물질을 잘게 나눔 · 태풍 때 파도의 힘을 줄임. 바꾼 말 — 「오염 물질을 분해한다」를 「더러운 물질을 잘게 나눈다」로 바꾸었다. 「없앤다」로 바꾸면 뜻이 달라진다.","scoring_points":["㉰의 내용만 남겨 요약했는가","어려운 말 하나를 쉬운 말로 바꾸었는가","뜻이 달라지지 않았는가"]},"explanation":["필요한 것만 남겨요.","어려운 낱말을 찾아요.","뜻은 그대로 두어요."],"asset":{"type":"passage","lines":["㉮ 갯벌은 썰물 때 드러나는 평평한 땅이다. 강이 실어 온 흙과 모래가","　 쌓여 만들어지며, 조수 간만의 차가 큰 바닷가에 잘 생긴다.","㉯ 짱뚱어는 가슴지느러미로 진흙 위를 기어 다니고, 농게는 한쪽","　 집게발만 유난히 크다. 조개는 진흙 속에 몸을 묻고 산다.","㉰ 갯벌은 육지에서 흘러온 물을 걸러 준다. 진흙 속 작은 생물이","　 오염 물질을 분해하기 때문이다. 태풍 때 파도의 힘도 줄인다.","㉱ 갯벌은 사람들의 삶터이다. 조개를 캐는 일이 오래 이어져 왔고,","　 요즘에는 갯벌 체험장을 찾는 사람도 많아졌다."],"title":"찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#9','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C14',4,'essay','teacher','「자료 유형에 정답이 하나로 정해진 것은 아니다」라는 말의 뜻을 갯벌 발표 개요의 내용 하나를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u3-C14","difficulty":4,"kind":"essay","stem":"「자료 유형에 정답이 하나로 정해진 것은 아니다」라는 말의 뜻을 갯벌 발표 개요의 내용 하나를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 한 발표 내용에 여러 유형이 어울릴 수 있다는 뜻이다. ① 「갯벌의 뜻과 생기는 곳」은 글로 설명하면서 갯벌 사진을 함께 보여 주면 더 잘 전해진다. 중요한 것은 유형의 이름이 아니라 그 자료가 내용을 잘 전하는가이다.","scoring_points":["말의 뜻을 썼는가","개요의 내용 하나를 예로 들었는가","내용을 잘 전하는가가 중요하다는 점을 썼는가"]},"explanation":["한 내용에 유형이 하나뿐일까요?","개요에서 하나를 골라요.","무엇이 중요한지 써요."],"asset":{"type":"passage","lines":["발표 주제 — 우리나라의 갯벌","① 갯벌의 뜻과 생기는 곳","② 밀물과 썰물에 따라 달라지는 모습","③ 갯벌에 사는 생물의 생김새","④ 연도별 갯벌 면적의 변화"],"title":"갯벌 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L03_challenge#10','kor',5,1,'u3','L03','g5_1_kor_u3_L03_challenge','lesson_challenge','K5-1-u3-C19',4,'essay','teacher','자신이 만든 발표 자료를 검토할 때 살필 것을 세 가지 이상 쓰고, 그 가운데 하나를 왜 살펴야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C19","difficulty":4,"kind":"essay","stem":"자신이 만든 발표 자료를 검토할 때 살필 것을 세 가지 이상 쓰고, 그 가운데 하나를 왜 살펴야 하는지 쓰세요.","answer_guide":{"answer":"예: 주제에 맞는 자료인지, 글의 양이 알맞은지, 듣는 사람이 어려워할 말은 없는지, 출처를 밝혔는지 살핀다. 글의 양을 살피는 까닭은 글이 많으면 듣는 사람이 발표자를 보지 않고 화면만 읽게 되기 때문이다.","scoring_points":["살필 것을 세 가지 이상 썼는가","그 가운데 하나의 까닭을 썼는가","듣는 사람의 처지에서 생각했는가"]},"explanation":["검토 기준을 떠올려요.","세 가지 이상 써요.","까닭을 하나 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#1','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C21',1,'mc','auto','발표가 이어지는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X20']::text[],false,'{"seq":1,"concept":"K5-1-u3-C21","difficulty":1,"kind":"mc","stem":"발표가 이어지는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"계획하기 → 자료 준비하기 → 발표하기 → 점검하기","correct":true},{"t":"발표하기 → 계획하기 → 점검하기 → 자료 준비하기","mis":"K5-1-u3-X20"},{"t":"점검하기 → 발표하기 → 계획하기 → 자료 준비하기","mis":"K5-1-u3-X20"},{"t":"자료 준비하기 → 발표하기 → 계획하기 → 점검하기","mis":"K5-1-u3-X20"}],"explanation":["계획 없이 발표할 수 없어요.","점검은 발표 뒤에 해요.","계획부터 점검까지 차례로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#2','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C23',1,'mc','auto','발표 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X22','K5-1-u3-X21']::text[],false,'{"seq":2,"concept":"K5-1-u3-C23","difficulty":1,"kind":"mc","stem":"발표 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 갯벌의 생물과 하는 일","correct":true},{"t":"지구의 모든 바다","mis":"K5-1-u3-X22"},{"t":"어제 본 농게 한 마리의 크기","mis":"K5-1-u3-X22"},{"t":"바다","mis":"K5-1-u3-X21"}],"explanation":["너무 넓어요.","너무 좁아요.","너무 넓지도 좁지도 않아 자료를 모으기 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#3','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C24',1,'match','auto','상황과 알맞은 매체를 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K5-1-u3-C24","difficulty":1,"kind":"match","stem":"상황과 알맞은 매체를 이으세요.","pairs":[{"l":"밀물이 들어오는 과정을 보일 때","r":"화면에 띄운 영상"},{"l":"조개껍데기의 무늬를 만져 보게 할 때","r":"직접 가져온 실물"},{"l":"해마다 줄어든 면적을 견줄 때","r":"화면에 띄운 그래프"}],"mis":"K5-1-u3-X23","explanation":["움직임은 영상이에요.","만져 보려면 실물이에요.","수치는 그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#4','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C27',1,'mc','auto','다연이의 시작하는 말에 담긴 것은 무엇인가요?',ARRAY['K5-1-u3-X26','K5-1-u3-X24']::text[],false,'{"seq":4,"concept":"K5-1-u3-C27","difficulty":1,"kind":"mc","stem":"다연이의 시작하는 말에 담긴 것은 무엇인가요?","options":[{"t":"무엇을 왜 발표하는지","correct":true},{"t":"발표를 끝낸다는 인사","mis":"K5-1-u3-X26"},{"t":"갯벌 생물의 이름 열두 개","mis":"K5-1-u3-X24"},{"t":"질문을 받지 않겠다는 말","mis":"K5-1-u3-X26"}],"explanation":["끝맺는 말의 내용이에요.","시작하는 말에 담을 것이 아니에요.","주제와 조사한 까닭이 담겼어요."],"asset":{"type":"speech","turns":[{"who":"시작","text":"안녕하세요. 저는 우리나라 갯벌에 대해 발표할 다연입니다. 지난 봄 갯벌 체험을 다녀온 뒤로 궁금한 점이 많아 조사해 보았습니다."},{"who":"끝","text":"이상으로 발표를 마치겠습니다. 궁금한 점이 있으면 질문해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#5','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C22',2,'mc','auto','주제를 좁혀 가는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X21']::text[],false,'{"seq":5,"concept":"K5-1-u3-C22","difficulty":2,"kind":"mc","stem":"주제를 좁혀 가는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"바다 → 바닷가 지형 → 갯벌 → 우리나라 갯벌의 생물과 하는 일","correct":true},{"t":"갯벌 → 바다 → 우리나라 갯벌의 생물과 하는 일 → 바닷가 지형","mis":"K5-1-u3-X21"},{"t":"우리나라 갯벌의 생물과 하는 일 → 갯벌 → 바닷가 지형 → 바다","mis":"K5-1-u3-X21"},{"t":"바다 → 우리나라 갯벌의 생물과 하는 일","mis":"K5-1-u3-X21"}],"explanation":["넓은 것에서 좁은 것으로 가야 해요.","거꾸로 넓혀 갔어요.","관심 대상에서 차례로 좁혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#6','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C25',2,'mc','auto','발표 자료를 만들 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X24','K5-1-u3-X15']::text[],false,'{"seq":6,"concept":"K5-1-u3-C25","difficulty":2,"kind":"mc","stem":"발표 자료를 만들 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 화면에 한 가지 내용만 담는다","correct":true},{"t":"한 화면에 되도록 많은 내용을 담는다","mis":"K5-1-u3-X24"},{"t":"글은 찾은 그대로 길게 적는다","mis":"K5-1-u3-X15"},{"t":"글씨는 작게 써서 많이 넣는다","mis":"K5-1-u3-X24"}],"explanation":["빽빽하면 알아보기 어려워요.","글은 요약해요.","한 화면에 한 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#7','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C26',2,'ox','auto','자료는 많을수록 좋은 발표가 돼요.',ARRAY['K5-1-u3-X25']::text[],false,'{"seq":7,"concept":"K5-1-u3-C26","difficulty":2,"kind":"ox","stem":"자료는 많을수록 좋은 발표가 돼요.","answer":"X","reason_options":[{"t":"발표의 주인공은 발표자이고 자료는 필요한 곳에 있을 때 힘이 되기 때문에","correct":true},{"t":"자료가 많으면 발표자가 말할 필요가 없기 때문에","mis":"K5-1-u3-X25"}],"mis":"K5-1-u3-X25","explanation":["자료는 보조예요.","많다고 좋은 것이 아니에요.","필요한 곳에 있을 때 힘이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#8','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C28',2,'mc','auto','갯벌 발표의 예상 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X27']::text[],false,'{"seq":8,"concept":"K5-1-u3-C28","difficulty":2,"kind":"mc","stem":"갯벌 발표의 예상 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"갯벌 면적이 줄어든 까닭은 무엇인가요?","correct":true},{"t":"오늘 급식 메뉴는 무엇인가요?","mis":"K5-1-u3-X27"},{"t":"발표자의 생일은 언제인가요?","mis":"K5-1-u3-X27"},{"t":"다음 주 날씨는 어떤가요?","mis":"K5-1-u3-X27"}],"explanation":["발표와 관계없어요.","발표와 관계없어요.","발표 내용에서 나올 법한 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#9','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C29',2,'mc','auto','발표를 마친 뒤 스스로 점검할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X28','K5-1-u3-X25','K5-1-u3-X18']::text[],false,'{"seq":9,"concept":"K5-1-u3-C29","difficulty":2,"kind":"mc","stem":"발표를 마친 뒤 스스로 점검할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"질문에 성의 있게 답했는지","correct":true},{"t":"발표가 끝났으니 돌아볼 것이 없다","mis":"K5-1-u3-X28"},{"t":"친구보다 화면 장수가 많았는지","mis":"K5-1-u3-X25"},{"t":"글씨 색이 예뻤는지","mis":"K5-1-u3-X18"}],"explanation":["점검까지가 발표예요.","장수가 많다고 좋은 것이 아니에요.","질문에 답한 태도도 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_basic#10','kor',5,1,'u3','L04','g5_1_kor_u3_L04_basic','lesson_basic','K5-1-u3-C25',3,'mc','auto','이 발표 화면에서 고칠 점이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u3-X24','K5-1-u3-X19']::text[],false,'{"seq":10,"concept":"K5-1-u3-C25","difficulty":3,"kind":"mc","stem":"이 발표 화면에서 고칠 점이 아닌 것은 어느 것인가요?","options":[{"t":"사진을 넣었다는 것","correct":true},{"t":"한 화면에 내용이 너무 많다는 것","mis":"K5-1-u3-X24"},{"t":"글씨가 작다는 것","mis":"K5-1-u3-X24"},{"t":"사진의 출처가 없다는 것","mis":"K5-1-u3-X19"}],"explanation":["고쳐야 할 점이에요.","고쳐야 할 점이에요.","사진을 넣은 것 자체는 잘못이 아니에요."],"asset":{"type":"passage","lines":["한 화면에 갯벌의 뜻, 생물 이름 열두 개, 면적 그래프,","체험장 안내가 빽빽하게 담겨 있고, 글씨는 작다.","사진 아래에는 아무 표시도 없다."],"title":"어떤 친구의 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#1','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C27',2,'mc','auto','끝맺는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X26','K5-1-u3-X49']::text[],false,'{"seq":1,"concept":"K5-1-u3-C27","difficulty":2,"kind":"mc","stem":"끝맺는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이상으로 발표를 마치겠습니다. 궁금한 점이 있으면 질문해 주세요.」","correct":true},{"t":"「끝.」","mis":"K5-1-u3-X26"},{"t":"「아직 할 말이 많은데 시간이 없네요.」","mis":"K5-1-u3-X26"},{"t":"「질문은 받지 않겠습니다.」","mis":"K5-1-u3-X49"}],"explanation":["마무리 인사가 없어요.","핑계예요.","마무리와 질문 안내가 담겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#2','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C24',2,'mc','auto','짧고 분명한 내용을 전할 때 알맞은 매체는 어느 것인가요?',ARRAY['K5-1-u3-X23']::text[],false,'{"seq":2,"concept":"K5-1-u3-C24","difficulty":2,"kind":"mc","stem":"짧고 분명한 내용을 전할 때 알맞은 매체는 어느 것인가요?","options":[{"t":"몸짓과 말","correct":true},{"t":"긴 영상","mis":"K5-1-u3-X23"},{"t":"여러 쪽짜리 종이 자료","mis":"K5-1-u3-X23"},{"t":"그래프 여러 장","mis":"K5-1-u3-X23"}],"explanation":["짧은 내용에 긴 영상은 맞지 않아요.","여러 쪽은 지나쳐요.","몸짓과 말로 바로 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#3','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C23',3,'mc','auto','「지구의 모든 바다」가 발표 주제로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u3-X22','K5-1-u3-X21','K5-1-u3-X05']::text[],false,'{"seq":3,"concept":"K5-1-u3-C23","difficulty":3,"kind":"mc","stem":"「지구의 모든 바다」가 발표 주제로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"너무 넓어서 짧은 발표 시간 안에 다루기 어렵기 때문이다","correct":true},{"t":"너무 좁아서 자료가 없기 때문이다","mis":"K5-1-u3-X22"},{"t":"바다는 발표할 수 없는 대상이기 때문이다","mis":"K5-1-u3-X21"},{"t":"듣는 사람이 바다를 모르기 때문이다","mis":"K5-1-u3-X05"}],"explanation":["좁은 것이 아니라 넓어요.","바다도 좁혀 가면 발표할 수 있어요.","시간 안에 다룰 크기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#4','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C26',3,'mc','auto','「발표의 주인공은 자료가 아니다」에 맞게 발표한 모습은 어느 것인가요?',ARRAY['K5-1-u3-X25']::text[],false,'{"seq":4,"concept":"K5-1-u3-C26","difficulty":3,"kind":"mc","stem":"「발표의 주인공은 자료가 아니다」에 맞게 발표한 모습은 어느 것인가요?","options":[{"t":"말로 설명하다가 말로 전하기 어려운 곳에서 사진을 가리키며 보여 준다","correct":true},{"t":"화면에 글을 가득 띄우고 그대로 읽는다","mis":"K5-1-u3-X25"},{"t":"자료를 수십 장 넘기며 말은 거의 하지 않는다","mis":"K5-1-u3-X25"},{"t":"듣는 사람을 보지 않고 화면만 바라본다","mis":"K5-1-u3-X25"}],"explanation":["자료가 주인이 되었어요.","말이 빠졌어요.","자료는 말을 도와줄 때 힘이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#5','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C28',3,'mc','auto','예상 질문을 미리 만들어 보면 좋은 점은 무엇인가요?',ARRAY['K5-1-u3-X27','K5-1-u3-X49']::text[],false,'{"seq":5,"concept":"K5-1-u3-C28","difficulty":3,"kind":"mc","stem":"예상 질문을 미리 만들어 보면 좋은 점은 무엇인가요?","options":[{"t":"발표 내용의 빈 곳이 먼저 보여 미리 채울 수 있다","correct":true},{"t":"질문을 받지 않아도 된다","mis":"K5-1-u3-X27"},{"t":"발표 시간이 줄어든다","mis":"K5-1-u3-X27"},{"t":"친구들이 질문을 못 하게 된다","mis":"K5-1-u3-X49"}],"explanation":["질문은 여전히 받아요.","시간과는 관계없어요.","빈 곳이 먼저 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#6','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C29',3,'error','auto','친구 발표를 듣고 말해 준 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X28','K5-1-u3-X19']::text[],false,'{"seq":6,"concept":"K5-1-u3-C29","difficulty":3,"kind":"error","stem":"친구 발표를 듣고 말해 준 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「좋은 점은 말할 필요 없고 틀린 것만 말해 주면 돼.」","correct":true,"mis_target":"K5-1-u3-X28"},{"t":"「그래프가 줄어든 정도를 잘 보여 줘서 좋았어.」","mis":"K5-1-u3-X28"},{"t":"「사진에 출처가 있으면 더 좋겠어.」","mis":"K5-1-u3-X19"}],"explanation":["좋았던 점을 말했어요.","아쉬운 점을 말했어요.","좋았던 점과 아쉬운 점을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#7','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C22',3,'mc','auto','「동물」에 관심 있는 친구가 주제를 좁혀 갈 때 그다음 단계로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X22','K5-1-u3-X21']::text[],false,'{"seq":7,"concept":"K5-1-u3-C22","difficulty":3,"kind":"mc","stem":"「동물」에 관심 있는 친구가 주제를 좁혀 갈 때 그다음 단계로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 동네에 사는 새","correct":true},{"t":"지구의 모든 생물","mis":"K5-1-u3-X22"},{"t":"동물","mis":"K5-1-u3-X21"},{"t":"어제 본 까치 깃털 한 개","mis":"K5-1-u3-X22"}],"explanation":["더 넓어졌어요.","그대로예요.","발표하고 싶은 대상으로 한 걸음 좁혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#8','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C27',4,'essay','teacher','다연이의 시작하는 말과 끝맺는 말에 각각 무엇이 담겼는지 쓰고, 그것이 듣는 사람에게 왜 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u3-C27","difficulty":4,"kind":"essay","stem":"다연이의 시작하는 말과 끝맺는 말에 각각 무엇이 담겼는지 쓰고, 그것이 듣는 사람에게 왜 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 시작하는 말에는 우리나라 갯벌에 대해 발표한다는 것과 갯벌 체험 뒤 궁금해 조사했다는 까닭이 담겼다. 듣는 사람이 무엇을 들을지 미리 알 수 있다. 끝맺는 말에는 마무리 인사와 질문 안내가 담겼다. 듣는 사람이 궁금한 점을 물을 수 있다는 것을 안다.","scoring_points":["시작하는 말에 담긴 것을 썼는가","끝맺는 말에 담긴 것을 썼는가","듣는 사람에게 주는 도움을 썼는가"]},"explanation":["무엇을 왜 발표하나요?","어떻게 마무리했나요?","듣는 사람 쪽에서 생각해요."],"asset":{"type":"speech","turns":[{"who":"시작","text":"안녕하세요. 저는 우리나라 갯벌에 대해 발표할 다연입니다. 지난 봄 갯벌 체험을 다녀온 뒤로 궁금한 점이 많아 조사해 보았습니다."},{"who":"끝","text":"이상으로 발표를 마치겠습니다. 궁금한 점이 있으면 질문해 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#9','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C25',4,'essay','teacher','이 발표 화면의 고칠 점을 세 가지 찾고, 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u3-C25","difficulty":4,"kind":"essay","stem":"이 발표 화면의 고칠 점을 세 가지 찾고, 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 첫째, 한 화면에 내용이 너무 많으니 갯벌의 뜻 · 생물 · 면적 · 체험장을 화면마다 하나씩 나눈다. 둘째, 글씨가 작으니 뒤쪽에서도 보이게 크게 쓴다. 셋째, 사진에 출처가 없으니 사진 아래에 어디에서 가져왔는지 적는다.","scoring_points":["고칠 점을 세 가지 찾았는가","고치는 방법을 썼는가","자료 만들 때 지킬 것과 이어지는가"]},"explanation":["내용의 양을 봐요.","글씨 크기를 봐요.","출처를 봐요."],"asset":{"type":"passage","lines":["한 화면에 갯벌의 뜻, 생물 이름 열두 개, 면적 그래프,","체험장 안내가 빽빽하게 담겨 있고, 글씨는 작다.","사진 아래에는 아무 표시도 없다."],"title":"어떤 친구의 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L04_challenge#10','kor',5,1,'u3','L04','g5_1_kor_u3_L04_challenge','lesson_challenge','K5-1-u3-C28',4,'essay','teacher','「우리 동네 도서관」을 발표한다고 할 때 예상 질문 두 개와 준비할 답을 쓰고, 예상 질문을 준비하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C28","difficulty":4,"kind":"essay","stem":"「우리 동네 도서관」을 발표한다고 할 때 예상 질문 두 개와 준비할 답을 쓰고, 예상 질문을 준비하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 예상 질문 — 「도서관에서 책은 몇 권까지 빌릴 수 있나요?」 답 — 「도서관 누리집 안내를 보니 한 사람이 다섯 권까지 빌릴 수 있다고 합니다.」 예상 질문 — 「어린이 열람실은 어디에 있나요?」 답 — 「들어가자마자 오른쪽에 있습니다.」 예상 질문을 준비하면 발표 내용에서 빠진 곳이 먼저 보여 미리 채울 수 있다.","scoring_points":["발표와 이어지는 예상 질문을 두 개 썼는가","준비할 답을 썼는가","예상 질문을 준비하면 좋은 점을 썼는가"]},"explanation":["듣는 사람이 궁금해할 것을 떠올려요.","답도 미리 준비해요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#1','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C31',1,'match','auto','학급 회의에서 나온 제안과 제안한 까닭을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K5-1-u3-C31","difficulty":1,"kind":"match","stem":"학급 회의에서 나온 제안과 제안한 까닭을 이으세요.","pairs":[{"l":"청소 구역을 두 주마다 바꾸자","r":"힘든 구역과 수월한 구역이 나뉘어서"},{"l":"한 달에 한 번 나눔 시간을 열자","r":"잘하는 것을 보여 줄 기회가 없어서"},{"l":"별명 대신 이름을 부르자","r":"별명 때문에 기분이 상하는 친구가 있어서"}],"mis":"K5-1-u3-X30","explanation":["노아는 청소 구역이 고르지 않다고 보았어요.","시연이는 기회가 없다고 보았어요.","준우는 상한 마음을 문제로 보았어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"학급 회의를 시작하겠습니다. 오늘의 주제는 새로운 학급 규칙 정하기입니다. 손을 들고 발언권을 얻은 뒤에 말해 주세요."},{"who":"노아","text":"청소 구역을 두 주마다 바꾸면 좋겠습니다. 어떤 구역은 늘 힘들고 어떤 구역은 늘 수월해서 불만이 쌓입니다."},{"who":"시연","text":"한 달에 한 번 학급 나눔 시간을 열면 좋겠습니다. 서로 잘하는 것을 보여 줄 기회가 없습니다."},{"who":"준우","text":"별명 대신 이름을 부르면 좋겠습니다. 별명 때문에 기분이 상하는 친구가 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#2','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C32',1,'mc','auto','질문의 세 가지 목적이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u3-X31','K5-1-u3-X32','K5-1-u3-X33']::text[],false,'{"seq":2,"concept":"K5-1-u3-C32","difficulty":1,"kind":"mc","stem":"질문의 세 가지 목적이 아닌 것은 어느 것인가요?","options":[{"t":"상대를 깎아내리기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X31"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X32"},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X33"}],"explanation":["질문의 목적이에요.","질문의 목적이에요.","깎아내리는 말은 질문의 목적이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#3','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C33',1,'mc','auto','「이 규칙으로 어떤 문제를 해결하고 싶은가요?」라는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X31','K5-1-u3-X36']::text[],false,'{"seq":3,"concept":"K5-1-u3-C33","difficulty":1,"kind":"mc","stem":"「이 규칙으로 어떤 문제를 해결하고 싶은가요?」라는 질문의 목적은 무엇인가요?","options":[{"t":"의도를 파악하기 위해서","correct":true},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X31"},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X31"},{"t":"상대를 놀리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["뜻을 또렷이 하려는 질문이 아니에요.","다른 방법을 구하는 질문이 아니에요.","왜 그렇게 제안했는지 알고 싶은 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#4','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C30',1,'mc','auto','질문을 잘하려면 먼저 무엇을 해야 하나요?',ARRAY['K5-1-u3-X29','K5-1-u3-X03']::text[],false,'{"seq":4,"concept":"K5-1-u3-C30","difficulty":1,"kind":"mc","stem":"질문을 잘하려면 먼저 무엇을 해야 하나요?","options":[{"t":"다른 사람의 말을 집중해서 듣는다","correct":true},{"t":"상대가 말하는 동안 내 질문만 생각한다","mis":"K5-1-u3-X29"},{"t":"떠오르는 대로 아무 때나 묻는다","mis":"K5-1-u3-X29"},{"t":"말하는 도중에 끼어든다","mis":"K5-1-u3-X03"}],"explanation":["들어야 궁금한 곳이 보여요.","들은 뒤에 물어요.","집중해 들으면 질문이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#5','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C34',2,'mc','auto','「나눔 시간은 물건을 나누는 건가요, 이야기를 나누는 건가요?」라는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X32','K5-1-u3-X36']::text[],false,'{"seq":5,"concept":"K5-1-u3-C34","difficulty":2,"kind":"mc","stem":"「나눔 시간은 물건을 나누는 건가요, 이야기를 나누는 건가요?」라는 질문의 목적은 무엇인가요?","options":[{"t":"명료하게 이해하기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X32"},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X32"},{"t":"회의를 빨리 끝내기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻는 질문이 아니에요.","다른 방법을 구하지 않아요.","「나눔」의 뜻을 또렷이 하려는 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#6','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C35',2,'mc','auto','「규칙을 정했는데도 계속 별명을 부르면 어떻게 하나요?」라는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X33','K5-1-u3-X36']::text[],false,'{"seq":6,"concept":"K5-1-u3-C35","difficulty":2,"kind":"mc","stem":"「규칙을 정했는데도 계속 별명을 부르면 어떻게 하나요?」라는 질문의 목적은 무엇인가요?","options":[{"t":"대안이나 정보를 찾기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X33"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X33"},{"t":"준우를 깎아내리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","뜻을 묻지 않아요.","그럴 때의 다른 방법을 구하는 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#7','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C37',2,'mc','auto','더 분명하게 표현한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X35']::text[],false,'{"seq":7,"concept":"K5-1-u3-C37","difficulty":2,"kind":"mc","stem":"더 분명하게 표현한 질문은 어느 것인가요?","options":[{"t":"나눔 시간에는 한 번에 몇 명이 발표하나요?","correct":true},{"t":"그건 좀 애매하지 않나요?","mis":"K5-1-u3-X35"},{"t":"어떻게 하실 건가요?","mis":"K5-1-u3-X35"},{"t":"그거 좀 이상하지 않아요?","mis":"K5-1-u3-X35"}],"explanation":["무엇이 애매한지 알 수 없어요.","무엇을 어떻게인지 흐릿해요.","무엇을 알고 싶은지 또렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#8','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C36',2,'mc','auto','다른 경우를 짚어 볼 때 질문을 여는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":8,"concept":"K5-1-u3-C36","difficulty":2,"kind":"mc","stem":"다른 경우를 짚어 볼 때 질문을 여는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"만약","correct":true},{"t":"누가","mis":"K5-1-u3-X34"},{"t":"언제","mis":"K5-1-u3-X34"},{"t":"어디에서","mis":"K5-1-u3-X34"}],"explanation":["사실을 또렷이 할 때 써요.","사실을 또렷이 할 때 써요.","「만약 … 라면」으로 다른 경우를 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#9','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C38',2,'mc','auto','이 학급 회의에서 할 만한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X36']::text[],false,'{"seq":9,"concept":"K5-1-u3-C38","difficulty":2,"kind":"mc","stem":"이 학급 회의에서 할 만한 질문은 어느 것인가요?","options":[{"t":"두 주마다 바꾸면 청소가 서툴러지지 않을까요?","correct":true},{"t":"오늘 몇 교시까지 하나요?","mis":"K5-1-u3-X36"},{"t":"그 의견은 왜 그렇게 별로인가요?","mis":"K5-1-u3-X36"},{"t":"노아는 어느 동네에 사나요?","mis":"K5-1-u3-X36"}],"explanation":["회의 내용과 관계없어요.","깎아내리는 말이에요.","노아의 제안과 이어지는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"학급 회의를 시작하겠습니다. 오늘의 주제는 새로운 학급 규칙 정하기입니다. 손을 들고 발언권을 얻은 뒤에 말해 주세요."},{"who":"노아","text":"청소 구역을 두 주마다 바꾸면 좋겠습니다. 어떤 구역은 늘 힘들고 어떤 구역은 늘 수월해서 불만이 쌓입니다."},{"who":"시연","text":"한 달에 한 번 학급 나눔 시간을 열면 좋겠습니다. 서로 잘하는 것을 보여 줄 기회가 없습니다."},{"who":"준우","text":"별명 대신 이름을 부르면 좋겠습니다. 별명 때문에 기분이 상하는 친구가 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_basic#10','kor',5,1,'u3','L07','g5_1_kor_u3_L07_basic','lesson_basic','K5-1-u3-C39',3,'ox','auto','한 질문은 반드시 한 가지 목적에만 들어가요.',ARRAY['K5-1-u3-X37']::text[],false,'{"seq":10,"concept":"K5-1-u3-C39","difficulty":3,"kind":"ox","stem":"한 질문은 반드시 한 가지 목적에만 들어가요.","answer":"X","reason_options":[{"t":"「이 행사로 어떤 변화를 기대하나요?」처럼 의도를 묻는 동시에 정보도 구하는 질문이 있기 때문에","correct":true},{"t":"질문의 목적은 늘 하나로 정해져 있기 때문에","mis":"K5-1-u3-X37"}],"mis":"K5-1-u3-X37","explanation":["두 목적에 걸치기도 해요.","갈래 맞히기가 목적이 아니에요.","무엇을 알고 싶은지가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#1','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C36',2,'mc','auto','까닭과 의도를 물을 때 질문을 여는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":1,"concept":"K5-1-u3-C36","difficulty":2,"kind":"mc","stem":"까닭과 의도를 물을 때 질문을 여는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"왜","correct":true},{"t":"만약","mis":"K5-1-u3-X34"},{"t":"언제","mis":"K5-1-u3-X34"},{"t":"누가","mis":"K5-1-u3-X34"}],"explanation":["다른 경우를 짚을 때 써요.","때를 또렷이 할 때 써요.","「왜」로 까닭과 의도를 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#2','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C31',2,'mc','auto','준우는 무엇을 문제라고 보았나요?',ARRAY['K5-1-u3-X30','K5-1-u3-X29']::text[],false,'{"seq":2,"concept":"K5-1-u3-C31","difficulty":2,"kind":"mc","stem":"준우는 무엇을 문제라고 보았나요?","options":[{"t":"별명 때문에 기분이 상하는 친구가 있다는 것","correct":true},{"t":"청소 구역이 고르지 않다는 것","mis":"K5-1-u3-X30"},{"t":"잘하는 것을 보여 줄 기회가 없다는 것","mis":"K5-1-u3-X30"},{"t":"회의 시간이 짧다는 것","mis":"K5-1-u3-X29"}],"explanation":["노아가 본 문제예요.","시연이가 본 문제예요.","준우는 상한 마음을 까닭으로 들었어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"학급 회의를 시작하겠습니다. 오늘의 주제는 새로운 학급 규칙 정하기입니다. 손을 들고 발언권을 얻은 뒤에 말해 주세요."},{"who":"노아","text":"청소 구역을 두 주마다 바꾸면 좋겠습니다. 어떤 구역은 늘 힘들고 어떤 구역은 늘 수월해서 불만이 쌓입니다."},{"who":"시연","text":"한 달에 한 번 학급 나눔 시간을 열면 좋겠습니다. 서로 잘하는 것을 보여 줄 기회가 없습니다."},{"who":"준우","text":"별명 대신 이름을 부르면 좋겠습니다. 별명 때문에 기분이 상하는 친구가 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#3','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C35',3,'mc','auto','등대 발표를 듣고 한 질문 「등대에 대해 더 알고 싶으면 어떤 자료를 찾아보면 좋을까요?」의 목적은 무엇인가요?',ARRAY['K5-1-u3-X33','K5-1-u3-X36']::text[],false,'{"seq":3,"concept":"K5-1-u3-C35","difficulty":3,"kind":"mc","stem":"등대 발표를 듣고 한 질문 「등대에 대해 더 알고 싶으면 어떤 자료를 찾아보면 좋을까요?」의 목적은 무엇인가요?","options":[{"t":"대안이나 정보를 찾기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X33"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X33"},{"t":"발표자를 깎아내리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","발표 속 뜻을 묻지 않아요.","발표에 없던 정보를 새로 구해요."],"asset":{"type":"passage","lines":["저는 우리 지역 등대에 대해 발표하겠습니다.","등대는 밤바다에서 배가 길을 찾도록 빛을 보내는 건물입니다.","우리 지역 등대는 백 년이 넘었고, 처음에는 기름으로 불을 밝혔다고 합니다.","지금은 전기를 씁니다.","등대마다 빛이 깜빡이는 간격이 달라서 배가 어느 등대인지 알아볼 수 있습니다.","이상으로 발표를 마치겠습니다."],"title":"발표 「우리 지역 등대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#4','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C34',3,'mc','auto','등대 발표를 듣고 명료하게 이해하려고 한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X32','K5-1-u3-X35']::text[],false,'{"seq":4,"concept":"K5-1-u3-C34","difficulty":3,"kind":"mc","stem":"등대 발표를 듣고 명료하게 이해하려고 한 질문은 어느 것인가요?","options":[{"t":"「빛이 깜빡이는 간격이 다르다는 것은 어떤 뜻인가요?」","correct":true},{"t":"「왜 등대를 발표 주제로 고르셨나요?」","mis":"K5-1-u3-X32"},{"t":"「다른 지역 등대에 대한 자료는 어디에서 찾을 수 있나요?」","mis":"K5-1-u3-X32"},{"t":"「그거 좀 이상하지 않아요?」","mis":"K5-1-u3-X35"}],"explanation":["의도를 묻는 질문이에요.","정보를 구하는 질문이에요.","발표 속 말의 뜻을 또렷이 하려는 질문이에요."],"asset":{"type":"passage","lines":["저는 우리 지역 등대에 대해 발표하겠습니다.","등대는 밤바다에서 배가 길을 찾도록 빛을 보내는 건물입니다.","우리 지역 등대는 백 년이 넘었고, 처음에는 기름으로 불을 밝혔다고 합니다.","지금은 전기를 씁니다.","등대마다 빛이 깜빡이는 간격이 달라서 배가 어느 등대인지 알아볼 수 있습니다.","이상으로 발표를 마치겠습니다."],"title":"발표 「우리 지역 등대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#5','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C33',3,'mc','auto','등대 발표자의 의도를 파악하려는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X31','K5-1-u3-X36']::text[],false,'{"seq":5,"concept":"K5-1-u3-C33","difficulty":3,"kind":"mc","stem":"등대 발표자의 의도를 파악하려는 질문은 어느 것인가요?","options":[{"t":"「우리 지역 등대를 발표 주제로 고른 까닭은 무엇인가요?」","correct":true},{"t":"「기름으로 불을 밝혔다는 것은 어떤 방법이었나요?」","mis":"K5-1-u3-X31"},{"t":"「등대에 대해 더 알 수 있는 책이 있나요?」","mis":"K5-1-u3-X31"},{"t":"「발표가 왜 이렇게 지루한가요?」","mis":"K5-1-u3-X36"}],"explanation":["뜻을 또렷이 하려는 질문이에요.","정보를 구하는 질문이에요.","왜 그 주제를 골랐는지 묻고 있어요."],"asset":{"type":"passage","lines":["저는 우리 지역 등대에 대해 발표하겠습니다.","등대는 밤바다에서 배가 길을 찾도록 빛을 보내는 건물입니다.","우리 지역 등대는 백 년이 넘었고, 처음에는 기름으로 불을 밝혔다고 합니다.","지금은 전기를 씁니다.","등대마다 빛이 깜빡이는 간격이 달라서 배가 어느 등대인지 알아볼 수 있습니다.","이상으로 발표를 마치겠습니다."],"title":"발표 「우리 지역 등대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#6','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C37',3,'error','auto','흐릿한 질문을 분명하게 고친 것이에요. 잘 고치지 못한 것은 어느 것인가요?',ARRAY['K5-1-u3-X35','K5-1-u3-X34']::text[],false,'{"seq":6,"concept":"K5-1-u3-C37","difficulty":3,"kind":"error","stem":"흐릿한 질문을 분명하게 고친 것이에요. 잘 고치지 못한 것은 어느 것인가요?","options":[{"t":"「그거 좀 이상하지 않아요?」 → 「그거 좀 많이 이상하지 않아요?」","correct":true,"mis_target":"K5-1-u3-X35"},{"t":"「어떻게 되는 건가요?」 → 「두 주마다 구역을 바꾸면 청소 방법은 누가 알려 주나요?」","mis":"K5-1-u3-X35"},{"t":"「그건 좀 애매하지 않나요?」 → 「나눔 시간에는 무엇을 하나요?」","mis":"K5-1-u3-X34"}],"explanation":["무엇이 궁금한지 또렷해졌어요.","무엇을 묻는지 또렷해졌어요.","여전히 무엇이 이상한지 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#7','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C39',3,'mc','auto','질문의 목적을 배우는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X37','K5-1-u3-X29','K5-1-u3-X36']::text[],false,'{"seq":7,"concept":"K5-1-u3-C39","difficulty":3,"kind":"mc","stem":"질문의 목적을 배우는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 무엇을 알고 싶은지 생각하고 그에 맞게 묻기 위해서","correct":true},{"t":"질문을 들을 때마다 갈래 이름을 맞히기 위해서","mis":"K5-1-u3-X37"},{"t":"질문을 되도록 적게 하기 위해서","mis":"K5-1-u3-X29"},{"t":"상대의 질문이 틀렸다고 말하기 위해서","mis":"K5-1-u3-X36"}],"explanation":["갈래 맞히기가 목적이 아니에요.","적게 묻는 것이 목적이 아니에요.","알고 싶은 것에 맞게 묻는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#8','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C32',4,'essay','teacher','등대 발표를 듣고 질문의 세 가지 목적에 맞게 질문을 하나씩 만들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u3-C32","difficulty":4,"kind":"essay","stem":"등대 발표를 듣고 질문의 세 가지 목적에 맞게 질문을 하나씩 만들어 쓰세요.","answer_guide":{"answer":"예: 의도를 파악하는 질문 — 「우리 지역 등대를 발표 주제로 고른 까닭은 무엇인가요?」 명료하게 이해하는 질문 — 「빛이 깜빡이는 간격이 다르다는 것은 어떤 뜻인가요?」 대안이나 정보를 찾는 질문 — 「지금 그 등대를 직접 볼 수 있는 방법이 있나요?」","scoring_points":["세 목적에 맞는 질문을 하나씩 썼는가","발표 내용과 이어지는가","분명하게 표현했는가"]},"explanation":["까닭을 묻는 질문을 만들어요.","뜻을 또렷이 하는 질문을 만들어요.","더 알 것을 구하는 질문을 만들어요."],"asset":{"type":"passage","lines":["저는 우리 지역 등대에 대해 발표하겠습니다.","등대는 밤바다에서 배가 길을 찾도록 빛을 보내는 건물입니다.","우리 지역 등대는 백 년이 넘었고, 처음에는 기름으로 불을 밝혔다고 합니다.","지금은 전기를 씁니다.","등대마다 빛이 깜빡이는 간격이 달라서 배가 어느 등대인지 알아볼 수 있습니다.","이상으로 발표를 마치겠습니다."],"title":"발표 「우리 지역 등대」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#9','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C37',4,'essay','teacher','「어떻게 되는 건가요?」라는 흐릿한 질문을 시연이의 제안에 대한 분명한 질문으로 고쳐 쓰고, 분명하게 물으면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u3-C37","difficulty":4,"kind":"essay","stem":"「어떻게 되는 건가요?」라는 흐릿한 질문을 시연이의 제안에 대한 분명한 질문으로 고쳐 쓰고, 분명하게 물으면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 「나눔 시간에는 한 사람이 얼마 동안 무엇을 보여 주나요?」 무엇을 알고 싶은지 분명하게 물으면 답하는 사람도 질문의 목적을 이해하고 알맞은 답을 해 줄 수 있다.","scoring_points":["시연이의 제안과 이어지게 고쳤는가","무엇이 궁금한지 또렷한가","분명하게 물으면 좋은 점을 썼는가"]},"explanation":["시연이는 무엇을 제안했나요?","궁금한 것을 또렷이 써요.","답하는 사람 쪽에서 생각해요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"학급 회의를 시작하겠습니다. 오늘의 주제는 새로운 학급 규칙 정하기입니다. 손을 들고 발언권을 얻은 뒤에 말해 주세요."},{"who":"노아","text":"청소 구역을 두 주마다 바꾸면 좋겠습니다. 어떤 구역은 늘 힘들고 어떤 구역은 늘 수월해서 불만이 쌓입니다."},{"who":"시연","text":"한 달에 한 번 학급 나눔 시간을 열면 좋겠습니다. 서로 잘하는 것을 보여 줄 기회가 없습니다."},{"who":"준우","text":"별명 대신 이름을 부르면 좋겠습니다. 별명 때문에 기분이 상하는 친구가 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L07_challenge#10','kor',5,1,'u3','L07','g5_1_kor_u3_L07_challenge','lesson_challenge','K5-1-u3-C30',4,'essay','teacher','회의나 발표에서 좋은 질문을 하려면 듣는 동안 어떻게 해야 하는지 두 가지 이상 쓰고, 그렇게 해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C30","difficulty":4,"kind":"essay","stem":"회의나 발표에서 좋은 질문을 하려면 듣는 동안 어떻게 해야 하는지 두 가지 이상 쓰고, 그렇게 해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 말하는 사람의 말을 끝까지 집중해서 듣고, 제안과 그 까닭이나 발표 내용 가운데 궁금하거나 흐릿한 곳을 짚어 둔다. 질문은 아무 때나 떠오르지 않고 주의 깊게 들어야 궁금한 곳이 보이기 때문이다.","scoring_points":["듣는 방법을 두 가지 이상 썼는가","집중해서 듣기가 들어 있는가","까닭을 썼는가"]},"explanation":["듣는 태도를 떠올려요.","궁금한 곳을 어떻게 찾나요?","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#1','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C40',1,'mc','auto','로운이가 이상하게 여긴 것은 무엇인가요?',ARRAY['K5-1-u3-X42','K5-1-u3-X39']::text[],false,'{"seq":1,"concept":"K5-1-u3-C40","difficulty":1,"kind":"mc","stem":"로운이가 이상하게 여긴 것은 무엇인가요?","options":[{"t":"손님이 다 나간 뒤에도 창가 식탁에 국수 한 그릇이 놓여 있는 것","correct":true},{"t":"국수 값이 오른 것","mis":"K5-1-u3-X42"},{"t":"분식집이 일찍 문을 닫는 것","mis":"K5-1-u3-X39"},{"t":"학원이 늦게 시작하는 것","mis":"K5-1-u3-X39"}],"explanation":["그런 내용은 없어요.","그런 내용은 없어요.","아무도 앉지 않는 식탁에 국수가 놓였어요."],"asset":{"type":"passage","lines":["학교 앞 골목 끝에 작은 분식집이 있다. 로운이는 목요일마다","그곳에서 국수를 먹는다. 학원이 늦게 시작하는 날이 목요일뿐이다.","어느 목요일, 로운이는 이상한 것을 보았다. 손님이 다 나간 뒤에도","창가 식탁에 국수 한 그릇이 김을 올리며 놓여 있었다.","젓가락도 가지런히 놓여 있었다.","다음 목요일에도, 그다음 목요일에도 그랬다."],"title":"「목요일의 국수」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#2','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C41',1,'mc','auto','아주머니의 마음을 짐작할 단서는 어느 것인가요?',ARRAY['K5-1-u3-X39']::text[],false,'{"seq":2,"concept":"K5-1-u3-C41","difficulty":1,"kind":"mc","stem":"아주머니의 마음을 짐작할 단서는 어느 것인가요?","options":[{"t":"그 국수를 한 번도 먹지 않았다","correct":true},{"t":"분식집이 골목 끝에 있다","mis":"K5-1-u3-X39"},{"t":"로운이는 목요일마다 국수를 먹는다","mis":"K5-1-u3-X39"},{"t":"학원이 목요일에 늦게 시작한다","mis":"K5-1-u3-X39"}],"explanation":["배경이에요.","로운이의 이야기예요.","아주머니의 행동에 마음이 담겼어요."],"asset":{"type":"passage","lines":["「저 식탁에는 누가 앉아요?」 로운이가 물었다.","아주머니는 국수를 삶던 손을 잠깐 멈추었다가 다시 젓가락을 저었다.","「그냥 버릇이야.」 그러고는 더 말하지 않았다.","로운이는 그 국수가 식어 가는 것을 오래 바라보았다.","아주머니는 손님이 다 가고 나면 그 그릇을 조용히 치웠다.","한 번도 먹지 않았다."],"title":"「목요일의 국수」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#3','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C42',1,'mc','auto','「목요일의 국수」에서 가장 먼저 일어난 일은 어느 것인가요?',ARRAY['K5-1-u3-X40']::text[],false,'{"seq":3,"concept":"K5-1-u3-C42","difficulty":1,"kind":"mc","stem":"「목요일의 국수」에서 가장 먼저 일어난 일은 어느 것인가요?","options":[{"t":"로운이가 창가에 놓인 국수 한 그릇을 발견한다","correct":true},{"t":"로운이가 창가 식탁에 앉아 국수를 먹는다","mis":"K5-1-u3-X40"},{"t":"아주머니가 오래전 아이 이야기를 들려준다","mis":"K5-1-u3-X40"},{"t":"그릇이 비워진다","mis":"K5-1-u3-X40"}],"explanation":["맨 끝의 일이에요.","겨울에 있었던 일이에요.","이야기는 국수를 발견하는 데서 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#4','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C44',1,'mc','auto','「목요일의 국수」에 어울리는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":4,"concept":"K5-1-u3-C44","difficulty":1,"kind":"mc","stem":"「목요일의 국수」에 어울리는 질문은 어느 것인가요?","options":[{"t":"왜 하필 목요일이었을까요?","correct":true},{"t":"분식집 국수 값은 얼마인가요?","mis":"K5-1-u3-X42"},{"t":"이 골목의 이름은 무엇인가요?","mis":"K5-1-u3-X42"},{"t":"로운이의 학원은 몇 층에 있나요?","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","이야기와 관계없어요.","이야기 안에서 생각해 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#5','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C41',2,'mc','auto','아주머니가 목요일마다 국수를 놓아 둔 까닭을 짐작할 수 있는 말은 어느 것인가요?',ARRAY['K5-1-u3-X39']::text[],false,'{"seq":5,"concept":"K5-1-u3-C41","difficulty":2,"kind":"mc","stem":"아주머니가 목요일마다 국수를 놓아 둔 까닭을 짐작할 수 있는 말은 어느 것인가요?","options":[{"t":"「오래전에 목요일마다 오던 애가 있었어.」","correct":true},{"t":"「겨울이 되었다.」","mis":"K5-1-u3-X39"},{"t":"「눈이 많이 내려 손님이 없던 날」","mis":"K5-1-u3-X39"},{"t":"「학교 앞 골목 끝에 작은 분식집이 있다.」","mis":"K5-1-u3-X39"}],"explanation":["때를 알려 주는 배경이에요.","날씨예요.","목요일과 국수가 이어지는 말이에요."],"asset":{"type":"passage","lines":["겨울이 되었다. 눈이 많이 내려 손님이 없던 날, 아주머니가 먼저","말을 꺼냈다. 「오래전에 목요일마다 오던 애가 있었어.」","그 아이는 늘 창가에 앉아 물만 마시다 갔다고 했다.","어느 날 아주머니가 국수 한 그릇을 놓아 주었고, 아이는 한참을","망설이다가 다 먹고 갔다. 그 뒤로 목요일마다 왔다.","「그러다 안 오더라. 이사 갔겠지.」 아주머니는 창밖을 보며 말했다."],"title":"「목요일의 국수」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#6','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C40',2,'mc','auto','로운이가 창가 식탁에 앉은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X43']::text[],false,'{"seq":6,"concept":"K5-1-u3-C40","difficulty":2,"kind":"mc","stem":"로운이가 창가 식탁에 앉은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아주머니의 마음을 알고 그 식탁을 채워 주고 싶어서","correct":true},{"t":"창가가 더 따뜻해서","mis":"K5-1-u3-X43"},{"t":"국수를 한 그릇 더 먹고 싶어서","mis":"K5-1-u3-X43"},{"t":"가운데 식탁이 더러워서","mis":"K5-1-u3-X43"}],"explanation":["이야기에 그런 근거가 없어요.","이야기에 그런 근거가 없어요.","아이 이야기를 들은 뒤 행동이 달라졌어요."],"asset":{"type":"passage","lines":["그다음 목요일, 로운이는 늘 앉던 가운데 식탁을 지나쳐 창가로 갔다.","그리고 김이 오르는 그 국수 앞에 앉았다.","아주머니가 놀란 얼굴로 돌아보았다. 「식으면 아깝잖아요.」","아주머니는 아무 말도 하지 않았다.","다만 국수를 삶는 냄비 앞에서 오래 서 있었다.","그날 이후로도 창가에는 목요일마다 국수가 놓였다.","다만 이제는 그릇이 비워졌다."],"title":"「목요일의 국수」 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#7','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C43',2,'mc','auto','아주머니에게 물을 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X42','K5-1-u3-X41']::text[],false,'{"seq":7,"concept":"K5-1-u3-C43","difficulty":2,"kind":"mc","stem":"아주머니에게 물을 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 아이가 다시 오지 않았을 때 어떤 마음이었나요?","correct":true},{"t":"분식집은 언제 처음 문을 열었나요?","mis":"K5-1-u3-X42"},{"t":"로운이의 학원은 어디에 있나요?","mis":"K5-1-u3-X41"},{"t":"오늘 날씨는 어떤가요?","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","아주머니에게 물을 것이 아니에요.","아주머니의 마음으로 들어가는 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#8','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C45',2,'ox','auto','인물이 되어 답할 때는 이야기와 상관없이 떠오르는 대로 답해도 돼요.',ARRAY['K5-1-u3-X43']::text[],false,'{"seq":8,"concept":"K5-1-u3-C45","difficulty":2,"kind":"ox","stem":"인물이 되어 답할 때는 이야기와 상관없이 떠오르는 대로 답해도 돼요.","answer":"X","reason_options":[{"t":"이야기에 나온 말과 행동을 근거로 답해야 인물의 마음에 가깝게 답할 수 있기 때문에","correct":true},{"t":"인물의 마음은 아무도 모르니 무엇이든 답이 되기 때문에","mis":"K5-1-u3-X43"}],"mis":"K5-1-u3-X43","explanation":["근거가 있어야 해요.","이야기 속 말과 행동을 봐요.","근거를 들어 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#9','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C46',2,'mc','auto','이야기를 나와 관련지어 말한 것은 어느 것인가요?',ARRAY['K5-1-u3-X44']::text[],false,'{"seq":9,"concept":"K5-1-u3-C46","difficulty":2,"kind":"mc","stem":"이야기를 나와 관련지어 말한 것은 어느 것인가요?","options":[{"t":"「나도 동생을 위해 말없이 우산을 챙겨 둔 적이 있어. 그때 마음이 아주머니와 비슷했을 것 같아.」","correct":true},{"t":"「이야기는 지어낸 거라 나와는 관계없어.」","mis":"K5-1-u3-X44"},{"t":"「국수는 맛있겠다.」","mis":"K5-1-u3-X44"},{"t":"「분식집에 가 본 적이 없어서 모르겠어.」","mis":"K5-1-u3-X44"}],"explanation":["나와 이어 보지 않았어요.","인물의 마음과 이어지지 않아요.","내 경험을 인물의 마음과 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_basic#10','kor',5,1,'u3','L09','g5_1_kor_u3_L09_basic','lesson_basic','K5-1-u3-C42',3,'mc','auto','「목요일의 국수」의 흐름을 차례대로 바르게 간추린 것은 어느 것인가요?',ARRAY['K5-1-u3-X40']::text[],false,'{"seq":10,"concept":"K5-1-u3-C42","difficulty":3,"kind":"mc","stem":"「목요일의 국수」의 흐름을 차례대로 바르게 간추린 것은 어느 것인가요?","options":[{"t":"국수 발견 → 까닭을 물으나 「그냥 버릇」 → 오래전 아이 이야기 → 로운이가 그 식탁에 앉음","correct":true},{"t":"오래전 아이 이야기 → 국수 발견 → 로운이가 그 식탁에 앉음 → 「그냥 버릇」","mis":"K5-1-u3-X40"},{"t":"국수 발견 → 로운이가 그 식탁에 앉음 → 「그냥 버릇」 → 오래전 아이 이야기","mis":"K5-1-u3-X40"},{"t":"로운이가 그 식탁에 앉음 → 국수 발견 → 오래전 아이 이야기 → 「그냥 버릇」","mis":"K5-1-u3-X40"}],"explanation":["아이 이야기는 겨울에 나와요.","앉은 것은 맨 끝이에요.","일어난 차례대로 간추렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#1','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C41',2,'mc','auto','「그냥 버릇이야.」라고 말한 뒤 아주머니가 보인 행동은 어느 것인가요?',ARRAY['K5-1-u3-X43','K5-1-u3-X39']::text[],false,'{"seq":1,"concept":"K5-1-u3-C41","difficulty":2,"kind":"mc","stem":"「그냥 버릇이야.」라고 말한 뒤 아주머니가 보인 행동은 어느 것인가요?","options":[{"t":"더 말하지 않고, 손님이 가면 그 그릇을 조용히 치웠다","correct":true},{"t":"로운이에게 까닭을 자세히 설명했다","mis":"K5-1-u3-X43"},{"t":"그 국수를 맛있게 먹었다","mis":"K5-1-u3-X43"},{"t":"분식집 문을 닫았다","mis":"K5-1-u3-X39"}],"explanation":["더 말하지 않았어요.","한 번도 먹지 않았어요.","말 대신 행동이 이어졌어요."],"asset":{"type":"passage","lines":["「저 식탁에는 누가 앉아요?」 로운이가 물었다.","아주머니는 국수를 삶던 손을 잠깐 멈추었다가 다시 젓가락을 저었다.","「그냥 버릇이야.」 그러고는 더 말하지 않았다.","로운이는 그 국수가 식어 가는 것을 오래 바라보았다.","아주머니는 손님이 다 가고 나면 그 그릇을 조용히 치웠다.","한 번도 먹지 않았다."],"title":"「목요일의 국수」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#2','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C44',2,'mc','auto','「목요일의 국수」 안에서 생각해 볼 수 있는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":2,"concept":"K5-1-u3-C44","difficulty":2,"kind":"mc","stem":"「목요일의 국수」 안에서 생각해 볼 수 있는 질문은 어느 것인가요?","options":[{"t":"그릇이 비워진 뒤 아주머니의 마음은 어떻게 달라졌을까요?","correct":true},{"t":"분식집 간판은 무슨 색인가요?","mis":"K5-1-u3-X42"},{"t":"로운이네 학교에는 몇 반까지 있나요?","mis":"K5-1-u3-X42"},{"t":"국수 한 그릇의 값은 얼마인가요?","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","이야기와 관계없어요.","이야기 속 말과 행동으로 생각해 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#3','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C43',3,'mc','auto','로운이에게 물을 질문 가운데 로운이의 의도를 파악하려는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X41','K5-1-u3-X42']::text[],false,'{"seq":3,"concept":"K5-1-u3-C43","difficulty":3,"kind":"mc","stem":"로운이에게 물을 질문 가운데 로운이의 의도를 파악하려는 질문은 어느 것인가요?","options":[{"t":"「식으면 아깝다고 말했을 때 진짜 하고 싶었던 말은 무엇인가요?」","correct":true},{"t":"「아주머니, 그 아이를 다시 만날 방법은 없을까요?」","mis":"K5-1-u3-X41"},{"t":"「그냥 버릇이라는 말은 어떤 뜻이었나요?」","mis":"K5-1-u3-X41"},{"t":"「국수 값은 누가 냈나요?」","mis":"K5-1-u3-X42"}],"explanation":["아주머니에게 묻는 질문이에요.","아주머니의 말을 묻고 있어요.","로운이가 왜 그렇게 말했는지 묻고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#4','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C43',3,'match','auto','「목요일의 국수」를 읽고 만든 질문과 그 목적을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u3-C43","difficulty":3,"kind":"match","stem":"「목요일의 국수」를 읽고 만든 질문과 그 목적을 이으세요.","pairs":[{"l":"국수를 계속 놓아 두시는 까닭이 무엇인가요?","r":"의도를 파악하기 위해서"},{"l":"그냥 버릇이라는 말은 어떤 뜻이었나요?","r":"명료하게 이해하기 위해서"},{"l":"그 아이를 다시 만날 방법은 없을까요?","r":"대안이나 정보를 찾기 위해서"}],"mis":"K5-1-u3-X31","explanation":["까닭을 묻고 있어요.","말의 뜻을 묻고 있어요.","다른 방법을 구하고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#5','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C40',3,'mc','auto','이 이야기를 읽으면 질문이 많이 생기는 까닭은 무엇인가요?',ARRAY['K5-1-u3-X38','K5-1-u3-X42']::text[],false,'{"seq":5,"concept":"K5-1-u3-C40","difficulty":3,"kind":"mc","stem":"이 이야기를 읽으면 질문이 많이 생기는 까닭은 무엇인가요?","options":[{"t":"아주머니가 까닭을 말하지 않고 행동으로만 마음을 보여 주기 때문이다","correct":true},{"t":"이야기에 어려운 낱말이 많기 때문이다","mis":"K5-1-u3-X38"},{"t":"이야기가 아주 길기 때문이다","mis":"K5-1-u3-X38"},{"t":"국수 값이 나오지 않기 때문이다","mis":"K5-1-u3-X42"}],"explanation":["낱말 때문이 아니에요.","길이 때문이 아니에요.","까닭이 적히지 않은 행동이 질문을 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#6','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C45',3,'error','auto','로운이가 되어 「왜 창가에 앉았나요?」에 답한 것이에요. 알맞지 않은 답은 어느 것인가요?',ARRAY['K5-1-u3-X43','K5-1-u3-X45']::text[],false,'{"seq":6,"concept":"K5-1-u3-C45","difficulty":3,"kind":"error","stem":"로운이가 되어 「왜 창가에 앉았나요?」에 답한 것이에요. 알맞지 않은 답은 어느 것인가요?","options":[{"t":"「가운데 식탁이 시끄러워서 옮겼어요.」","correct":true,"mis_target":"K5-1-u3-X43"},{"t":"「아주머니가 그 아이를 기다리시는 것 같아서 국수가 식지 않게 해 드리고 싶었어요.」","mis":"K5-1-u3-X45"},{"t":"「아이 이야기를 듣고 나니 그 국수가 그냥 남는 게 마음에 걸렸어요.」","mis":"K5-1-u3-X45"}],"explanation":["이야기 속 아주머니의 말을 근거로 했어요.","이야기 속 일을 근거로 했어요.","이야기에 그런 근거가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#7','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C46',3,'mc','auto','이야기를 자신과 관련지어 만든 질문은 어느 것인가요?',ARRAY['K5-1-u3-X42','K5-1-u3-X44']::text[],false,'{"seq":7,"concept":"K5-1-u3-C46","difficulty":3,"kind":"mc","stem":"이야기를 자신과 관련지어 만든 질문은 어느 것인가요?","options":[{"t":"「나도 누군가를 위해 까닭을 말하지 않고 한 일이 있는데, 아주머니는 왜 끝까지 말하지 않으셨을까요?」","correct":true},{"t":"「분식집은 몇 시에 문을 여나요?」","mis":"K5-1-u3-X42"},{"t":"「이야기는 지어낸 것이니 나와 상관없지 않나요?」","mis":"K5-1-u3-X44"},{"t":"「로운이는 국수를 좋아하나요? 나는 싫어하는데.」","mis":"K5-1-u3-X44"}],"explanation":["이야기와 관계없어요.","나와 이어 보지 않았어요.","내 경험과 인물의 마음을 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#8','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C41',4,'essay','teacher','아주머니의 마음을 짐작할 단서를 이야기에서 세 가지 찾아 쓰고, 그 단서로 짐작한 아주머니의 마음을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u3-C41","difficulty":4,"kind":"essay","stem":"아주머니의 마음을 짐작할 단서를 이야기에서 세 가지 찾아 쓰고, 그 단서로 짐작한 아주머니의 마음을 쓰세요.","answer_guide":{"answer":"예: 단서 — 목요일마다 한 그릇을 더 만든다 · 젓가락까지 가지런히 놓는다 · 그 국수를 한 번도 먹지 않는다. 짐작한 마음 — 오래전 목요일마다 오던 아이가 언젠가 다시 올까 기다리며, 그 아이를 잊지 않고 있는 마음이다.","scoring_points":["단서를 세 가지 찾았는가","단서가 인물의 말과 행동인가","단서로 마음을 짐작했는가"]},"explanation":["되풀이되는 행동을 찾아요.","배경은 단서가 아닐 수 있어요.","단서를 모아 마음을 짐작해요."],"asset":{"type":"passage","lines":["「저 식탁에는 누가 앉아요?」 로운이가 물었다.","아주머니는 국수를 삶던 손을 잠깐 멈추었다가 다시 젓가락을 저었다.","「그냥 버릇이야.」 그러고는 더 말하지 않았다.","로운이는 그 국수가 식어 가는 것을 오래 바라보았다.","아주머니는 손님이 다 가고 나면 그 그릇을 조용히 치웠다.","한 번도 먹지 않았다."],"title":"「목요일의 국수」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#9','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C43',4,'essay','teacher','아주머니와 로운이에게 각각 질문을 하나씩 만들고, 그 질문의 목적이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u3-C43","difficulty":4,"kind":"essay","stem":"아주머니와 로운이에게 각각 질문을 하나씩 만들고, 그 질문의 목적이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 아주머니에게 — 「그릇이 비워진 날 냄비 앞에 오래 서 계신 까닭은 무엇인가요?」 목적: 의도를 파악하기 위해서. 로운이에게 — 「식으면 아깝다는 말은 어떤 뜻이었나요?」 목적: 명료하게 이해하기 위해서.","scoring_points":["두 인물에게 하나씩 질문했는가","질문이 이야기와 이어지는가","질문의 목적을 썼는가"]},"explanation":["누구에게 물을지 정해요.","이야기 속에서 궁금한 곳을 찾아요.","목적을 밝혀요."],"asset":{"type":"passage","lines":["그다음 목요일, 로운이는 늘 앉던 가운데 식탁을 지나쳐 창가로 갔다.","그리고 김이 오르는 그 국수 앞에 앉았다.","아주머니가 놀란 얼굴로 돌아보았다. 「식으면 아깝잖아요.」","아주머니는 아무 말도 하지 않았다.","다만 국수를 삶는 냄비 앞에서 오래 서 있었다.","그날 이후로도 창가에는 목요일마다 국수가 놓였다.","다만 이제는 그릇이 비워졌다."],"title":"「목요일의 국수」 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L09_challenge#10','kor',5,1,'u3','L09','g5_1_kor_u3_L09_challenge','lesson_challenge','K5-1-u3-C45',4,'essay','teacher','아주머니가 되어 「그날 이후 목요일이 어떻게 달라졌나요?」라는 질문에 답하고, 이야기 속 어떤 말과 행동을 근거로 했는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C45","difficulty":4,"kind":"essay","stem":"아주머니가 되어 「그날 이후 목요일이 어떻게 달라졌나요?」라는 질문에 답하고, 이야기 속 어떤 말과 행동을 근거로 했는지 쓰세요.","answer_guide":{"answer":"예: 답 — 「예전에는 식어 가는 국수를 혼자 치웠는데, 이제는 그릇이 비워져서 목요일이 기다려져요.」 근거 — 「그날 이후로도 창가에는 목요일마다 국수가 놓였다. 다만 이제는 그릇이 비워졌다.」와 아주머니가 냄비 앞에 오래 서 있었던 행동이다.","scoring_points":["인물이 되어 답했는가","이야기 속 말과 행동을 근거로 들었는가","근거와 답이 이어지는가"]},"explanation":["아주머니의 처지에서 답해요.","이야기의 끝부분을 봐요.","근거를 밝혀요."],"asset":{"type":"passage","lines":["그다음 목요일, 로운이는 늘 앉던 가운데 식탁을 지나쳐 창가로 갔다.","그리고 김이 오르는 그 국수 앞에 앉았다.","아주머니가 놀란 얼굴로 돌아보았다. 「식으면 아깝잖아요.」","아주머니는 아무 말도 하지 않았다.","다만 국수를 삶는 냄비 앞에서 오래 서 있었다.","그날 이후로도 창가에는 목요일마다 국수가 놓였다.","다만 이제는 그릇이 비워졌다."],"title":"「목요일의 국수」 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#1','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C47',1,'mc','auto','조사하고 발표하는 활동에서 가장 먼저 할 일은 어느 것인가요?',ARRAY['K5-1-u3-X45']::text[],false,'{"seq":1,"concept":"K5-1-u3-C47","difficulty":1,"kind":"mc","stem":"조사하고 발표하는 활동에서 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"관심 있는 주제를 정한다","correct":true},{"t":"발표 자료를 만든다","mis":"K5-1-u3-X45"},{"t":"친구들 앞에서 발표한다","mis":"K5-1-u3-X45"},{"t":"질문을 주고받는다","mis":"K5-1-u3-X45"}],"explanation":["조사한 뒤에 만들어요.","자료를 만든 뒤에 해요.","주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#2','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C48',1,'mc','auto','조사해 볼 만한 주제로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X46']::text[],false,'{"seq":2,"concept":"K5-1-u3-C48","difficulty":1,"kind":"mc","stem":"조사해 볼 만한 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"학교 주변 안전 시설","correct":true},{"t":"친구의 집안 사정","mis":"K5-1-u3-X46"},{"t":"아직 아무도 모르는 미래의 일","mis":"K5-1-u3-X46"},{"t":"옆 반 친구의 시험 점수","mis":"K5-1-u3-X46"}],"explanation":["남의 사정이에요.","자료를 구할 수 없어요.","자료를 구할 수 있고 친구들에게 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#3','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C50',1,'mc','auto','더 믿을 수 있는 자료는 어느 것인가요?',ARRAY['K5-1-u3-X48']::text[],false,'{"seq":3,"concept":"K5-1-u3-C50","difficulty":1,"kind":"mc","stem":"더 믿을 수 있는 자료는 어느 것인가요?","options":[{"t":"기관 이름과 낸 때가 적힌 통계 자료","correct":true},{"t":"누가 썼는지 알 수 없는 게시글","mis":"K5-1-u3-X48"},{"t":"친구에게 전해 들은 이야기","mis":"K5-1-u3-X48"},{"t":"댓글이 많이 달린 글","mis":"K5-1-u3-X48"}],"explanation":["쓴 사람을 알 수 없어요.","확인되지 않은 말이에요.","만든 곳과 때가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#4','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C49',1,'match','auto','알고 싶은 것과 알맞은 조사 방법을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u3-C49","difficulty":1,"kind":"match","stem":"알고 싶은 것과 알맞은 조사 방법을 이으세요.","pairs":[{"l":"우리 학교 앞 횡단보도의 위치","r":"직접 관찰하기"},{"l":"우리나라 하루 물 사용량","r":"공공 기관 누리집 찾아보기"},{"l":"동네 어른들이 기억하는 옛 지명","r":"면담하기"}],"mis":"K5-1-u3-X47","explanation":["실제 모습은 직접 봐요.","나라 전체의 수치는 기관 자료예요.","기억은 직접 여쭈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#5','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C51',2,'mc','auto','발표를 들으며 질문할 수 있는 것을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u3-X49','K5-1-u3-X36']::text[],false,'{"seq":5,"concept":"K5-1-u3-C51","difficulty":2,"kind":"mc","stem":"발표를 들으며 질문할 수 있는 것을 바르게 말한 것은 어느 것인가요?","options":[{"t":"발표 내용 · 활용한 자료 · 자료를 만든 과정","correct":true},{"t":"발표 내용만","mis":"K5-1-u3-X49"},{"t":"발표자의 옷차림","mis":"K5-1-u3-X36"},{"t":"발표가 끝나면 물을 것이 없다","mis":"K5-1-u3-X49"}],"explanation":["자료와 만든 과정도 물을 수 있어요.","발표와 관계없어요.","세 가지 모두 물을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#6','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C47',2,'mc','auto','조사를 마친 뒤 바로 다음에 할 일은 어느 것인가요?',ARRAY['K5-1-u3-X45','K5-1-u3-X11']::text[],false,'{"seq":6,"concept":"K5-1-u3-C47","difficulty":2,"kind":"mc","stem":"조사를 마친 뒤 바로 다음에 할 일은 어느 것인가요?","options":[{"t":"발표에 필요한 자료를 선별한다","correct":true},{"t":"질문을 주고받는다","mis":"K5-1-u3-X45"},{"t":"관심 있는 주제를 정한다","mis":"K5-1-u3-X45"},{"t":"조사한 것을 모두 화면에 옮긴다","mis":"K5-1-u3-X11"}],"explanation":["맨 끝에 해요.","맨 처음에 해요.","조사한 것에서 필요한 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#7','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C49',2,'mc','auto','「생활 속 물 절약 방법」을 조사할 때 우리 집에서 물을 어떻게 쓰는지 알아보는 알맞은 방법은 어느 것인가요?',ARRAY['K5-1-u3-X46','K5-1-u3-X48','K5-1-u3-X47']::text[],false,'{"seq":7,"concept":"K5-1-u3-C49","difficulty":2,"kind":"mc","stem":"「생활 속 물 절약 방법」을 조사할 때 우리 집에서 물을 어떻게 쓰는지 알아보는 알맞은 방법은 어느 것인가요?","options":[{"t":"우리 집에서 물을 쓰는 모습을 직접 관찰한다","correct":true},{"t":"아무도 모르는 미래를 짐작해 적는다","mis":"K5-1-u3-X46"},{"t":"친구에게 들은 말을 그대로 쓴다","mis":"K5-1-u3-X48"},{"t":"관계없는 동물 도감을 찾아본다","mis":"K5-1-u3-X47"}],"explanation":["짐작은 조사가 아니에요.","확인되지 않은 말이에요.","실제 모습은 직접 관찰해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#8','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C50',2,'ox','auto','인터넷 게시글은 누가 썼는지 몰라도 내용이 그럴듯하면 발표에 써도 돼요.',ARRAY['K5-1-u3-X48']::text[],false,'{"seq":8,"concept":"K5-1-u3-C50","difficulty":2,"kind":"ox","stem":"인터넷 게시글은 누가 썼는지 몰라도 내용이 그럴듯하면 발표에 써도 돼요.","answer":"X","reason_options":[{"t":"누가 언제 낸 자료인지 알 수 없으면 사실인지 확인하기 어렵기 때문에","correct":true},{"t":"인터넷에 올라온 글은 모두 사실이기 때문에","mis":"K5-1-u3-X48"}],"mis":"K5-1-u3-X48","explanation":["그럴듯해도 확인이 필요해요.","사실이 아닌 글도 있어요.","만든 곳과 때를 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#9','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C48',2,'mc','auto','「친구의 집안 사정」이 조사 주제로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u3-X46','K5-1-u3-X22','K5-1-u3-X12']::text[],false,'{"seq":9,"concept":"K5-1-u3-C48","difficulty":2,"kind":"mc","stem":"「친구의 집안 사정」이 조사 주제로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"남의 사정을 함부로 알리는 일이고 친구들에게 도움이 되는 주제도 아니기 때문이다","correct":true},{"t":"자료가 너무 많기 때문이다","mis":"K5-1-u3-X46"},{"t":"발표 시간이 짧기 때문이다","mis":"K5-1-u3-X22"},{"t":"그래프로 나타낼 수 없기 때문이다","mis":"K5-1-u3-X12"}],"explanation":["양의 문제가 아니에요.","시간의 문제가 아니에요.","남의 사정은 조사 주제가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_basic#10','kor',5,1,'u3','L11','g5_1_kor_u3_L11_basic','lesson_basic','K5-1-u3-C51',3,'mc','auto','「질문이 오갈 때 발표는 비로소 완성된다」의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X49','K5-1-u3-X36']::text[],false,'{"seq":10,"concept":"K5-1-u3-C51","difficulty":3,"kind":"mc","stem":"「질문이 오갈 때 발표는 비로소 완성된다」의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"발표자의 설명과 듣는 사람의 질문과 답이 오가면서 내용이 더 분명해진다","correct":true},{"t":"질문만 하면 발표는 하지 않아도 된다","mis":"K5-1-u3-X49"},{"t":"질문이 없어야 좋은 발표이다","mis":"K5-1-u3-X49"},{"t":"질문은 발표자의 실수를 찾는 것이다","mis":"K5-1-u3-X36"}],"explanation":["발표가 먼저 있어야 해요.","질문이 발표를 채워요.","묻고 답하며 완성돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#1','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C20',2,'mc','auto','공공 기관 누리집의 자료를 발표에 쓸 때 함께 할 일은 어느 것인가요?',ARRAY['K5-1-u3-X19','K5-1-u3-X10']::text[],false,'{"seq":1,"concept":"K5-1-u3-C20","difficulty":2,"kind":"mc","stem":"공공 기관 누리집의 자료를 발표에 쓸 때 함께 할 일은 어느 것인가요?","options":[{"t":"어디에서 가져왔는지 출처를 적는다","correct":true},{"t":"믿을 수 있는 곳이니 출처는 적지 않는다","mis":"K5-1-u3-X19"},{"t":"수치를 조금 부풀려 쓴다","mis":"K5-1-u3-X10"},{"t":"내가 만든 자료라고 말한다","mis":"K5-1-u3-X19"}],"explanation":["믿을 수 있어도 출처는 적어요.","과장하면 안 돼요.","이름표를 달아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#2','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C47',2,'mc','auto','조사하고 발표하는 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X45']::text[],false,'{"seq":2,"concept":"K5-1-u3-C47","difficulty":2,"kind":"mc","stem":"조사하고 발표하는 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 조사하기 → 자료 선별하기 → 자료 만들기 → 발표하기 → 질문하기","correct":true},{"t":"조사하기 → 자료 만들기 → 주제 정하기 → 발표하기 → 자료 선별하기 → 질문하기","mis":"K5-1-u3-X45"},{"t":"자료 만들기 → 주제 정하기 → 조사하기 → 질문하기 → 발표하기 → 자료 선별하기","mis":"K5-1-u3-X45"},{"t":"주제 정하기 → 발표하기 → 조사하기 → 자료 선별하기 → 질문하기 → 자료 만들기","mis":"K5-1-u3-X45"}],"explanation":["주제가 먼저예요.","조사도 하기 전에 자료를 만들었어요.","차례대로 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#3','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C49',3,'mc','auto','「우리 지역의 옛 지명」을 조사할 때 가장 알맞게 짝지은 방법은 어느 것인가요?',ARRAY['K5-1-u3-X48','K5-1-u3-X47']::text[],false,'{"seq":3,"concept":"K5-1-u3-C49","difficulty":3,"kind":"mc","stem":"「우리 지역의 옛 지명」을 조사할 때 가장 알맞게 짝지은 방법은 어느 것인가요?","options":[{"t":"지역 어른들을 면담하고, 지역 기관 누리집이나 책에서 확인한다","correct":true},{"t":"옆 반 친구에게 한 번 물어보고 끝낸다","mis":"K5-1-u3-X48"},{"t":"아무 게시글 하나를 그대로 옮긴다","mis":"K5-1-u3-X48"},{"t":"학교 앞 횡단보도를 관찰한다","mis":"K5-1-u3-X47"}],"explanation":["확인이 부족해요.","누가 썼는지 몰라요.","면담과 믿을 만한 자료로 함께 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#4','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C48',3,'mc','auto','「학교 주변 안전 시설」이 좋은 조사 주제인 까닭은 무엇인가요?',ARRAY['K5-1-u3-X46','K5-1-u3-X13']::text[],false,'{"seq":4,"concept":"K5-1-u3-C48","difficulty":3,"kind":"mc","stem":"「학교 주변 안전 시설」이 좋은 조사 주제인 까닭은 무엇인가요?","options":[{"t":"직접 관찰하거나 믿을 만한 자료를 구할 수 있고 친구들의 안전에 도움이 되기 때문이다","correct":true},{"t":"아무도 알 수 없는 내용이라 신기하기 때문이다","mis":"K5-1-u3-X46"},{"t":"자료가 없어서 마음대로 쓸 수 있기 때문이다","mis":"K5-1-u3-X46"},{"t":"한 가지 자료 유형으로만 나타낼 수 있기 때문이다","mis":"K5-1-u3-X13"}],"explanation":["알 수 없으면 조사할 수 없어요.","마음대로 쓰면 조사가 아니에요.","자료를 구할 수 있고 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#5','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C51',3,'error','auto','발표가 끝난 뒤 질문을 주고받는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X49','K5-1-u3-X32','K5-1-u3-X35']::text[],false,'{"seq":5,"concept":"K5-1-u3-C51","difficulty":3,"kind":"error","stem":"발표가 끝난 뒤 질문을 주고받는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「발표 내용만 물을 수 있고 자료를 만든 과정은 물으면 안 돼.」","correct":true,"mis_target":"K5-1-u3-X49"},{"t":"「질문의 목적을 먼저 정하고 물어.」","mis":"K5-1-u3-X32"},{"t":"「무엇이 궁금한지 분명하게 물어.」","mis":"K5-1-u3-X35"}],"explanation":["맞는 말이에요.","맞는 말이에요.","자료와 만든 과정도 물을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#6','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C50',3,'mc','auto','「우리나라 하루 물 사용량」을 발표하려 할 때 가장 믿을 수 있는 자료는 어느 것인가요?',ARRAY['K5-1-u3-X48','K5-1-u3-X10']::text[],false,'{"seq":6,"concept":"K5-1-u3-C50","difficulty":3,"kind":"mc","stem":"「우리나라 하루 물 사용량」을 발표하려 할 때 가장 믿을 수 있는 자료는 어느 것인가요?","options":[{"t":"물 관리 기관 누리집에 올라온, 낸 때가 적힌 통계","correct":true},{"t":"물을 아껴 쓰자는 댓글","mis":"K5-1-u3-X48"},{"t":"누가 만들었는지 모르는 그림 한 장","mis":"K5-1-u3-X48"},{"t":"대충 어림해서 크게 부풀린 수","mis":"K5-1-u3-X10"}],"explanation":["의견일 뿐이에요.","만든 곳을 알 수 없어요.","만든 곳과 때가 드러난 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#7','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C12',3,'mc','auto','조사한 내용으로 발표 자료를 만들 때 하지 말아야 할 일은 어느 것인가요?',ARRAY['K5-1-u3-X15','K5-1-u3-X17','K5-1-u3-X19']::text[],false,'{"seq":7,"concept":"K5-1-u3-C12","difficulty":3,"kind":"mc","stem":"조사한 내용으로 발표 자료를 만들 때 하지 말아야 할 일은 어느 것인가요?","options":[{"t":"조사한 내용을 하나도 빼지 않고 모두 담는다","correct":true},{"t":"필요한 내용만 남기고 요약한다","mis":"K5-1-u3-X15"},{"t":"어려운 말은 쉬운 말로 바꾼다","mis":"K5-1-u3-X17"},{"t":"가져온 자료에 출처를 적는다","mis":"K5-1-u3-X19"}],"explanation":["해야 할 일이에요.","해야 할 일이에요.","모두 담으면 선별한 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#8','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C47',4,'essay','teacher','「생활 속 물 절약 방법」을 주제로 조사하고 발표하는 과정을 차례대로 계획해 쓰세요. 단계마다 무엇을 할지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u3-C47","difficulty":4,"kind":"essay","stem":"「생활 속 물 절약 방법」을 주제로 조사하고 발표하는 과정을 차례대로 계획해 쓰세요. 단계마다 무엇을 할지 쓰세요.","answer_guide":{"answer":"예: 주제 정하기 — 생활 속 물 절약 방법으로 정한다. 조사하기 — 우리 집에서 물 쓰는 모습을 관찰하고, 공공 기관 누리집에서 물 절약 안내를 찾아 출처를 적는다. 선별하기 — 발표에 필요한 방법 세 가지만 고른다. 자료 만들기 — 방법마다 사진 한 장과 짧은 글을 넣는다. 발표하기 — 시작하는 말과 끝맺는 말을 준비해 발표한다. 질문하기 — 친구들의 질문에 답한다.","scoring_points":["여섯 단계를 차례대로 썼는가","단계마다 할 일을 썼는가","출처 · 선별 · 질문을 빠뜨리지 않았는가"]},"explanation":["주제부터 시작해요.","조사 · 선별 · 자료 만들기를 나누어요.","발표 뒤 질문까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#9','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C50',4,'essay','teacher','「학교 주변 안전 시설」을 조사하며 찾은 자료 셋(가: 구청 누리집의 안전 지도, 나: 누가 썼는지 모르는 게시글, 다: 친구에게 들은 말) 가운데 발표에 쓸 자료를 고르고 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u3-C50","difficulty":4,"kind":"essay","stem":"「학교 주변 안전 시설」을 조사하며 찾은 자료 셋(가: 구청 누리집의 안전 지도, 나: 누가 썼는지 모르는 게시글, 다: 친구에게 들은 말) 가운데 발표에 쓸 자료를 고르고 까닭을 쓰세요.","answer_guide":{"answer":"예: 가를 고른다. 구청 누리집은 책임 있는 곳이 낸 자료라서 누가 언제 만들었는지 알 수 있고 믿을 수 있기 때문이다. 나는 누가 썼는지 알 수 없고, 다는 전해 들은 말이라 사실인지 확인하기 어렵다. 가를 쓸 때에도 출처를 적는다.","scoring_points":["믿을 수 있는 자료를 골랐는가","고른 까닭을 썼는가","고르지 않은 자료의 문제를 썼는가"]},"explanation":["누가 만든 자료인가요?","확인할 수 있나요?","까닭을 견주어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_L11_challenge#10','kor',5,1,'u3','L11','g5_1_kor_u3_L11_challenge','lesson_challenge','K5-1-u3-C51',4,'essay','teacher','친구의 「우리 지역의 옛 지명」 발표를 들었다고 생각하고, 발표 내용 · 활용한 자료 · 자료를 만든 과정에 대해 질문을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u3-C51","difficulty":4,"kind":"essay","stem":"친구의 「우리 지역의 옛 지명」 발표를 들었다고 생각하고, 발표 내용 · 활용한 자료 · 자료를 만든 과정에 대해 질문을 하나씩 쓰세요.","answer_guide":{"answer":"예: 발표 내용 — 「그 지명은 왜 그렇게 불리게 되었나요?」 활용한 자료 — 「옛 지도 사진은 어디에서 찾았나요?」 자료를 만든 과정 — 「어른들을 면담할 때 어떤 질문을 하셨나요?」","scoring_points":["세 가지에 대해 질문을 하나씩 썼는가","발표와 이어지는가","분명하게 표현했는가"]},"explanation":["내용에 대해 물어요.","자료에 대해 물어요.","만든 과정에 대해 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#1','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C54',1,'mc','auto','㉯의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?',ARRAY['K5-1-u3-X52','K5-1-u3-X51']::text[],false,'{"seq":1,"concept":"K5-1-u3-C54","difficulty":1,"kind":"mc","stem":"㉯의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?","options":[{"t":"반려","correct":true},{"t":"애완","mis":"K5-1-u3-X52"},{"t":"소유","mis":"K5-1-u3-X52"},{"t":"장난감","mis":"K5-1-u3-X51"}],"explanation":["즐기는 대상으로 보는 말이에요.","물건처럼 여기는 말이에요.","가족처럼 함께 지내는 동무로 보는 말이에요."],"asset":{"type":"passage","lines":["㉮ 시장 상인회와 동네 마트가 (협력 / 하청)하여 장보기 행사를 열었다.","㉯ 이모는 강아지를 (반려 / 애완)동물로 기르며 가족처럼 여긴다.","㉰ 미술 시간에 (살구색 / 살색) 물감으로 얼굴을 칠했다.","㉱ 오늘 학교에서 (학부모 / 학부형) 공개 수업이 열린다."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#2','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C55',1,'mc','auto','㉰의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?',ARRAY['K5-1-u3-X53','K5-1-u3-X51']::text[],false,'{"seq":2,"concept":"K5-1-u3-C55","difficulty":1,"kind":"mc","stem":"㉰의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?","options":[{"t":"살구색","correct":true},{"t":"살색","mis":"K5-1-u3-X53"},{"t":"피부색","mis":"K5-1-u3-X53"},{"t":"검은색","mis":"K5-1-u3-X51"}],"explanation":["한 가지 피부색만 「살」의 색이라고 여기는 말이에요.","사람마다 피부색이 달라요.","빛깔 그대로를 가리키는 말이에요."],"asset":{"type":"passage","lines":["㉮ 시장 상인회와 동네 마트가 (협력 / 하청)하여 장보기 행사를 열었다.","㉯ 이모는 강아지를 (반려 / 애완)동물로 기르며 가족처럼 여긴다.","㉰ 미술 시간에 (살구색 / 살색) 물감으로 얼굴을 칠했다.","㉱ 오늘 학교에서 (학부모 / 학부형) 공개 수업이 열린다."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#3','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C13',1,'mc','auto','지슬이의 발표 내용 ③을 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12']::text[],false,'{"seq":3,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"지슬이의 발표 내용 ③을 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"영상","correct":true},{"t":"표나 그래프","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X12"},{"t":"그림이나 사진","mis":"K5-1-u3-X12"}],"explanation":["수치가 아니에요.","설명이 아니에요.","날아오르는 움직임은 영상이 잘 보여 줘요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#4','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C33',1,'mc','auto','율비에게 「복도 걷기 도우미를 두자고 하신 까닭이 무엇인가요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X31','K5-1-u3-X36']::text[],false,'{"seq":4,"concept":"K5-1-u3-C33","difficulty":1,"kind":"mc","stem":"율비에게 「복도 걷기 도우미를 두자고 하신 까닭이 무엇인가요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"의도를 파악하기 위해서","correct":true},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X31"},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X31"},{"t":"율비를 깎아내리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["뜻을 묻지 않아요.","다른 방법을 구하지 않아요.","왜 제안했는지 묻고 있어요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#5','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C13',1,'mc','auto','「우리 지역 여름 축제」 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12','K5-1-u3-X08']::text[],false,'{"seq":5,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"「우리 지역 여름 축제」 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"표나 그래프","correct":true},{"t":"영상","mis":"K5-1-u3-X12"},{"t":"그림이나 사진","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X08"}],"explanation":["움직임이 아니에요.","모습이 아니에요.","해마다 달라진 사람 수는 표나 그래프예요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#6','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C15',1,'mc','auto','지슬이가 발표 내용 ④에 쓸 단락은 어느 것인가요?',ARRAY['K5-1-u3-X14']::text[],false,'{"seq":6,"concept":"K5-1-u3-C15","difficulty":1,"kind":"mc","stem":"지슬이가 발표 내용 ④에 쓸 단락은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"K5-1-u3-X14"},{"t":"㉰","mis":"K5-1-u3-X14"},{"t":"㉱","mis":"K5-1-u3-X14"}],"explanation":["쉼터의 뜻과 생긴 곳이에요.","마을 사람들이 하는 일이에요.","큰고니의 생김새가 담겼어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#7','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C44',1,'mc','auto','「담 너머」의 인물에게 할 만한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":7,"concept":"K5-1-u3-C44","difficulty":1,"kind":"mc","stem":"「담 너머」의 인물에게 할 만한 질문은 어느 것인가요?","options":[{"t":"「담 너머를 왜 그렇게 궁금해했나요?」","correct":true},{"t":"「담의 높이는 몇 센티미터인가요?」","mis":"K5-1-u3-X42"},{"t":"「나비의 날개는 무슨 색인가요?」","mis":"K5-1-u3-X42"},{"t":"「두더지는 몇 살인가요?」","mis":"K5-1-u3-X42"}],"explanation":["글 안에서 생각해 볼 수 없어요.","글과 관계없는 사실이에요.","인물의 마음으로 들어가는 질문이에요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#8','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C27',1,'mc','auto','지슬이의 시작하는 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X26']::text[],false,'{"seq":8,"concept":"K5-1-u3-C27","difficulty":1,"kind":"mc","stem":"지슬이의 시작하는 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"K5-1-u3-X26"},{"t":"나","mis":"K5-1-u3-X26"},{"t":"세 가지 모두 똑같이 알맞다","mis":"K5-1-u3-X26"}],"explanation":["핑계로 시작했어요.","인사 없이 바로 본론이에요.","주제와 조사한 까닭이 담겼어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"음…… 준비를 많이 못 했는데 그냥 해 보겠습니다."},{"who":"나","text":"철새는 계절에 따라 사는 곳을 옮기는 새로, 마을 저수지는 물이 얕아……."},{"who":"다","text":"안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울 방학에 저수지에서 새 떼를 본 뒤로 궁금해져 조사해 보았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#9','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C18',2,'mc','auto','㉮의 「도래하는」을 뜻은 그대로 두고 쉬운 말로 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":9,"concept":"K5-1-u3-C18","difficulty":2,"kind":"mc","stem":"㉮의 「도래하는」을 뜻은 그대로 두고 쉬운 말로 바꾼 것은 어느 것인가요?","options":[{"t":"날아오는","correct":true},{"t":"떠나는","mis":"K5-1-u3-X17"},{"t":"사라지는","mis":"K5-1-u3-X17"},{"t":"태어나는","mis":"K5-1-u3-X17"}],"explanation":["뜻이 거꾸로예요.","뜻이 달라져요.","찾아 날아온다는 뜻 그대로예요."],"asset":{"type":"passage","lines":["㉮ 철새가 도래하는 때는 늦가을이다.","㉯ 큰고니는 이 저수지에서 월동한다.","㉰ 해마다 찾아오는 새의 개체 수가 감소하고 있다."],"title":"지슬이의 발표 원고 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#10','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C25',2,'mc','auto','지슬이의 첫 발표 화면에서 고칠 점이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u3-X24','K5-1-u3-X19']::text[],false,'{"seq":10,"concept":"K5-1-u3-C25","difficulty":2,"kind":"mc","stem":"지슬이의 첫 발표 화면에서 고칠 점이 아닌 것은 어느 것인가요?","options":[{"t":"큰고니 사진을 넣었다는 것","correct":true},{"t":"한 화면에 내용이 너무 많다는 것","mis":"K5-1-u3-X24"},{"t":"글씨가 작다는 것","mis":"K5-1-u3-X24"},{"t":"사진의 출처가 없다는 것","mis":"K5-1-u3-X19"}],"explanation":["고쳐야 할 점이에요.","고쳐야 할 점이에요.","사진을 넣은 것 자체는 잘못이 아니에요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#11','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C31',2,'match','auto','율비네 학급 회의에서 나온 제안과 까닭을 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K5-1-u3-C31","difficulty":2,"kind":"match","stem":"율비네 학급 회의에서 나온 제안과 까닭을 이으세요.","pairs":[{"l":"복도 걷기 도우미","r":"뛰다가 부딪혀 넘어지는 일이 잦아서"},{"l":"학급 문고 정리 당번","r":"책이 아무렇게나 꽂혀 찾기 어려워서"},{"l":"모둠별 화분 기르기","r":"물을 주는 사람이 없어 화분이 시들어서"}],"mis":"K5-1-u3-X30","explanation":["율비는 넘어지는 일을 문제로 보았어요.","하설이는 찾기 어려운 것을 문제로 보았어요.","려원이는 시드는 화분을 문제로 보았어요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#12','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C41',2,'mc','auto','려원이의 마음을 짐작할 단서로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X39']::text[],false,'{"seq":12,"concept":"K5-1-u3-C41","difficulty":2,"kind":"mc","stem":"려원이의 마음을 짐작할 단서로 알맞은 것은 어느 것인가요?","options":[{"t":"비가 오는 날에도 가장 먼저 와서 화분부터 살폈다","correct":true},{"t":"화분이 창틀 끝에 있다","mis":"K5-1-u3-X39"},{"t":"누구 것인지 아무도 몰랐다","mis":"K5-1-u3-X39"},{"t":"한율이가 일찍 학교에 왔다","mis":"K5-1-u3-X39"}],"explanation":["배경이에요.","반 아이들의 모습이에요.","되풀이하는 행동에 마음이 담겼어요."],"asset":{"type":"passage","lines":["「그거 네 거야?」 한율이가 물었다. 려원이는 고개를 저었다.","「아니. 그냥 내가 주는 거야.」 그러고는 물병을 가방에 넣었다.","비가 오는 날에도, 시험이 있는 날에도 려원이는 가장 먼저 와서","화분부터 살폈다."],"title":"이야기 「창틀의 화분」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#13','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C43',2,'mc','auto','려원이에게 물을 질문으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X42','K5-1-u3-X41']::text[],false,'{"seq":13,"concept":"K5-1-u3-C43","difficulty":2,"kind":"mc","stem":"려원이에게 물을 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「「그냥 내가 주는 거야」라고만 말한 까닭은 무엇인가요?」","correct":true},{"t":"「물병은 어디에서 샀나요?」","mis":"K5-1-u3-X42"},{"t":"「한율이는 몇 시에 일어나나요?」","mis":"K5-1-u3-X41"},{"t":"「교실은 몇 층인가요?」","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","려원이에게 물을 것이 아니에요.","려원이의 말 속 마음을 묻는 질문이에요."],"asset":{"type":"passage","lines":["「그거 네 거야?」 한율이가 물었다. 려원이는 고개를 저었다.","「아니. 그냥 내가 주는 거야.」 그러고는 물병을 가방에 넣었다.","비가 오는 날에도, 시험이 있는 날에도 려원이는 가장 먼저 와서","화분부터 살폈다."],"title":"이야기 「창틀의 화분」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#14','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C50',2,'mc','auto','지슬이가 「해마다 쉼터를 찾아온 새의 수」를 조사할 때 가장 믿을 수 있는 자료는 어느 것인가요?',ARRAY['K5-1-u3-X48']::text[],false,'{"seq":14,"concept":"K5-1-u3-C50","difficulty":2,"kind":"mc","stem":"지슬이가 「해마다 쉼터를 찾아온 새의 수」를 조사할 때 가장 믿을 수 있는 자료는 어느 것인가요?","options":[{"t":"지역 환경 기관 누리집에 올라온, 낸 때가 적힌 조사 자료","correct":true},{"t":"누가 썼는지 모르는 게시글","mis":"K5-1-u3-X48"},{"t":"지나가던 사람에게 들은 말","mis":"K5-1-u3-X48"},{"t":"새를 좋아하는 친구의 짐작","mis":"K5-1-u3-X48"}],"explanation":["쓴 사람을 알 수 없어요.","확인되지 않은 말이에요.","만든 곳과 때가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#15','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C14',2,'ox','auto','지슬이의 발표 내용 ③은 영상이 없으면 발표할 수 없어요.',ARRAY['K5-1-u3-X13']::text[],false,'{"seq":15,"concept":"K5-1-u3-C14","difficulty":2,"kind":"ox","stem":"지슬이의 발표 내용 ③은 영상이 없으면 발표할 수 없어요.","answer":"X","reason_options":[{"t":"날아오르기 전과 뒤의 사진을 나란히 보여 주는 것처럼 다른 유형으로도 전할 수 있기 때문에","correct":true},{"t":"한 내용에는 정해진 유형 하나만 쓸 수 있기 때문에","mis":"K5-1-u3-X13"}],"mis":"K5-1-u3-X13","explanation":["다른 유형으로도 전할 수 있어요.","정답 유형이 하나로 정해져 있지 않아요.","내용을 잘 전하는가가 중요해요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#16','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C53',2,'mc','auto','「우리 주변에서 바꾸어 쓸 말을 찾아봅니다」에 맞게 말한 것은 어느 것인가요?',ARRAY['K5-1-u3-X51','K5-1-u3-X53']::text[],false,'{"seq":16,"concept":"K5-1-u3-C53","difficulty":2,"kind":"mc","stem":"「우리 주변에서 바꾸어 쓸 말을 찾아봅니다」에 맞게 말한 것은 어느 것인가요?","options":[{"t":"「누군가를 낮추거나 빠뜨리는 말은 함께함을 담은 말로 바꾸어 써야겠어.」","correct":true},{"t":"「뜻만 통하면 아무 말이나 괜찮아.」","mis":"K5-1-u3-X51"},{"t":"「오래 써 온 말은 바꿀 필요가 없어.」","mis":"K5-1-u3-X53"},{"t":"「짧은 말이 늘 더 좋아.」","mis":"K5-1-u3-X51"}],"explanation":["낱말에는 태도가 담겨요.","오래 썼어도 고칠 말이 있어요.","누구를 어떻게 부르는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#17','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C52',3,'mc','auto','「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X50','K5-1-u3-X49']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"mc","stem":"「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"발표하는 사람은 예상 질문을 준비하고, 듣는 사람은 자료와 내용을 집중해 들으며 질문을 만든다","correct":true},{"t":"발표하는 사람은 질문을 받지 않고, 듣는 사람은 조용히 있는다","mis":"K5-1-u3-X50"},{"t":"발표 공부와 질문 공부는 서로 관계없다","mis":"K5-1-u3-X50"},{"t":"질문은 이야기를 읽을 때만 한다","mis":"K5-1-u3-X49"}],"explanation":["질문이 빠졌어요.","두 공부는 한 짝이에요.","발표와 질문이 맞물려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#18','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C23',3,'mc','auto','지슬이가 「우리 마을 철새 쉼터」를 주제로 고른 것이 알맞은 까닭은 무엇인가요?',ARRAY['K5-1-u3-X22','K5-1-u3-X01']::text[],false,'{"seq":18,"concept":"K5-1-u3-C23","difficulty":3,"kind":"mc","stem":"지슬이가 「우리 마을 철새 쉼터」를 주제로 고른 것이 알맞은 까닭은 무엇인가요?","options":[{"t":"너무 넓지도 좁지도 않아 짧은 발표 시간에 자료를 모아 다루기 좋기 때문이다","correct":true},{"t":"세상의 모든 새를 다룰 수 있기 때문이다","mis":"K5-1-u3-X22"},{"t":"큰고니 깃털 한 개만 다루기 때문이다","mis":"K5-1-u3-X22"},{"t":"아무 자료도 필요 없기 때문이다","mis":"K5-1-u3-X01"}],"explanation":["너무 넓은 주제가 아니에요.","너무 좁은 주제가 아니에요.","알맞은 크기의 주제예요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#19','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C42',3,'mc','auto','「창틀의 화분」의 흐름을 차례대로 바르게 간추린 것은 어느 것인가요?',ARRAY['K5-1-u3-X40']::text[],false,'{"seq":19,"concept":"K5-1-u3-C42","difficulty":3,"kind":"mc","stem":"「창틀의 화분」의 흐름을 차례대로 바르게 간추린 것은 어느 것인가요?","options":[{"t":"촉촉한 흙의 수수께끼 → 「그냥 내가 주는 거야」 → 전학 간 친구와의 약속 → 함께 물 주기와 꽃","correct":true},{"t":"전학 간 친구와의 약속 → 촉촉한 흙의 수수께끼 → 함께 물 주기와 꽃 → 「그냥 내가 주는 거야」","mis":"K5-1-u3-X40"},{"t":"함께 물 주기와 꽃 → 「그냥 내가 주는 거야」 → 촉촉한 흙의 수수께끼 → 전학 간 친구와의 약속","mis":"K5-1-u3-X40"},{"t":"촉촉한 흙의 수수께끼 → 함께 물 주기와 꽃 → 전학 간 친구와의 약속 → 「그냥 내가 주는 거야」","mis":"K5-1-u3-X40"}],"explanation":["약속은 셋째에 드러나요.","꽃은 맨 끝이에요.","일어난 차례대로 간추렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#20','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C28',3,'mc','auto','지슬이의 발표에서 나올 법한 예상 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X27']::text[],false,'{"seq":20,"concept":"K5-1-u3-C28","difficulty":3,"kind":"mc","stem":"지슬이의 발표에서 나올 법한 예상 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「갈대 울타리를 치면 새들이 왜 덜 놀라나요?」","correct":true},{"t":"「지슬이는 무슨 음식을 좋아하나요?」","mis":"K5-1-u3-X27"},{"t":"「빵집은 몇 시에 문을 여나요?」","mis":"K5-1-u3-X27"},{"t":"「내일 날씨는 어떤가요?」","mis":"K5-1-u3-X27"}],"explanation":["발표와 관계없어요.","발표에서 뺀 내용이에요.","발표 내용 ①과 ㉰에서 나올 질문이에요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#21','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C39',3,'ox','auto','「쉼터를 만들어서 마을에 어떤 변화가 생기기를 바라나요?」는 한 가지 목적으로만 나눌 수 있어요.',ARRAY['K5-1-u3-X37']::text[],false,'{"seq":21,"concept":"K5-1-u3-C39","difficulty":3,"kind":"ox","stem":"「쉼터를 만들어서 마을에 어떤 변화가 생기기를 바라나요?」는 한 가지 목적으로만 나눌 수 있어요.","answer":"X","reason_options":[{"t":"왜 쉼터를 만들었는지 의도를 묻는 동시에 앞으로의 변화에 대한 정보도 구하는 질문이기 때문에","correct":true},{"t":"질문은 언제나 한 가지 목적에만 들어가기 때문에","mis":"K5-1-u3-X37"}],"mis":"K5-1-u3-X37","explanation":["두 목적에 걸쳐요.","갈래 맞히기가 목적이 아니에요.","무엇을 알고 싶은지가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#22','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C7',3,'mc','auto','지슬이가 큰고니에 대해 깊이 있는 답을 듣고 싶을 때 알맞은 조사 방법과 그 특징을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u3-X06','K5-1-u3-X48']::text[],false,'{"seq":22,"concept":"K5-1-u3-C7","difficulty":3,"kind":"mc","stem":"지슬이가 큰고니에 대해 깊이 있는 답을 듣고 싶을 때 알맞은 조사 방법과 그 특징을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"새를 연구하는 전문가에게 묻기 — 깊이 있는 답을 들을 수 있으나 만나기 어렵다","correct":true},{"t":"인터넷에서 찾기 — 늘 사실이라 확인할 필요가 없다","mis":"K5-1-u3-X06"},{"t":"책에서 찾기 — 언제나 가장 새로운 정보가 있다","mis":"K5-1-u3-X06"},{"t":"친구에게 묻기 — 전해 들은 말이라도 그대로 믿을 수 있다","mis":"K5-1-u3-X48"}],"explanation":["인터넷은 사실인지 확인해야 해요.","책은 최신 정보가 적을 수 있어요.","전문가에게서 깊이 있는 답을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#23','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C16',4,'essay','teacher','지슬이의 글 자료에서 발표에 쓸 단락과 뺄 단락을 고르고, 쓸 단락 하나를 발표 화면에 넣을 수 있게 요약하세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C16","difficulty":4,"kind":"essay","stem":"지슬이의 글 자료에서 발표에 쓸 단락과 뺄 단락을 고르고, 쓸 단락 하나를 발표 화면에 넣을 수 있게 요약하세요.","answer_guide":{"answer":"예: 쓸 단락 — ㉮ · ㉯ · ㉰, 뺄 단락 — ㉱(빵집은 철새 쉼터와 관계없다). ㉰ 요약 — 겨울마다 볍씨를 뿌려 먹이를 나눔 · 새가 놀라지 않게 갈대 울타리를 침.","scoring_points":["쓸 단락과 뺄 단락을 바르게 골랐는가","뺀 까닭을 썼는가","필요한 내용만 남겨 요약했는가"]},"explanation":["발표 주제와 이어지는지 봐요.","관계없는 것은 덜어요.","필요한 것만 남겨요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#24','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C54',4,'essay','teacher','「알맞은 낱말 고르기」의 ㉮~㉱에서 더 바람직한 낱말을 하나씩 고르고, 그 가운데 둘을 골라 왜 바람직한지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C54","difficulty":4,"kind":"essay","stem":"「알맞은 낱말 고르기」의 ㉮~㉱에서 더 바람직한 낱말을 하나씩 고르고, 그 가운데 둘을 골라 왜 바람직한지 쓰세요.","answer_guide":{"answer":"예: ㉮ 협력 · ㉯ 반려 · ㉰ 살구색 · ㉱ 학부모. 「반려」는 동물을 즐기는 대상이 아니라 함께 사는 동무로 여기는 태도를 담는다. 「학부모」는 아버지와 형만이 아니라 학생의 보호자를 두루 가리켜 누군가를 빠뜨리지 않는다.","scoring_points":["네 낱말을 바르게 골랐는가","둘을 골라 까닭을 썼는가","낱말에 담긴 태도로 설명했는가"]},"explanation":["누구를 어떻게 부르는지 봐요.","함께함을 담은 말을 골라요.","빠뜨리는 사람이 없는지 봐요."],"asset":{"type":"passage","lines":["㉮ 시장 상인회와 동네 마트가 (협력 / 하청)하여 장보기 행사를 열었다.","㉯ 이모는 강아지를 (반려 / 애완)동물로 기르며 가족처럼 여긴다.","㉰ 미술 시간에 (살구색 / 살색) 물감으로 얼굴을 칠했다.","㉱ 오늘 학교에서 (학부모 / 학부형) 공개 수업이 열린다."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_a#25','kor',5,1,'u3','','g5_1_kor_u3_review_a','unit_review','K5-1-u3-C52',4,'essay','teacher','이 단원에서 배운 「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 어떻게 이어지는지 지슬이의 발표를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C52","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「자료를 선별하여 발표하기」와 「궁금한 내용 질문하기」가 어떻게 이어지는지 지슬이의 발표를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 지슬이는 철새 쉼터 발표에 맞는 자료를 골라 요약하고, 새의 수가 줄어든 까닭 같은 예상 질문을 미리 준비한다. 듣는 친구들은 지슬이의 자료와 말을 집중해 듣고 「큰고니 사진은 어디에서 찾았나요?」처럼 목적에 맞게 분명히 묻는다. 질문과 답이 오가면서 발표가 완성되므로 두 공부는 한 짝이다.","scoring_points":["발표하는 쪽의 할 일을 썼는가","듣고 질문하는 쪽의 할 일을 썼는가","둘이 이어지는 까닭을 지슬이의 예로 썼는가"]},"explanation":["발표하는 사람은 무엇을 준비하나요?","듣는 사람은 무엇을 하나요?","두 쪽이 어떻게 만나나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#1','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C54',1,'mc','auto','㉮의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?',ARRAY['K5-1-u3-X52','K5-1-u3-X51']::text[],false,'{"seq":1,"concept":"K5-1-u3-C54","difficulty":1,"kind":"mc","stem":"㉮의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?","options":[{"t":"협력","correct":true},{"t":"하청","mis":"K5-1-u3-X52"},{"t":"지시","mis":"K5-1-u3-X51"},{"t":"명령","mis":"K5-1-u3-X51"}],"explanation":["아래에서 일을 맡는다는 말이에요.","위아래를 가르는 말이에요.","힘을 합하여 서로 돕는다는 말이에요."],"asset":{"type":"passage","lines":["㉮ 시장 상인회와 동네 마트가 (협력 / 하청)하여 장보기 행사를 열었다.","㉯ 이모는 강아지를 (반려 / 애완)동물로 기르며 가족처럼 여긴다.","㉰ 미술 시간에 (살구색 / 살색) 물감으로 얼굴을 칠했다.","㉱ 오늘 학교에서 (학부모 / 학부형) 공개 수업이 열린다."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#2','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C55',1,'mc','auto','㉱의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?',ARRAY['K5-1-u3-X53','K5-1-u3-X51']::text[],false,'{"seq":2,"concept":"K5-1-u3-C55","difficulty":1,"kind":"mc","stem":"㉱의 빈칸에 들어갈 더 바람직한 낱말은 어느 것인가요?","options":[{"t":"학부모","correct":true},{"t":"학부형","mis":"K5-1-u3-X53"},{"t":"학생의 아버지","mis":"K5-1-u3-X53"},{"t":"학형","mis":"K5-1-u3-X51"}],"explanation":["아버지와 형만 가리키는 말이에요.","어머니를 빠뜨렸어요.","보호자를 두루 가리켜요."],"asset":{"type":"passage","lines":["㉮ 시장 상인회와 동네 마트가 (협력 / 하청)하여 장보기 행사를 열었다.","㉯ 이모는 강아지를 (반려 / 애완)동물로 기르며 가족처럼 여긴다.","㉰ 미술 시간에 (살구색 / 살색) 물감으로 얼굴을 칠했다.","㉱ 오늘 학교에서 (학부모 / 학부형) 공개 수업이 열린다."],"title":"알맞은 낱말 고르기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#3','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C13',1,'mc','auto','지슬이의 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12','K5-1-u3-X08']::text[],false,'{"seq":3,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"지슬이의 발표 내용 ②를 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"표나 그래프","correct":true},{"t":"영상","mis":"K5-1-u3-X12"},{"t":"그림이나 사진","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X08"}],"explanation":["움직임이 아니에요.","생김새가 아니에요.","해마다 달라진 수치는 표나 그래프예요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#4','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C34',1,'mc','auto','하설이에게 「정리 당번은 책을 꽂기만 하나요, 찢어진 책도 고치나요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X32','K5-1-u3-X36']::text[],false,'{"seq":4,"concept":"K5-1-u3-C34","difficulty":1,"kind":"mc","stem":"하설이에게 「정리 당번은 책을 꽂기만 하나요, 찢어진 책도 고치나요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"명료하게 이해하기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X32"},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X32"},{"t":"회의를 빨리 끝내기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","다른 방법을 구하지 않아요.","당번이 하는 일을 또렷이 하려는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#5','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C13',1,'mc','auto','「우리 지역 여름 축제」 발표 내용 ③을 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12','K5-1-u3-X13']::text[],false,'{"seq":5,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"「우리 지역 여름 축제」 발표 내용 ③을 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"영상","correct":true},{"t":"표나 그래프","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X12"},{"t":"그림이나 사진","mis":"K5-1-u3-X13"}],"explanation":["수치가 아니에요.","설명이 아니에요.","공연은 움직임이라 영상이 잘 보여 줘요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#6','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C17',1,'mc','auto','지슬이의 글 자료에서 발표 주제와 관계없어 빼야 할 단락은 어느 것인가요?',ARRAY['K5-1-u3-X16']::text[],false,'{"seq":6,"concept":"K5-1-u3-C17","difficulty":1,"kind":"mc","stem":"지슬이의 글 자료에서 발표 주제와 관계없어 빼야 할 단락은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"K5-1-u3-X16"},{"t":"㉯","mis":"K5-1-u3-X16"},{"t":"㉰","mis":"K5-1-u3-X16"}],"explanation":["발표 내용 ①과 이어져요.","발표 내용 ④와 이어져요.","빵집은 철새 쉼터와 관계없어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#7','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C34',1,'mc','auto','「담 너머」를 읽고 「내가 세우는 담이란 어떤 뜻인가요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X32','K5-1-u3-X36']::text[],false,'{"seq":7,"concept":"K5-1-u3-C34","difficulty":1,"kind":"mc","stem":"「담 너머」를 읽고 「내가 세우는 담이란 어떤 뜻인가요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"명료하게 이해하기 위해서","correct":true},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X32"},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X32"},{"t":"나비를 놀리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["다른 방법을 구하지 않아요.","왜 했는지보다 말의 뜻을 물어요.","흐릿한 말의 뜻을 또렷이 하려는 질문이에요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#8','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C27',1,'mc','auto','지슬이의 시작하는 말 「가」가 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u3-X26']::text[],false,'{"seq":8,"concept":"K5-1-u3-C27","difficulty":1,"kind":"mc","stem":"지슬이의 시작하는 말 「가」가 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"무엇을 왜 발표하는지 없이 핑계부터 댔기 때문이다","correct":true},{"t":"너무 길기 때문이다","mis":"K5-1-u3-X26"},{"t":"질문 안내가 빠졌기 때문이다","mis":"K5-1-u3-X26"},{"t":"철새를 설명했기 때문이다","mis":"K5-1-u3-X26"}],"explanation":["길이 때문이 아니에요.","질문 안내는 끝맺는 말에 담아요.","주제와 까닭이 없어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"음…… 준비를 많이 못 했는데 그냥 해 보겠습니다."},{"who":"나","text":"철새는 계절에 따라 사는 곳을 옮기는 새로, 마을 저수지는 물이 얕아……."},{"who":"다","text":"안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울 방학에 저수지에서 새 떼를 본 뒤로 궁금해져 조사해 보았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#9','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C18',2,'mc','auto','㉯의 「월동한다」를 쉬운 말로 알맞게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":9,"concept":"K5-1-u3-C18","difficulty":2,"kind":"mc","stem":"㉯의 「월동한다」를 쉬운 말로 알맞게 바꾼 것은 어느 것인가요?","options":[{"t":"겨울을 난다","correct":true},{"t":"달을 본다","mis":"K5-1-u3-X17"},{"t":"겨울에 떠난다","mis":"K5-1-u3-X17"},{"t":"잠만 잔다","mis":"K5-1-u3-X17"}],"explanation":["낱자의 뜻만 보면 안 돼요.","머무는 것이지 떠나는 것이 아니에요.","겨울을 지낸다는 뜻 그대로예요."],"asset":{"type":"passage","lines":["㉮ 철새가 도래하는 때는 늦가을이다.","㉯ 큰고니는 이 저수지에서 월동한다.","㉰ 해마다 찾아오는 새의 개체 수가 감소하고 있다."],"title":"지슬이의 발표 원고 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#10','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C26',2,'mc','auto','지슬이의 첫 화면으로 발표하면 어떤 일이 생길까요?',ARRAY['K5-1-u3-X25']::text[],false,'{"seq":10,"concept":"K5-1-u3-C26","difficulty":2,"kind":"mc","stem":"지슬이의 첫 화면으로 발표하면 어떤 일이 생길까요?","options":[{"t":"듣는 사람이 지슬이를 보지 않고 화면의 글만 읽게 된다","correct":true},{"t":"듣는 사람이 지슬이의 말에 더 집중한다","mis":"K5-1-u3-X25"},{"t":"발표가 짧고 분명해진다","mis":"K5-1-u3-X25"},{"t":"자료가 많아 더 좋은 발표가 된다","mis":"K5-1-u3-X25"}],"explanation":["글이 많으면 화면만 봐요.","오히려 흐려져요.","자료는 많을수록 좋은 것이 아니에요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#11','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C37',2,'mc','auto','하설이의 제안에 대해 더 분명하게 표현한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X35']::text[],false,'{"seq":11,"concept":"K5-1-u3-C37","difficulty":2,"kind":"mc","stem":"하설이의 제안에 대해 더 분명하게 표현한 질문은 어느 것인가요?","options":[{"t":"「정리 당번은 무슨 요일에 몇 명이 하나요?」","correct":true},{"t":"「그거 좀 그렇지 않아요?」","mis":"K5-1-u3-X35"},{"t":"「어떻게 되는 건가요?」","mis":"K5-1-u3-X35"},{"t":"「좀 애매한데요?」","mis":"K5-1-u3-X35"}],"explanation":["무엇이 궁금한지 알 수 없어요.","흐릿해요.","무엇을 알고 싶은지 또렷해요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#12','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C40',2,'mc','auto','「창틀의 화분」 ①에서 한율이가 궁금해할 만한 것은 무엇인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":12,"concept":"K5-1-u3-C40","difficulty":2,"kind":"mc","stem":"「창틀의 화분」 ①에서 한율이가 궁금해할 만한 것은 무엇인가요?","options":[{"t":"누구 것인지 모르는 화분의 흙이 아침마다 촉촉한 것","correct":true},{"t":"창틀이 무슨 색인지","mis":"K5-1-u3-X42"},{"t":"교실이 몇 층인지","mis":"K5-1-u3-X42"},{"t":"물병이 얼마인지","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","이야기와 관계없어요.","까닭이 적히지 않은 일이에요."],"asset":{"type":"passage","lines":["한율이네 교실 창틀 끝에는 작은 화분 하나가 있다.","누구 것인지 아무도 몰랐다. 그런데 아침마다 흙이 촉촉했다.","어느 날 일찍 학교에 온 한율이는 려원이가 물병으로 그 화분에","물을 주는 것을 보았다. 려원이는 잎에 앉은 먼지를 손끝으로","하나하나 닦아 냈다."],"title":"이야기 「창틀의 화분」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#13','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C35',2,'mc','auto','한율이에게 「화분에 꽃이 더 잘 피게 하려면 무엇을 더 해 볼 수 있을까요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X33','K5-1-u3-X36']::text[],false,'{"seq":13,"concept":"K5-1-u3-C35","difficulty":2,"kind":"mc","stem":"한율이에게 「화분에 꽃이 더 잘 피게 하려면 무엇을 더 해 볼 수 있을까요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"대안이나 정보를 찾기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X33"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X33"},{"t":"한율이를 놀리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","뜻을 묻지 않아요.","더 해 볼 방법을 구하는 질문이에요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#14','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C10',2,'mc','auto','지슬이가 인터넷에서 찾은 철새 정보를 믿을 수 있는지 확인하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X09']::text[],false,'{"seq":14,"concept":"K5-1-u3-C10","difficulty":2,"kind":"mc","stem":"지슬이가 인터넷에서 찾은 철새 정보를 믿을 수 있는지 확인하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 내용을 다른 곳에서도 찾아 견주어 본다","correct":true},{"t":"처음 찾은 글을 그대로 쓴다","mis":"K5-1-u3-X09"},{"t":"글쓴이가 자신 있게 썼으면 믿는다","mis":"K5-1-u3-X09"},{"t":"사진이 많은 글을 고른다","mis":"K5-1-u3-X09"}],"explanation":["한 곳만 보면 틀릴 수 있어요.","자신 있는 말투와 사실은 달라요.","여러 곳에서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#15','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C14',2,'mc','auto','지슬이의 발표 내용 ①을 더 잘 전하려면 어떻게 하면 좋을까요?',ARRAY['K5-1-u3-X12','K5-1-u3-X16','K5-1-u3-X13']::text[],false,'{"seq":15,"concept":"K5-1-u3-C14","difficulty":2,"kind":"mc","stem":"지슬이의 발표 내용 ①을 더 잘 전하려면 어떻게 하면 좋을까요?","options":[{"t":"글로 설명하면서 저수지 사진을 함께 보여 준다","correct":true},{"t":"글은 빼고 그래프만 보여 준다","mis":"K5-1-u3-X12"},{"t":"관계없는 빵집 사진을 넣는다","mis":"K5-1-u3-X16"},{"t":"정해진 유형이 글이니 다른 것은 쓰지 않는다","mis":"K5-1-u3-X13"}],"explanation":["그래프는 수치에 알맞아요.","주제와 관계없어요.","한 내용에 여러 유형을 함께 쓸 수 있어요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#16','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C55',2,'mc','auto','「살색」을 「살구색」으로 고쳐 쓰는 까닭은 무엇인가요?',ARRAY['K5-1-u3-X51','K5-1-u3-X53']::text[],false,'{"seq":16,"concept":"K5-1-u3-C55","difficulty":2,"kind":"mc","stem":"「살색」을 「살구색」으로 고쳐 쓰는 까닭은 무엇인가요?","options":[{"t":"사람마다 피부색이 다른데 한 가지 색만 「살」의 색이라고 하면 누군가를 빠뜨리기 때문이다","correct":true},{"t":"「살구색」이 글자 수가 더 많기 때문이다","mis":"K5-1-u3-X51"},{"t":"「살색」은 맞춤법이 틀린 말이기 때문이다","mis":"K5-1-u3-X53"},{"t":"어른들이 쓰지 말라고 했기 때문이다","mis":"K5-1-u3-X53"}],"explanation":["글자 수와는 관계없어요.","맞춤법의 문제가 아니에요.","빠뜨리는 사람이 없게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#17','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C52',3,'ox','auto','발표를 잘 준비한 사람은 질문을 받을 준비도 함께 해요.',ARRAY['K5-1-u3-X50']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"ox","stem":"발표를 잘 준비한 사람은 질문을 받을 준비도 함께 해요.","answer":"O","reason_options":[{"t":"발표와 질문은 한 짝이라 예상 질문과 답을 미리 만들면 발표 내용의 빈 곳도 채울 수 있기 때문에","correct":true},{"t":"좋은 발표에는 질문이 나오지 않기 때문에","mis":"K5-1-u3-X50"}],"mis":"K5-1-u3-X50","explanation":["예상 질문을 준비해요.","질문이 오갈 때 발표가 완성돼요.","두 공부는 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#18','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C22',3,'mc','auto','지슬이가 주제를 좁혀 간 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X21']::text[],false,'{"seq":18,"concept":"K5-1-u3-C22","difficulty":3,"kind":"mc","stem":"지슬이가 주제를 좁혀 간 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"동물 → 새 → 우리 마을에 오는 철새 → 우리 마을 철새 쉼터","correct":true},{"t":"우리 마을 철새 쉼터 → 동물 → 새 → 우리 마을에 오는 철새","mis":"K5-1-u3-X21"},{"t":"새 → 동물 → 우리 마을 철새 쉼터 → 우리 마을에 오는 철새","mis":"K5-1-u3-X21"},{"t":"동물 → 우리 마을 철새 쉼터","mis":"K5-1-u3-X21"}],"explanation":["맨 끝이 맨 앞에 왔어요.","넓혀 갔다가 좁혔어요.","넓은 것에서 차례로 좁혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#19','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C46',3,'mc','auto','「창틀의 화분」을 나와 관련지어 말한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X44']::text[],false,'{"seq":19,"concept":"K5-1-u3-C46","difficulty":3,"kind":"mc","stem":"「창틀의 화분」을 나와 관련지어 말한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이사 간 친구와 한 약속을 지키려고 나도 혼자 무언가를 한 적이 있어. 려원이 마음을 알 것 같아.」","correct":true},{"t":"「화분 이야기는 나와 관계없어.」","mis":"K5-1-u3-X44"},{"t":"「나는 식물을 안 키워서 할 말이 없어.」","mis":"K5-1-u3-X44"},{"t":"「꽃은 노란색이 예뻐.」","mis":"K5-1-u3-X44"}],"explanation":["나와 이어 보지 않았어요.","경험이 달라도 마음은 이어 볼 수 있어요.","내 경험을 인물의 마음과 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#20','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C29',3,'mc','auto','지슬이가 발표를 마치고 점검한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X28','K5-1-u3-X25','K5-1-u3-X18']::text[],false,'{"seq":20,"concept":"K5-1-u3-C29","difficulty":3,"kind":"mc","stem":"지슬이가 발표를 마치고 점검한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「새 떼 영상은 효과적이었지만, 새의 수가 줄어든 까닭을 묻는 질문에는 성의 있게 답하지 못해서 아쉬웠다.」","correct":true},{"t":"「발표가 끝났으니 돌아볼 것이 없다.」","mis":"K5-1-u3-X28"},{"t":"「화면 장수가 많아서 잘한 발표였다.」","mis":"K5-1-u3-X25"},{"t":"「글씨 색이 예뻐서 만족한다.」","mis":"K5-1-u3-X18"}],"explanation":["점검까지가 발표예요.","장수가 기준이 아니에요.","좋았던 점과 아쉬운 점을 함께 짚었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#21','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C39',3,'mc','auto','질문하기 전에 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K5-1-u3-X37','K5-1-u3-X35','K5-1-u3-X29']::text[],false,'{"seq":21,"concept":"K5-1-u3-C39","difficulty":3,"kind":"mc","stem":"질문하기 전에 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"내가 무엇을 알고 싶은지","correct":true},{"t":"질문의 갈래 이름이 무엇인지","mis":"K5-1-u3-X37"},{"t":"질문이 얼마나 긴지","mis":"K5-1-u3-X35"},{"t":"다른 친구가 무엇을 물었는지","mis":"K5-1-u3-X29"}],"explanation":["갈래 이름보다 알고 싶은 것이 먼저예요.","길이는 기준이 아니에요.","알고 싶은 것에 맞게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#22','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C11',3,'mc','auto','지슬이가 새 떼 영상을 발표에 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-1-u3-X10','K5-1-u3-X25','K5-1-u3-X19']::text[],false,'{"seq":22,"concept":"K5-1-u3-C11","difficulty":3,"kind":"mc","stem":"지슬이가 새 떼 영상을 발표에 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"날아오르는 장면만 짧게 골라 보여 준다","correct":true},{"t":"처음부터 끝까지 모두 튼다","mis":"K5-1-u3-X10"},{"t":"영상 내내 지슬이는 아무 말도 하지 않는다","mis":"K5-1-u3-X25"},{"t":"영상의 출처는 적지 않는다","mis":"K5-1-u3-X19"}],"explanation":["필요한 부분만 골라요.","설명은 발표자가 해요.","꼭 필요한 부분만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#23','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C25',4,'essay','teacher','지슬이의 첫 발표 화면을 어떻게 고치면 좋을지 세 가지 쓰고, 그렇게 고치면 듣는 사람에게 무엇이 좋은지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C25","difficulty":4,"kind":"essay","stem":"지슬이의 첫 발표 화면을 어떻게 고치면 좋을지 세 가지 쓰고, 그렇게 고치면 듣는 사람에게 무엇이 좋은지 쓰세요.","answer_guide":{"answer":"예: 화면마다 철새 이름 · 저수지 지도 · 먹이 주는 날 가운데 한 가지만 담는다. 긴 설명 글은 요약해서 큰 글씨로 쓴다. 큰고니 사진 아래에 가져온 곳을 적는다. 그러면 듣는 사람이 화면을 한눈에 알아보고 지슬이의 말에 집중할 수 있으며 자료도 믿고 볼 수 있다.","scoring_points":["고칠 점을 세 가지 썼는가","고치는 방법이 자료 만들 때 지킬 것과 맞는가","듣는 사람에게 좋은 점을 썼는가"]},"explanation":["내용의 양을 봐요.","글씨와 글의 양을 봐요.","출처를 봐요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#24','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C38',4,'essay','teacher','율비네 학급 회의에서 하설이의 제안에 대해 내용과 이어지고 예의 있는 질문을 두 개 만들고, 그 질문이 왜 좋은지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C38","difficulty":4,"kind":"essay","stem":"율비네 학급 회의에서 하설이의 제안에 대해 내용과 이어지고 예의 있는 질문을 두 개 만들고, 그 질문이 왜 좋은지 쓰세요.","answer_guide":{"answer":"예: 「정리 당번은 일주일에 한 번 몇 명이 하나요?」 · 「만약 당번이 정리한 뒤에도 책이 흐트러지면 어떻게 하나요?」 두 질문 모두 하설이의 제안과 이어지고, 상대를 깎아내리지 않으며 무엇이 궁금한지 분명하다.","scoring_points":["하설이의 제안과 이어지는 질문을 두 개 썼는가","예의 있게 물었는가","좋은 까닭을 썼는가"]},"explanation":["하설이는 무엇을 제안했나요?","깎아내리는 말은 빼요.","분명하게 물어요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_b#25','kor',5,1,'u3','','g5_1_kor_u3_review_b','unit_review','K5-1-u3-C13',4,'essay','teacher','「자료 유형은 발표 내용이 무엇을 보여 주려는지에 따라 고른다」와 「유형에 정답이 하나로 정해진 것은 아니다」를 함께 생각하여, 자료 유형을 고르는 방법을 예와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C13","difficulty":4,"kind":"essay","stem":"「자료 유형은 발표 내용이 무엇을 보여 주려는지에 따라 고른다」와 「유형에 정답이 하나로 정해진 것은 아니다」를 함께 생각하여, 자료 유형을 고르는 방법을 예와 함께 쓰세요.","answer_guide":{"answer":"예: 먼저 발표 내용이 설명인지, 변화 과정인지, 생김새인지, 수치인지 따져 그 내용을 가장 잘 살려 주는 유형을 고른다. 새 떼가 날아오르는 모습은 영상이 가장 잘 보여 준다. 그러나 영상을 구하기 어렵다면 날아오르기 전과 뒤의 사진 두 장을 나란히 두어도 된다. 중요한 것은 유형의 이름이 아니라 자료가 내용을 잘 전하는가이다.","scoring_points":["보여 주려는 것을 기준으로 고른다고 썼는가","다른 유형으로도 전할 수 있다고 썼는가","예를 들었는가"]},"explanation":["기준을 먼저 써요.","정답이 하나뿐일까요?","예를 들어 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#1','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C54',1,'match','auto','낱말과 그 뜻을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K5-1-u3-C54","difficulty":1,"kind":"match","stem":"낱말과 그 뜻을 이으세요.","pairs":[{"l":"애완","r":"귀여워하거나 즐김"},{"l":"반려","r":"짝이 되는 동무"},{"l":"협력","r":"힘을 합하여 서로 도움"}],"mis":"K5-1-u3-X52","explanation":["즐기는 대상으로 봐요.","함께 지내는 동무로 봐요.","함께함을 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#2','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C53',1,'ox','auto','비슷한 뜻의 낱말이라도 담고 있는 태도가 달라요.',ARRAY['K5-1-u3-X51']::text[],false,'{"seq":2,"concept":"K5-1-u3-C53","difficulty":1,"kind":"ox","stem":"비슷한 뜻의 낱말이라도 담고 있는 태도가 달라요.","answer":"O","reason_options":[{"t":"「애완」과 「반려」처럼 같은 대상을 즐기는 것으로 보는지 동무로 보는지가 다르기 때문에","correct":true},{"t":"뜻이 비슷하면 어느 낱말을 써도 똑같기 때문에","mis":"K5-1-u3-X51"}],"mis":"K5-1-u3-X51","explanation":["낱말마다 태도가 담겨요.","대상을 보는 눈이 달라요.","그래서 낱말을 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#3','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C13',1,'mc','auto','지슬이의 발표 내용 ④를 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X12']::text[],false,'{"seq":3,"concept":"K5-1-u3-C13","difficulty":1,"kind":"mc","stem":"지슬이의 발표 내용 ④를 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"그림이나 사진","correct":true},{"t":"표나 그래프","mis":"K5-1-u3-X12"},{"t":"영상","mis":"K5-1-u3-X12"},{"t":"글","mis":"K5-1-u3-X12"}],"explanation":["수치가 아니에요.","움직임보다 생김새를 보여 줘야 해요.","생김새의 특징은 사진이 잘 보여 줘요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#4','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C35',1,'mc','auto','려원이에게 「방학 동안에는 화분에 물을 어떻게 주나요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X33','K5-1-u3-X36']::text[],false,'{"seq":4,"concept":"K5-1-u3-C35","difficulty":1,"kind":"mc","stem":"려원이에게 「방학 동안에는 화분에 물을 어떻게 주나요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"대안이나 정보를 찾기 위해서","correct":true},{"t":"의도를 파악하기 위해서","mis":"K5-1-u3-X33"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X33"},{"t":"려원이를 놀리기 위해서","mis":"K5-1-u3-X36"}],"explanation":["까닭을 묻지 않아요.","말의 뜻을 묻지 않아요.","그럴 때의 방법을 구하는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#5','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C8',1,'mc','auto','「우리 지역 여름 축제」 발표 내용 ①을 가장 잘 살려 주는 자료 유형은 어느 것인가요?',ARRAY['K5-1-u3-X07']::text[],false,'{"seq":5,"concept":"K5-1-u3-C8","difficulty":1,"kind":"mc","stem":"「우리 지역 여름 축제」 발표 내용 ①을 가장 잘 살려 주는 자료 유형은 어느 것인가요?","options":[{"t":"글","correct":true},{"t":"영상","mis":"K5-1-u3-X07"},{"t":"표나 그래프","mis":"K5-1-u3-X07"},{"t":"그림이나 사진","mis":"K5-1-u3-X07"}],"explanation":["움직임이 아니에요.","수치의 변화가 아니에요.","뜻과 시작은 자세한 설명이 필요해요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#6','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C15',1,'mc','auto','지슬이가 발표 내용 ①에 쓸 단락은 어느 것인가요?',ARRAY['K5-1-u3-X14']::text[],false,'{"seq":6,"concept":"K5-1-u3-C15","difficulty":1,"kind":"mc","stem":"지슬이가 발표 내용 ①에 쓸 단락은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"K5-1-u3-X14"},{"t":"㉰","mis":"K5-1-u3-X14"},{"t":"㉱","mis":"K5-1-u3-X14"}],"explanation":["생김새예요.","마을 사람들이 하는 일이에요.","철새의 뜻과 저수지가 쉼터인 까닭이 담겼어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#7','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C41',1,'mc','auto','「담 너머」에서 고양이가 담 너머로 가 보게 된 일은 어느 것인가요?',ARRAY['K5-1-u3-X39']::text[],false,'{"seq":7,"concept":"K5-1-u3-C41","difficulty":1,"kind":"mc","stem":"「담 너머」에서 고양이가 담 너머로 가 보게 된 일은 어느 것인가요?","options":[{"t":"나비가 「내 등에 올라타 봐.」라고 말했다","correct":true},{"t":"늙은 개가 위험하다고 했다","mis":"K5-1-u3-X39"},{"t":"두더지가 아무것도 없다고 했다","mis":"K5-1-u3-X39"},{"t":"참새가 관심 없다고 했다","mis":"K5-1-u3-X39"}],"explanation":["이웃들의 대답이에요.","이웃들의 대답이에요.","나비의 말이 고양이를 담 너머로 이끌었어요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#8','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C27',1,'mc','auto','지슬이의 끝맺는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X26','K5-1-u3-X49']::text[],false,'{"seq":8,"concept":"K5-1-u3-C27","difficulty":1,"kind":"mc","stem":"지슬이의 끝맺는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「이상으로 우리 마을 철새 쉼터에 대한 발표를 마치겠습니다. 궁금한 점이 있으면 질문해 주세요.」","correct":true},{"t":"「여기까지예요.」","mis":"K5-1-u3-X26"},{"t":"「다음에 또 할게요. 질문은 안 받아요.」","mis":"K5-1-u3-X49"},{"t":"「철새는 계절에 따라 사는 곳을 옮기는 새입니다.」","mis":"K5-1-u3-X26"}],"explanation":["마무리가 흐려요.","질문을 막았어요.","마무리와 질문 안내가 담겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#9','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C18',2,'error','auto','㉰를 쉬운 말로 바꾼 것이에요. 뜻이 달라져 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u3-X17']::text[],false,'{"seq":9,"concept":"K5-1-u3-C18","difficulty":2,"kind":"error","stem":"㉰를 쉬운 말로 바꾼 것이에요. 뜻이 달라져 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「해마다 찾아오는 새가 모두 사라졌다.」","correct":true,"mis_target":"K5-1-u3-X17"},{"t":"「해마다 찾아오는 새의 수가 줄어들고 있다.」","mis":"K5-1-u3-X17"},{"t":"「해마다 찾아오는 새가 점점 적어지고 있다.」","mis":"K5-1-u3-X17"}],"explanation":["뜻이 그대로예요.","뜻이 그대로예요.","줄어드는 것과 사라지는 것은 달라요."],"asset":{"type":"passage","lines":["㉮ 철새가 도래하는 때는 늦가을이다.","㉯ 큰고니는 이 저수지에서 월동한다.","㉰ 해마다 찾아오는 새의 개체 수가 감소하고 있다."],"title":"지슬이의 발표 원고 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#10','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C20',2,'mc','auto','지슬이가 인터넷에서 가져온 큰고니 사진에 해야 할 일은 어느 것인가요?',ARRAY['K5-1-u3-X19','K5-1-u3-X24']::text[],false,'{"seq":10,"concept":"K5-1-u3-C20","difficulty":2,"kind":"mc","stem":"지슬이가 인터넷에서 가져온 큰고니 사진에 해야 할 일은 어느 것인가요?","options":[{"t":"사진 아래쪽에 어디에서 가져왔는지 적는다","correct":true},{"t":"내가 찍은 사진이라고 말한다","mis":"K5-1-u3-X19"},{"t":"사진을 더 크게 늘려 화면을 채운다","mis":"K5-1-u3-X24"},{"t":"출처는 지슬이만 알면 되니 그대로 둔다","mis":"K5-1-u3-X19"}],"explanation":["남의 사진이에요.","크기보다 출처가 먼저예요.","이름표를 달아요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#11','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C36',2,'mc','auto','려원이의 제안에 「만약」을 넣어 다른 경우를 짚어 본 질문은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":11,"concept":"K5-1-u3-C36","difficulty":2,"kind":"mc","stem":"려원이의 제안에 「만약」을 넣어 다른 경우를 짚어 본 질문은 어느 것인가요?","options":[{"t":"「만약 모둠이 맡은 화분이 시들면 어떻게 하나요?」","correct":true},{"t":"「려원이는 언제 화분을 보았나요?」","mis":"K5-1-u3-X34"},{"t":"「화분은 누가 사 왔나요?」","mis":"K5-1-u3-X34"},{"t":"「화분은 어디에 있나요?」","mis":"K5-1-u3-X34"}],"explanation":["때를 묻는 질문이에요.","사람을 묻는 질문이에요.","「만약」으로 다른 경우를 짚었어요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#12','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C41',2,'mc','auto','려원이가 화분을 돌본 까닭을 짐작할 수 있는 말은 어느 것인가요?',ARRAY['K5-1-u3-X39']::text[],false,'{"seq":12,"concept":"K5-1-u3-C41","difficulty":2,"kind":"mc","stem":"려원이가 화분을 돌본 까닭을 짐작할 수 있는 말은 어느 것인가요?","options":[{"t":"「꽃이 피면 사진 찍어 보내 준다고 했어.」","correct":true},{"t":"「봄 방학을 앞둔 날」","mis":"K5-1-u3-X39"},{"t":"「화분에는 아직 꽃봉오리 하나 없었다.」","mis":"K5-1-u3-X39"},{"t":"「한 달쯤 지나」","mis":"K5-1-u3-X39"}],"explanation":["때를 알려 주는 말이에요.","화분의 모습이에요.","전학 간 친구와의 약속이 드러나요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#13','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C33',2,'mc','auto','한율이에게 「「둘이 주면 더 빨리 필까 해서」라는 말에는 어떤 마음이 담겨 있었나요?」라고 묻는 질문의 목적은 무엇인가요?',ARRAY['K5-1-u3-X31','K5-1-u3-X36']::text[],false,'{"seq":13,"concept":"K5-1-u3-C33","difficulty":2,"kind":"mc","stem":"한율이에게 「「둘이 주면 더 빨리 필까 해서」라는 말에는 어떤 마음이 담겨 있었나요?」라고 묻는 질문의 목적은 무엇인가요?","options":[{"t":"의도를 파악하기 위해서","correct":true},{"t":"대안이나 정보를 찾기 위해서","mis":"K5-1-u3-X31"},{"t":"명료하게 이해하기 위해서","mis":"K5-1-u3-X31"},{"t":"회의를 이어 가기 위해서","mis":"K5-1-u3-X36"}],"explanation":["방법을 구하지 않아요.","낱말 뜻을 묻지 않아요.","왜 그렇게 말했는지 마음을 묻고 있어요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#14','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C20',2,'ox','auto','공공 기관 누리집처럼 믿을 수 있는 곳의 자료는 출처를 적지 않아도 돼요.',ARRAY['K5-1-u3-X19']::text[],false,'{"seq":14,"concept":"K5-1-u3-C20","difficulty":2,"kind":"ox","stem":"공공 기관 누리집처럼 믿을 수 있는 곳의 자료는 출처를 적지 않아도 돼요.","answer":"X","reason_options":[{"t":"믿을 수 있는 곳의 자료라도 남이 만든 것이므로 어디에서 가져왔는지 밝혀야 하기 때문에","correct":true},{"t":"믿을 수 있는 곳의 자료는 누구나 아는 것이기 때문에","mis":"K5-1-u3-X19"}],"mis":"K5-1-u3-X19","explanation":["어디에서 왔는지 밝혀요.","예의이고 믿음의 근거예요.","출처는 늘 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#15','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C9',2,'mc','auto','「해마다 쉼터를 찾아온 새의 수가 줄었다」를 글로만 전하면 생기는 어려움은 무엇인가요?',ARRAY['K5-1-u3-X08','K5-1-u3-X07']::text[],false,'{"seq":15,"concept":"K5-1-u3-C9","difficulty":2,"kind":"mc","stem":"「해마다 쉼터를 찾아온 새의 수가 줄었다」를 글로만 전하면 생기는 어려움은 무엇인가요?","options":[{"t":"얼마나 줄었는지 듣는 사람이 가늠하기 어렵다","correct":true},{"t":"아무 어려움도 없다","mis":"K5-1-u3-X08"},{"t":"새의 생김새를 알 수 없다","mis":"K5-1-u3-X07"},{"t":"새가 날아오르는 모습이 보이지 않는다","mis":"K5-1-u3-X07"}],"explanation":["수치의 크기는 글로 가늠하기 어려워요.","생김새와는 다른 문제예요.","그래프라면 한눈에 보여요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#16','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C43',2,'mc','auto','「담 너머」의 고양이에게 물을 질문 가운데 의도를 파악하려는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X41','K5-1-u3-X42']::text[],false,'{"seq":16,"concept":"K5-1-u3-C43","difficulty":2,"kind":"mc","stem":"「담 너머」의 고양이에게 물을 질문 가운데 의도를 파악하려는 질문은 어느 것인가요?","options":[{"t":"「이웃들 말과 달리 담을 넘기로 한 까닭은 무엇인가요?」","correct":true},{"t":"「담 너머 들판의 빛깔은 몇 가지였나요?」","mis":"K5-1-u3-X41"},{"t":"「나비는 어디에 살아요?」","mis":"K5-1-u3-X42"},{"t":"「담의 높이는 얼마나 되나요?」","mis":"K5-1-u3-X42"}],"explanation":["사실을 묻는 질문이에요.","글과 관계없어요.","왜 그렇게 했는지 묻고 있어요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#17','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C52',3,'error','auto','이 단원에서 배운 것을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X50','K5-1-u3-X12','K5-1-u3-X37']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"error","stem":"이 단원에서 배운 것을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「자료를 잘 고르면 질문은 받을 필요가 없어.」","correct":true,"mis_target":"K5-1-u3-X50"},{"t":"「자료는 내용과 상황에 맞게 골라야 해.」","mis":"K5-1-u3-X12"},{"t":"「질문은 목적을 생각해 분명하게 해야 해.」","mis":"K5-1-u3-X37"}],"explanation":["맞는 말이에요.","맞는 말이에요.","발표와 질문은 한 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#18','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C24',3,'mc','auto','지슬이가 친구들에게 쉼터 둘레의 갈대를 직접 만져 보게 하려면 어떤 매체가 알맞을까요?',ARRAY['K5-1-u3-X23']::text[],false,'{"seq":18,"concept":"K5-1-u3-C24","difficulty":3,"kind":"mc","stem":"지슬이가 친구들에게 쉼터 둘레의 갈대를 직접 만져 보게 하려면 어떤 매체가 알맞을까요?","options":[{"t":"직접 가져온 실물","correct":true},{"t":"화면에 띄운 영상","mis":"K5-1-u3-X23"},{"t":"화면에 띄운 그래프","mis":"K5-1-u3-X23"},{"t":"몸짓과 말","mis":"K5-1-u3-X23"}],"explanation":["만져 볼 수 없어요.","수치를 보여 주는 매체예요.","만져 보려면 실물이에요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#19','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C40',3,'mc','auto','「창틀의 화분」에서 읽는 사람이 려원이에게 묻고 싶어지는 까닭은 무엇인가요?',ARRAY['K5-1-u3-X38']::text[],false,'{"seq":19,"concept":"K5-1-u3-C40","difficulty":3,"kind":"mc","stem":"「창틀의 화분」에서 읽는 사람이 려원이에게 묻고 싶어지는 까닭은 무엇인가요?","options":[{"t":"려원이가 화분을 돌보는 까닭을 처음에는 말하지 않았기 때문이다","correct":true},{"t":"화분이 작기 때문이다","mis":"K5-1-u3-X38"},{"t":"이야기가 교실에서 일어나기 때문이다","mis":"K5-1-u3-X38"},{"t":"한율이가 일찍 왔기 때문이다","mis":"K5-1-u3-X38"}],"explanation":["크기 때문이 아니에요.","장소 때문이 아니에요.","까닭이 적히지 않은 행동이 질문을 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#20','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C28',3,'mc','auto','예상 질문을 미리 만들어 본 지슬이에게 생길 좋은 점은 무엇인가요?',ARRAY['K5-1-u3-X49','K5-1-u3-X27','K5-1-u3-X01']::text[],false,'{"seq":20,"concept":"K5-1-u3-C28","difficulty":3,"kind":"mc","stem":"예상 질문을 미리 만들어 본 지슬이에게 생길 좋은 점은 무엇인가요?","options":[{"t":"「새의 수가 왜 줄었을까?」처럼 발표에서 빠진 곳을 먼저 찾아 채울 수 있다","correct":true},{"t":"친구들이 질문을 하지 못하게 된다","mis":"K5-1-u3-X49"},{"t":"발표 시간이 줄어든다","mis":"K5-1-u3-X27"},{"t":"자료를 만들지 않아도 된다","mis":"K5-1-u3-X01"}],"explanation":["질문은 여전히 받아요.","시간과는 관계없어요.","빈 곳이 먼저 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#21','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C36',3,'mc','auto','지슬이에게 「먹이로 볍씨를 뿌리는 까닭」을 물으려 할 때 질문을 여는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":21,"concept":"K5-1-u3-C36","difficulty":3,"kind":"mc","stem":"지슬이에게 「먹이로 볍씨를 뿌리는 까닭」을 물으려 할 때 질문을 여는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"왜","correct":true},{"t":"만약","mis":"K5-1-u3-X34"},{"t":"언제","mis":"K5-1-u3-X34"},{"t":"누가","mis":"K5-1-u3-X34"}],"explanation":["다른 경우를 짚을 때 써요.","때를 물을 때 써요.","까닭은 「왜」로 물어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#22','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C12',3,'mc','auto','지슬이의 글 자료 ㉮~㉱를 선별한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X11','K5-1-u3-X16','K5-1-u3-X14']::text[],false,'{"seq":22,"concept":"K5-1-u3-C12","difficulty":3,"kind":"mc","stem":"지슬이의 글 자료 ㉮~㉱를 선별한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"㉮ · ㉯ · ㉰를 발표 내용에 맞게 요약해 쓰고 ㉱는 뺀다","correct":true},{"t":"㉮~㉱를 모두 그대로 쓴다","mis":"K5-1-u3-X11"},{"t":"빵집 이야기가 재미있으니 ㉱를 가장 크게 쓴다","mis":"K5-1-u3-X16"},{"t":"㉯만 쓰고 나머지는 모두 뺀다","mis":"K5-1-u3-X14"}],"explanation":["다 쓰면 선별이 아니에요.","주제와 관계없어요.","필요한 것은 남기고 관계없는 것은 덜어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#23','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C27',4,'essay','teacher','지슬이의 시작하는 말 「가」를 알맞게 고쳐 쓰고, 시작하는 말에 꼭 담아야 할 것이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C27","difficulty":4,"kind":"essay","stem":"지슬이의 시작하는 말 「가」를 알맞게 고쳐 쓰고, 시작하는 말에 꼭 담아야 할 것이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 「안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울마다 저수지를 찾아오는 새들이 어디에서 왜 오는지 궁금해 조사해 보았습니다.」 시작하는 말에는 무엇을 발표하는지와 왜 발표하는지를 담아야 한다.","scoring_points":["인사와 주제를 담아 고쳤는가","발표하는 까닭을 담았는가","시작하는 말에 담을 것을 썼는가"]},"explanation":["핑계는 빼요.","무엇을 발표하나요?","왜 발표하나요?"],"asset":{"type":"speech","turns":[{"who":"가","text":"음…… 준비를 많이 못 했는데 그냥 해 보겠습니다."},{"who":"나","text":"철새는 계절에 따라 사는 곳을 옮기는 새로, 마을 저수지는 물이 얕아……."},{"who":"다","text":"안녕하세요. 저는 우리 마을 철새 쉼터에 대해 발표할 지슬입니다. 겨울 방학에 저수지에서 새 떼를 본 뒤로 궁금해져 조사해 보았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#24','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C45',4,'essay','teacher','려원이가 되어 「한율이가 물병을 들고 왔을 때 왜 아무 말 없이 웃었나요?」라는 질문에 답하고, 이야기 속 어떤 말과 행동을 근거로 했는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C45","difficulty":4,"kind":"essay","stem":"려원이가 되어 「한율이가 물병을 들고 왔을 때 왜 아무 말 없이 웃었나요?」라는 질문에 답하고, 이야기 속 어떤 말과 행동을 근거로 했는지 쓰세요.","answer_guide":{"answer":"예: 답 — 「혼자 지키던 약속을 한율이가 알아주고 함께해 주니 고마워서 말보다 웃음이 먼저 나왔어.」 근거 — 려원이가 약속을 말한 바로 다음 날 한율이가 물병을 들고 와 「둘이 주면 더 빨리 필까 해서.」라고 말했고, 려원이가 사진을 두 장 찍었다.","scoring_points":["인물이 되어 답했는가","이야기 속 말과 행동을 근거로 들었는가","근거와 답이 이어지는가"]},"explanation":["려원이의 처지에서 답해요.","약속과 한율이의 행동을 봐요.","근거를 밝혀요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_c#25','kor',5,1,'u3','','g5_1_kor_u3_review_c','unit_review','K5-1-u3-C26',4,'essay','teacher','「자료는 많을수록 좋은 발표가 된다」는 친구의 생각에 대해 자기 생각을 쓰고, 발표의 주인공이 누구인지 밝혀 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C26","difficulty":4,"kind":"essay","stem":"「자료는 많을수록 좋은 발표가 된다」는 친구의 생각에 대해 자기 생각을 쓰고, 발표의 주인공이 누구인지 밝혀 까닭을 쓰세요.","answer_guide":{"answer":"예: 그렇지 않다. 발표의 주인공은 발표하는 사람이고 자료는 말을 도와주는 보조이다. 자료가 너무 많으면 화면이 빽빽해지고 발표자는 화면을 읽기만 하게 된다. 자료는 말로 전하기 어려운 곳에 꼭 필요한 만큼 있을 때 힘이 된다.","scoring_points":["친구의 생각에 대한 자기 생각을 밝혔는가","발표의 주인공이 발표자라고 썼는가","자료가 많을 때의 문제를 들어 까닭을 썼는가"]},"explanation":["자료가 많으면 어떻게 되나요?","주인공은 누구인가요?","자료가 힘이 될 때를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#1','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C54',1,'blank','auto','빈칸에 알맞은 낱말을 고르세요. 「여러 모둠이 (　　)하여 좋은 결과를 만들었다.」',ARRAY['K5-1-u3-X52','K5-1-u3-X51']::text[],false,'{"seq":1,"concept":"K5-1-u3-C54","difficulty":1,"kind":"blank","stem":"빈칸에 알맞은 낱말을 고르세요. 「여러 모둠이 (　　)하여 좋은 결과를 만들었다.」","options":[{"t":"협력","correct":true},{"t":"하청","mis":"K5-1-u3-X52"},{"t":"지배","mis":"K5-1-u3-X51"},{"t":"경쟁","mis":"K5-1-u3-X51"}],"explanation":["위아래를 가르는 말이에요.","함께함과 거리가 멀어요.","힘을 합하여 돕는다는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#2','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C53',1,'mc','auto','낱말을 고를 때 함께 생각할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X51']::text[],false,'{"seq":2,"concept":"K5-1-u3-C53","difficulty":1,"kind":"mc","stem":"낱말을 고를 때 함께 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"차별이나 낮추는 뜻은 없는지, 약자를 배려했는지","correct":true},{"t":"글자 수가 짧은지","mis":"K5-1-u3-X51"},{"t":"발음하기 쉬운지","mis":"K5-1-u3-X51"},{"t":"어른들이 자주 쓰는 말인지","mis":"K5-1-u3-X51"}],"explanation":["길이가 기준은 아니에요.","발음이 기준은 아니에요.","누구를 어떻게 부르는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#3','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C8',1,'match','auto','지슬이의 발표 내용과 가장 잘 살려 주는 자료 유형을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K5-1-u3-C8","difficulty":1,"kind":"match","stem":"지슬이의 발표 내용과 가장 잘 살려 주는 자료 유형을 이으세요.","pairs":[{"l":"철새 쉼터의 뜻과 생긴 곳","r":"글"},{"l":"해마다 쉼터를 찾아온 새의 수","r":"표나 그래프"},{"l":"새 떼가 날아오르는 모습","r":"영상"},{"l":"큰고니의 생김새","r":"그림이나 사진"}],"mis":"K5-1-u3-X07","explanation":["설명은 글이에요.","수치는 표나 그래프예요.","움직임은 영상, 생김새는 사진이에요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#4','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C38',1,'mc','auto','율비네 학급 회의에서 할 만한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X36']::text[],false,'{"seq":4,"concept":"K5-1-u3-C38","difficulty":1,"kind":"mc","stem":"율비네 학급 회의에서 할 만한 질문은 어느 것인가요?","options":[{"t":"「도우미는 누가 어떻게 정하나요?」","correct":true},{"t":"「오늘 급식은 무엇인가요?」","mis":"K5-1-u3-X36"},{"t":"「그 의견은 왜 그렇게 별로인가요?」","mis":"K5-1-u3-X36"},{"t":"「하설이는 몇 번인가요?」","mis":"K5-1-u3-X36"}],"explanation":["회의 내용과 관계없어요.","깎아내리는 말이에요.","율비의 제안과 이어지는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#5','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C9',1,'mc','auto','축제에 해마다 다녀간 사람 수를 표나 그래프로 나타내는 까닭은 무엇인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X07']::text[],false,'{"seq":5,"concept":"K5-1-u3-C9","difficulty":1,"kind":"mc","stem":"축제에 해마다 다녀간 사람 수를 표나 그래프로 나타내는 까닭은 무엇인가요?","options":[{"t":"수치의 변화를 한눈에 알아볼 수 있어서","correct":true},{"t":"보기에 예뻐서","mis":"K5-1-u3-X18"},{"t":"설명을 자세히 담을 수 있어서","mis":"K5-1-u3-X07"},{"t":"움직임을 보여 줄 수 있어서","mis":"K5-1-u3-X07"}],"explanation":["예쁜 것은 기준이 아니에요.","자세한 설명은 글이에요.","여러 해의 수치가 한눈에 보여요."],"asset":{"type":"passage","lines":["① 축제의 뜻과 시작된 해","② 해마다 다녀간 사람 수","③ 축제 무대 공연 장면","④ 축제 마당의 모습"],"title":"「우리 지역 여름 축제」 발표 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#6','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C16',1,'mc','auto','㉮를 발표 내용 ①에 맞게 요약한 것은 어느 것인가요?',ARRAY['K5-1-u3-X15','K5-1-u3-X14']::text[],false,'{"seq":6,"concept":"K5-1-u3-C16","difficulty":1,"kind":"mc","stem":"㉮를 발표 내용 ①에 맞게 요약한 것은 어느 것인가요?","options":[{"t":"계절 따라 사는 곳을 옮기는 새 · 물이 얕고 잘 얼지 않는 저수지","correct":true},{"t":"㉮의 두 문장을 그대로 옮겨 적음","mis":"K5-1-u3-X15"},{"t":"큰고니는 온몸이 흼","mis":"K5-1-u3-X14"},{"t":"빵집은 주말마다 붐빔","mis":"K5-1-u3-X14"}],"explanation":["옮겨 적으면 요약이 아니에요.","㉯의 내용이에요.","필요한 것만 남겼어요."],"asset":{"type":"passage","lines":["㉮ 철새는 계절에 따라 사는 곳을 옮기는 새다. 마을 저수지는 물이","　 얕고 겨울에도 잘 얼지 않아 철새가 쉬어 가기 좋다.","㉯ 큰고니는 온몸이 희고 부리 끝이 검으며 노란 무늬가 있다.","　 청둥오리 수컷은 머리가 초록빛으로 반짝인다.","㉰ 마을 사람들은 겨울마다 볍씨를 뿌려 먹이를 나누고,","　 새가 놀라지 않게 쉼터 둘레에 갈대 울타리를 친다.","㉱ 저수지 옆길에 새로 생긴 빵집은 주말마다 손님으로 붐빈다."],"title":"지슬이가 찾은 글 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#7','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C40',1,'mc','auto','「담 너머」를 읽고 질문하고 싶어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X38']::text[],false,'{"seq":7,"concept":"K5-1-u3-C40","difficulty":1,"kind":"mc","stem":"「담 너머」를 읽고 질문하고 싶어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나비가 「담은 대부분 네가 세우게 될 거야」라고 했지만 그 까닭은 말하지 않았기 때문이다","correct":true},{"t":"고양이가 나오기 때문이다","mis":"K5-1-u3-X38"},{"t":"글이 짧기 때문이다","mis":"K5-1-u3-X38"},{"t":"들판이 넓기 때문이다","mis":"K5-1-u3-X38"}],"explanation":["인물이 나와서가 아니에요.","길이 때문이 아니에요.","까닭이 적히지 않은 말이 질문을 불러요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#8','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C21',1,'mc','auto','지슬이가 발표 화면을 고친 뒤 친구들 앞에서 발표를 마쳤어요. 이제 남은 일은 무엇인가요?',ARRAY['K5-1-u3-X20']::text[],false,'{"seq":8,"concept":"K5-1-u3-C21","difficulty":1,"kind":"mc","stem":"지슬이가 발표 화면을 고친 뒤 친구들 앞에서 발표를 마쳤어요. 이제 남은 일은 무엇인가요?","options":[{"t":"발표 과정을 점검하기","correct":true},{"t":"발표 계획 세우기","mis":"K5-1-u3-X20"},{"t":"발표 주제 정하기","mis":"K5-1-u3-X20"},{"t":"자료 다시 찾기","mis":"K5-1-u3-X20"}],"explanation":["계획은 맨 처음이에요.","주제는 맨 처음이에요.","발표 뒤에는 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#9','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C18',2,'mc','auto','어려운 말을 쉬운 말로 바꿀 때 가장 조심할 점은 무엇인가요?',ARRAY['K5-1-u3-X17','K5-1-u3-X15','K5-1-u3-X19']::text[],false,'{"seq":9,"concept":"K5-1-u3-C18","difficulty":2,"kind":"mc","stem":"어려운 말을 쉬운 말로 바꿀 때 가장 조심할 점은 무엇인가요?","options":[{"t":"뜻이 달라지지 않게 한다","correct":true},{"t":"되도록 짧은 말로만 바꾼다","mis":"K5-1-u3-X17"},{"t":"어려운 말은 모두 빼 버린다","mis":"K5-1-u3-X15"},{"t":"바꾼 말에는 출처를 적는다","mis":"K5-1-u3-X19"}],"explanation":["짧다고 뜻이 같은 것은 아니에요.","빼면 내용이 빠져요.","뜻은 그대로, 말만 쉽게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#10','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C25',2,'mc','auto','지슬이의 첫 화면을 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K5-1-u3-X24','K5-1-u3-X15','K5-1-u3-X13']::text[],false,'{"seq":10,"concept":"K5-1-u3-C25","difficulty":2,"kind":"mc","stem":"지슬이의 첫 화면을 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"화면마다 한 가지 내용만 담고 글은 요약해 크게 쓴다","correct":true},{"t":"철새 이름을 열다섯 개에서 서른 개로 늘린다","mis":"K5-1-u3-X24"},{"t":"설명 글을 세 단락에서 다섯 단락으로 늘린다","mis":"K5-1-u3-X15"},{"t":"사진을 모두 빼고 글만 남긴다","mis":"K5-1-u3-X13"}],"explanation":["더 빽빽해져요.","더 길어져요.","한 화면에 한 가지, 요약, 큰 글씨예요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#11','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C30',2,'mc','auto','율비네 회의에서 좋은 질문을 하려면 듣는 동안 무엇을 해야 하나요?',ARRAY['K5-1-u3-X29','K5-1-u3-X03']::text[],false,'{"seq":11,"concept":"K5-1-u3-C30","difficulty":2,"kind":"mc","stem":"율비네 회의에서 좋은 질문을 하려면 듣는 동안 무엇을 해야 하나요?","options":[{"t":"제안과 그 까닭을 짝지어 들으며 궁금하거나 흐릿한 곳을 짚는다","correct":true},{"t":"다른 친구와 이야기하며 기다린다","mis":"K5-1-u3-X29"},{"t":"내 의견만 생각하며 듣지 않는다","mis":"K5-1-u3-X29"},{"t":"친구가 말하는 도중에 끼어든다","mis":"K5-1-u3-X03"}],"explanation":["집중하지 않으면 질문이 안 생겨요.","들어야 궁금한 곳이 보여요.","집중해서 듣고 짚어 둬요."],"asset":{"type":"speech","turns":[{"who":"율비","text":"쉬는 시간마다 복도 걷기 도우미를 정하면 좋겠습니다. 복도에서 뛰다가 부딪혀 넘어지는 일이 잦습니다."},{"who":"하설","text":"학급 문고 정리 당번을 일주일에 한 번 두면 좋겠습니다. 책이 아무렇게나 꽂혀 있어 찾기 어렵습니다."},{"who":"려원","text":"창가 화분을 모둠마다 하나씩 맡아 기르면 좋겠습니다. 물을 주는 사람이 없어 화분이 자꾸 시듭니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#12','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C45',2,'mc','auto','려원이가 되어 「왜 사진을 두 장 찍었나요?」에 답한 것으로 이야기에 근거한 것은 어느 것인가요?',ARRAY['K5-1-u3-X43']::text[],false,'{"seq":12,"concept":"K5-1-u3-C45","difficulty":2,"kind":"mc","stem":"려원이가 되어 「왜 사진을 두 장 찍었나요?」에 답한 것으로 이야기에 근거한 것은 어느 것인가요?","options":[{"t":"「한 장은 전학 간 친구에게, 한 장은 같이 물을 준 한율이에게 주고 싶었어요.」","correct":true},{"t":"「사진기가 새것이라서요.」","mis":"K5-1-u3-X43"},{"t":"「꽃이 싫어서 두 번 확인했어요.」","mis":"K5-1-u3-X43"},{"t":"「그냥 손이 미끄러졌어요.」","mis":"K5-1-u3-X43"}],"explanation":["이야기에 근거가 없어요.","이야기와 맞지 않아요.","친구와의 약속과 한율이의 도움이 근거예요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#13','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C44',2,'mc','auto','「창틀의 화분」 안에서 생각해 볼 수 있는 질문은 어느 것인가요?',ARRAY['K5-1-u3-X42']::text[],false,'{"seq":13,"concept":"K5-1-u3-C44","difficulty":2,"kind":"mc","stem":"「창틀의 화분」 안에서 생각해 볼 수 있는 질문은 어느 것인가요?","options":[{"t":"「꽃이 핀 날 려원이는 어떤 마음이었을까요?」","correct":true},{"t":"「화분 값은 얼마인가요?」","mis":"K5-1-u3-X42"},{"t":"「한율이네 학교 이름은 무엇인가요?」","mis":"K5-1-u3-X42"},{"t":"「물병은 몇 개인가요?」","mis":"K5-1-u3-X42"}],"explanation":["이야기와 관계없어요.","이야기와 관계없어요.","이야기 속 말과 행동으로 생각해 볼 수 있어요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#14','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C49',2,'mc','auto','「마을 어르신들이 기억하는 철새 쉼터의 옛 모습」을 알아보는 알맞은 방법은 어느 것인가요?',ARRAY['K5-1-u3-X47']::text[],false,'{"seq":14,"concept":"K5-1-u3-C49","difficulty":2,"kind":"mc","stem":"「마을 어르신들이 기억하는 철새 쉼터의 옛 모습」을 알아보는 알맞은 방법은 어느 것인가요?","options":[{"t":"어르신들을 찾아가 면담한다","correct":true},{"t":"공공 기관 누리집의 통계만 본다","mis":"K5-1-u3-X47"},{"t":"저수지를 오늘 관찰한다","mis":"K5-1-u3-X47"},{"t":"철새 도감을 찾아본다","mis":"K5-1-u3-X47"}],"explanation":["기억은 통계에 없어요.","옛 모습은 오늘 관찰로 알 수 없어요.","기억은 직접 여쭈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#15','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C11',2,'mc','auto','지슬이가 새의 수 그래프를 찾았을 때 먼저 확인할 것은 어느 것인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X11','K5-1-u3-X24']::text[],false,'{"seq":15,"concept":"K5-1-u3-C11","difficulty":2,"kind":"mc","stem":"지슬이가 새의 수 그래프를 찾았을 때 먼저 확인할 것은 어느 것인가요?","options":[{"t":"눈금의 간격이 고른지, 수치가 과장되지 않았는지","correct":true},{"t":"그래프 색이 예쁜지","mis":"K5-1-u3-X18"},{"t":"막대가 되도록 많은지","mis":"K5-1-u3-X11"},{"t":"그래프가 화면을 가득 채우는지","mis":"K5-1-u3-X24"}],"explanation":["색은 기준이 아니에요.","많다고 좋은 것이 아니에요.","따져 보고 써요."],"asset":{"type":"passage","lines":["발표 주제 — 우리 마을 철새 쉼터","① 철새 쉼터의 뜻과 생긴 곳","② 해마다 쉼터를 찾아온 새의 수","③ 새 떼가 한꺼번에 날아오르는 모습","④ 큰고니의 생김새"],"title":"지슬이의 발표 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#16','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C45',2,'mc','auto','나비가 되어 「왜 고양이를 도와주었나요?」에 답한 것으로 글에 근거한 것은 어느 것인가요?',ARRAY['K5-1-u3-X43']::text[],false,'{"seq":16,"concept":"K5-1-u3-C45","difficulty":2,"kind":"mc","stem":"나비가 되어 「왜 고양이를 도와주었나요?」에 답한 것으로 글에 근거한 것은 어느 것인가요?","options":[{"t":"「궁금해하며 보는 눈이 있어서 담 너머를 보여 주고 싶었어.」","correct":true},{"t":"「배가 고파서 고양이에게 먹이를 얻으려고.」","mis":"K5-1-u3-X43"},{"t":"「심심해서 아무나 태웠어.」","mis":"K5-1-u3-X43"},{"t":"「고양이가 무서워서.」","mis":"K5-1-u3-X43"}],"explanation":["글에 근거가 없어요.","글과 맞지 않아요.","「너는 궁금해하며 봤으니까」가 근거예요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#17','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C52',3,'mc','auto','지슬이의 발표를 들은 친구가 「큰고니 사진은 어디에서 찾았나요?」라고 물었어요. 이 장면에서 알 수 있는 것은 무엇인가요?',ARRAY['K5-1-u3-X49','K5-1-u3-X29']::text[],false,'{"seq":17,"concept":"K5-1-u3-C52","difficulty":3,"kind":"mc","stem":"지슬이의 발표를 들은 친구가 「큰고니 사진은 어디에서 찾았나요?」라고 물었어요. 이 장면에서 알 수 있는 것은 무엇인가요?","options":[{"t":"발표자가 활용한 자료가 듣는 사람의 질문으로 이어졌다","correct":true},{"t":"발표가 실패했다","mis":"K5-1-u3-X49"},{"t":"듣는 사람이 발표를 듣지 않았다","mis":"K5-1-u3-X29"},{"t":"자료에 대한 질문은 하면 안 된다","mis":"K5-1-u3-X49"}],"explanation":["질문은 실패가 아니에요.","들었기 때문에 물었어요.","자료에 대해서도 물을 수 있어요."],"asset":{"type":"passage","lines":["한 화면에 철새 이름 열다섯 개, 저수지 지도, 먹이 주는 날짜표,","긴 설명 글 세 단락이 작은 글씨로 가득 담겨 있다.","인터넷에서 가져온 큰고니 사진 아래에는 아무 표시가 없다."],"title":"지슬이의 첫 발표 화면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#18','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C6',3,'mc','auto','지슬이의 발표를 들을 사람이 마을 어르신들이라면 준비에서 무엇을 더 생각해야 할까요?',ARRAY['K5-1-u3-X05','K5-1-u3-X17','K5-1-u3-X24']::text[],false,'{"seq":18,"concept":"K5-1-u3-C6","difficulty":3,"kind":"mc","stem":"지슬이의 발표를 들을 사람이 마을 어르신들이라면 준비에서 무엇을 더 생각해야 할까요?","options":[{"t":"어르신들이 궁금해할 내용과 잘 보이는 큰 글씨의 자료","correct":true},{"t":"듣는 사람은 생각할 필요가 없다","mis":"K5-1-u3-X05"},{"t":"어려운 낱말을 더 많이 쓴다","mis":"K5-1-u3-X17"},{"t":"화면에 글을 더 빽빽하게 넣는다","mis":"K5-1-u3-X24"}],"explanation":["듣는 사람에 따라 자료가 달라져요.","쉬운 말로 바꾸어요.","한 화면에 한 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#19','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C41',3,'mc','auto','한율이가 려원이를 따라 물병을 들고 온 까닭을 짐작할 단서로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u3-X39','K5-1-u3-X41']::text[],false,'{"seq":19,"concept":"K5-1-u3-C41","difficulty":3,"kind":"mc","stem":"한율이가 려원이를 따라 물병을 들고 온 까닭을 짐작할 단서로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"려원이가 전학 간 친구와 한 약속을 들은 바로 다음 날 물병을 들고 왔다","correct":true},{"t":"창틀이 교실 끝에 있다","mis":"K5-1-u3-X39"},{"t":"봄 방학이 다가왔다","mis":"K5-1-u3-X39"},{"t":"화분에 꽃봉오리가 없었다","mis":"K5-1-u3-X41"}],"explanation":["배경이에요.","때를 알려 줄 뿐이에요.","약속을 들은 뒤 행동이 달라졌어요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#20','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C29',3,'error','auto','지슬이의 발표를 듣고 친구들이 말해 준 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u3-X28','K5-1-u3-X19']::text[],false,'{"seq":20,"concept":"K5-1-u3-C29","difficulty":3,"kind":"error","stem":"지슬이의 발표를 듣고 친구들이 말해 준 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘한 점은 빼고 틀린 것만 알려 줄게.」","correct":true,"mis_target":"K5-1-u3-X28"},{"t":"「새 떼 영상 덕분에 날아오르는 모습이 한눈에 보였어.」","mis":"K5-1-u3-X28"},{"t":"「큰고니 사진에 출처를 적으면 더 좋겠어.」","mis":"K5-1-u3-X19"}],"explanation":["좋았던 점을 말했어요.","아쉬운 점을 말했어요.","좋았던 점과 아쉬운 점을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#21','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C36',3,'mc','auto','「만약」을 알맞게 넣어 지슬이에게 한 질문은 어느 것인가요?',ARRAY['K5-1-u3-X34']::text[],false,'{"seq":21,"concept":"K5-1-u3-C36","difficulty":3,"kind":"mc","stem":"「만약」을 알맞게 넣어 지슬이에게 한 질문은 어느 것인가요?","options":[{"t":"「만약 저수지가 꽁꽁 언다면 철새들은 어디로 가나요?」","correct":true},{"t":"「만약 철새 쉼터는 어디에 있나요?」","mis":"K5-1-u3-X34"},{"t":"「만약 큰고니는 무슨 색인가요?」","mis":"K5-1-u3-X34"},{"t":"「만약 발표는 누가 했나요?」","mis":"K5-1-u3-X34"}],"explanation":["「어디에」로 물으면 돼요.","「무슨」으로 물으면 돼요.","「만약」으로 다른 경우를 짚었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#22','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C19',3,'mc','auto','지슬이가 고친 발표 자료를 검토할 때 살필 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u3-X18','K5-1-u3-X19']::text[],false,'{"seq":22,"concept":"K5-1-u3-C19","difficulty":3,"kind":"mc","stem":"지슬이가 고친 발표 자료를 검토할 때 살필 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"화면의 바탕색이 지슬이가 좋아하는 색인지","correct":true},{"t":"주제에 맞는 자료인지","mis":"K5-1-u3-X18"},{"t":"글의 양이 알맞은지","mis":"K5-1-u3-X18"},{"t":"출처를 밝혔는지","mis":"K5-1-u3-X19"}],"explanation":["살펴야 해요.","살펴야 해요.","좋아하는 색은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#23','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C32',4,'essay','teacher','「창틀의 화분」을 읽고 려원이나 한율이에게 질문의 세 가지 목적에 맞는 질문을 하나씩 만들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u3-C32","difficulty":4,"kind":"essay","stem":"「창틀의 화분」을 읽고 려원이나 한율이에게 질문의 세 가지 목적에 맞는 질문을 하나씩 만들어 쓰세요.","answer_guide":{"answer":"예: 의도를 파악하는 질문 — 「려원아, 처음에 「그냥 내가 주는 거야」라고만 말한 까닭은 무엇이니?」 명료하게 이해하는 질문 — 「한율아, 「둘이 주면 더 빨리 필까 해서」는 어떤 뜻이었니?」 대안이나 정보를 찾는 질문 — 「려원아, 친구에게 꽃 사진 말고 무엇을 더 보내 줄 수 있을까?」","scoring_points":["세 목적에 맞는 질문을 하나씩 썼는가","누구에게 묻는지 밝혔는가","이야기 안에서 생각해 볼 수 있는 질문인가"]},"explanation":["까닭을 묻는 질문이에요.","뜻을 묻는 질문이에요.","방법을 구하는 질문이에요."],"asset":{"type":"passage","lines":["봄 방학을 앞둔 날, 려원이가 먼저 말했다.","「작년에 같은 반이던 친구가 전학 가면서 두고 간 거야.","　꽃이 피면 사진 찍어 보내 준다고 했어.」","화분에는 아직 꽃봉오리 하나 없었다.","다음 날 아침, 창틀 앞에는 물병을 든 한율이가 서 있었다.","「둘이 주면 더 빨리 필까 해서.」 려원이는 아무 말 없이 웃었다.","한 달쯤 지나 화분에 작은 노란 꽃이 피었다.","그날 려원이는 사진을 두 장 찍었다."],"title":"이야기 「창틀의 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#24','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C48',4,'essay','teacher','「우리 학교 급식 남기지 않기」처럼 학교생활과 관련된 조사 주제를 하나 정하고, 그 주제가 조사할 만한 까닭과 알맞은 조사 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u3-C48","difficulty":4,"kind":"essay","stem":"「우리 학교 급식 남기지 않기」처럼 학교생활과 관련된 조사 주제를 하나 정하고, 그 주제가 조사할 만한 까닭과 알맞은 조사 방법을 쓰세요.","answer_guide":{"answer":"예: 주제 — 우리 학교 급식 남기지 않기. 직접 관찰하거나 영양 선생님을 면담해 자료를 구할 수 있고, 친구들이 음식을 아끼는 데 도움이 되기 때문에 조사할 만하다. 조사 방법 — 일주일 동안 급식 뒤 남은 음식을 관찰하고, 영양 선생님께 면담한다.","scoring_points":["조사 주제를 하나 정했는가","자료를 구할 수 있고 도움이 된다는 까닭을 썼는가","주제에 맞는 조사 방법을 썼는가"]},"explanation":["자료를 구할 수 있나요?","친구들에게 도움이 되나요?","답이 있을 곳을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u3_review_d#25','kor',5,1,'u3','','g5_1_kor_u3_review_d','unit_review','K5-1-u3-C44',4,'essay','teacher','「담 너머」를 읽고 고양이나 나비에게 할 질문을 두 개 만들고, 각 질문의 목적과 그 질문이 글 안에서 생각해 볼 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u3-C44","difficulty":4,"kind":"essay","stem":"「담 너머」를 읽고 고양이나 나비에게 할 질문을 두 개 만들고, 각 질문의 목적과 그 질문이 글 안에서 생각해 볼 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 나비에게 — 「대부분의 담은 내가 세우게 된다는 말은 어떤 뜻인가요?」 목적: 명료하게 이해하기 위해서. 나비의 말에 담긴 뜻을 글 전체에서 생각해 볼 수 있다. 고양이에게 — 「이웃들 말과 달리 담을 넘기로 한 까닭은 무엇인가요?」 목적: 의도를 파악하기 위해서. 고양이가 늘 궁금해했다는 글의 내용에서 생각해 볼 수 있다.","scoring_points":["질문을 두 개 만들었는가","각 질문의 목적을 썼는가","글 안에서 생각해 볼 수 있는 까닭을 썼는가"]},"explanation":["인물의 말과 행동에서 궁금한 곳을 찾아요.","목적을 밝혀요.","글과 이어 까닭을 써요."],"asset":{"type":"passage","lines":["담 아래에서 자란 어린 고양이는 담 너머가 늘 궁금했다. 늙은 개는","위험하다고, 참새는 관심 없다고, 두더지는 아무것도 없다고 했다.","어느 날 담 위에 앉은 나비가 말했다. 「내 등에 올라타 봐.」","담을 넘은 고양이는 처음 보는 빛깔의 들판에 눈이 휘둥그레졌다.","「다들 껌껌하다고 했는데.」","「그 친구들은 무서워하며 봤고, 너는 궁금해하며 봤으니까.」","「앞으로도 담은 많을 거야. 남이 세운 담도 있지만,","　대부분은 네가 세우게 될 거야.」"],"title":"짧은 글 「담 너머」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
